INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('actas_despachos','pantalla','actas_despachos','Actas & Despachos','Actas de entrega y de recepción de los equipos alquilados.','["operaciones-app/src/zahory-mock/pages/flota/ActasDespachosPage.jsx#ActasDespachosPage"]'::jsonb,'b0f416afdf')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actas_despachos',1,'actas_despachos',NULL,NULL,'Emite un acta con Crear acta. Cargar checklist sugerido trae una lista base de puntos a revisar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actas_despachos',2,'actas_despachos',NULL,NULL,'Marca cada punto como Conforme u Observado y avanza con Avanzar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actas_despachos',3,'actas_despachos',NULL,NULL,'Guardar borrador conserva el acta para seguirla con Continuar acta. Confirmar acta la cierra.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actas_despachos',4,'actas_despachos',NULL,NULL,'Anular acta deja sin efecto un acta emitida.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actas_despachos',5,'actas_despachos',NULL,NULL,'Para qué sirve: el acta deja constancia, con checklist, fotos y firmas, del estado en que un equipo alquilado se entrega al cliente o se recibe de vuelta. Es la evidencia ante un reclamo por daños.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actas_despachos',6,'actas_despachos',NULL,NULL,'El acta avanza por pasos. En el checklist cada punto se marca Conforme u Observado; si lo marcas Observado debes describir la observación. Puedes agregar puntos propios y fotos, y con Guardar borrador sigues después.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actas_despachos',7,'actas_despachos',NULL,NULL,'No se puede despachar un equipo con certificaciones obligatorias vencidas: la pantalla pide renovarlas primero en Certificaciones del Activo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actas_despachos',8,'actas_despachos',NULL,NULL,'Confirmar acta la cierra con sus firmas; Volver a firmar permite rehacer una firma antes de confirmar. Anular acta deja sin efecto un acta ya emitida.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actas_despachos',9,'actas_despachos',NULL,NULL,'En Evidencia puedes adjuntar documentos PDF opcionales de hasta 10 MB por archivo. Después de guardar el acta, abre el documento desde el enlace en su detalle.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actas_despachos',10,'actas_despachos',NULL,NULL,'Al elegir enlazar una guía de remisión, si falla la carga de guías se muestra el mensaje «No se pudieron cargar las guías» con el detalle del error.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actas_despachos',11,'actas_despachos',NULL,NULL,'Activar y Desactivar, en el catálogo de puntos del checklist, solo aparecen si tu rol tiene el permiso de editar actas.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('actividades','pantalla','actividades','Actividades','Registro de las actividades comerciales: llamadas, visitas y reuniones.','["src/pages_core.jsx#Actividades"]'::jsonb,'a926023fb3')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actividades',1,'actividades',NULL,NULL,'Registra una actividad con Nueva actividad y Guardar actividad.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actividades',2,'actividades',NULL,NULL,'Puedes verlas en Kanban o en Lista y acotar con Filtros.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actividades',3,'actividades',NULL,NULL,'Para qué sirve: dejar constancia de cada contacto con un cliente o prospecto (llamada, visita, reunión, correo) para saber qué se habló y qué sigue. Los leads sin actividad reciente se marcan como desatendidos a partir de este registro.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actividades',4,'actividades',NULL,NULL,'Nueva actividad pide el tipo, con quién fue (lead, cuenta u oportunidad), la fecha y un resumen; Guardar actividad la registra. La vista Kanban las agrupa por estado y la Lista las muestra en tabla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('actividades',5,'actividades',NULL,NULL,'Si no aparece una actividad que registraste, revisa los Filtros de fecha y de responsable. Si no puedes registrar, tu rol no tiene permiso de crear en Actividades.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('activos_fijos','pantalla','activos_fijos','Activos Fijos','Registro de los activos fijos de la empresa, sus documentos y su baja.','["src/pages_fin.jsx#ActivosFijos"]'::jsonb,'ba438c208f')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('activos_fijos',1,'activos_fijos',NULL,NULL,'Registra un activo con Nuevo activo indicando nombre, fecha, valor y vida útil. Nuevo activo (Compras) lo registra además como compra en Compras / Gastos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('activos_fijos',2,'activos_fijos',NULL,NULL,'Agregar doc adjunta documentos al activo y Editar cambia sus datos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('activos_fijos',3,'activos_fijos',NULL,NULL,'Promover al Maestro lleva el activo al maestro de la empresa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('activos_fijos',4,'activos_fijos',NULL,NULL,'Dar de baja retira el activo: debes indicar el motivo y confirmar con Confirmar baja.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('activos_fijos',5,'activos_fijos',NULL,NULL,'Para qué sirve: llevar el inventario de los bienes de la empresa (equipos, vehículos, maquinaria, mobiliario) con su valor, su vida útil y sus documentos. De aquí salen la depreciación que usa el costeo y los equipos que se asignan a órdenes y alquileres.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('activos_fijos',6,'activos_fijos',NULL,NULL,'Crear activo guarda el activo nuevo; pide código y nombre, y para depreciarlo, fecha de alta, valor de adquisición y vida útil. Descargar plantilla baja el Excel para cargar muchos activos de una vez.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('activos_fijos',7,'activos_fijos',NULL,NULL,'No deja dar de baja un activo sin indicar el motivo. Si un activo no aparece en la Hoja de Costeo con costo por hora, revisa que tenga valor, vida útil y horas disponibles al mes.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('agenda_comercial','pantalla','agenda_comercial','Agenda Comercial','Calendario de reuniones y visitas del equipo comercial.','["src/pages_core.jsx#AgendaComercial"]'::jsonb,'37a93e9e93')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('agenda_comercial',1,'agenda_comercial',NULL,NULL,'Agenda una reunión o visita con Nuevo evento y Crear evento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('agenda_comercial',2,'agenda_comercial',NULL,NULL,'Cambia la vista entre Día, Semana, Mes y Lista; Hoy vuelve a la fecha actual.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('agenda_comercial',3,'agenda_comercial',NULL,NULL,'Cuando el evento ocurre usa Marcar realizado y crear actividad: queda como realizado y se registra la actividad comercial.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('agenda_comercial',4,'agenda_comercial',NULL,NULL,'Eliminar evento lo borra y no se puede deshacer; solo aparece si tu rol puede eliminar eventos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('agenda_comercial',5,'agenda_comercial',NULL,NULL,'Para qué sirve: programar las reuniones y visitas del equipo comercial y ver la semana de cada vendedor. Un evento realizado se convierte en actividad, así el historial del cliente queda completo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('agenda_comercial',6,'agenda_comercial',NULL,NULL,'Si no ves Eliminar evento, tu rol no tiene permiso para eliminar eventos. Si no aparece un evento, revisa la vista elegida y usa Hoy para volver a la fecha actual.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('inventario_admin','pantalla','inventario','Almacenes','Existencias, entradas, ajustes, transferencias y conteos del almacén desde Administración.','["src/pages_extra.jsx#Inventario"]'::jsonb,'71bf749470')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_admin',1,'inventario',NULL,NULL,'Registrar Entrada ingresa material al almacén; Primera Entrada registra el stock inicial de un material.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_admin',2,'inventario',NULL,NULL,'Ajustar corrige una diferencia de stock y Transferir mueve material entre almacenes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_admin',3,'inventario',NULL,NULL,'Iniciar Conteo abre un conteo físico: Escanear lee los códigos, Guardar avance permite continuar después y Cerrar Conteo genera los ajustes. Un código que no pertenece al conteo se rechaza.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_admin',4,'inventario',NULL,NULL,'Generar SOLPE crea la solicitud de compra y la envía a Compras.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_admin',5,'inventario',NULL,NULL,'Para qué sirve: controlar desde Administración qué hay en cada almacén y registrar lo que entra, se ajusta o se mueve. El almacén del taller se opera con más detalle en la aplicación de Operaciones (ubicaciones, reservas y despachos); aquí está la vista de existencias y los movimientos básicos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_admin',6,'inventario',NULL,NULL,'Si no aparece un material para ingresarlo, primero debe existir en el maestro de materiales. No deja cerrar un conteo con códigos que no le pertenecen. Si el stock no cuadra con lo físico, usa Iniciar Conteo en lugar de varios ajustes sueltos: el conteo deja el historial de la diferencia.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('analisis_sos','pantalla','analisis_sos','Análisis SOS','Muestras de aceite, resultados por elemento y seguimiento de condiciones de alerta o críticas.','["operaciones-app/src/zahory-mock/pages/confiabilidad/AnalisisSosPage.jsx#AnalisisSosPage"]'::jsonb,'5dc3598e36')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('analisis_sos',1,'analisis_sos','ver',NULL,'Para qué sirve: registrar las muestras de aceite que se envían al laboratorio y sus resultados, para detectar desgaste o contaminación antes de que el equipo falle. Cada resultado se compara con límites de alerta y crítico; un resultado crítico genera automáticamente un hallazgo en el backlog para atenderlo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('analisis_sos',2,'analisis_sos','ver',NULL,'SOS significa Scheduled Oil Sampling: análisis de aceite programado. En Muestras consulta y filtra por condición, estado, segmento y sistema, o busca una muestra.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('analisis_sos',3,'analisis_sos','crear',NULL,'Usa Nueva muestra, completa los datos del equipo, sistema y muestra solicitados y pulsa Guardar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('analisis_sos',4,'analisis_sos','editar',NULL,'Usa Cargar resultados para ingresar la fecha y los valores por elemento y adjuntar el Informe PDF. También puedes usar Importar CSV o XLSX con el archivo del laboratorio, revisar la previsualización y pulsar Aplicar valores reconocidos antes de Guardar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('analisis_sos',5,'analisis_sos','ver',NULL,'Los resultados se comparan con límites de alerta y crítico. Los límites son orientativos y deben validarse para cada aplicación; consulta el detalle y la condición prevista antes de guardar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('analisis_sos',6,'analisis_sos','editar',NULL,'En Límites consulta los límites globales y de la empresa; usa Nuevo límite propio, Crear límite propio o Editar cuando corresponda y guarda los cambios.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('analisis_sos',7,'analisis_sos','ver',NULL,'Una condición crítica crea un hallazgo de backlog automáticamente. Para una muestra en alerta sin hallazgo, Crear backlog está disponible si tienes permiso para crear backlog; el botón Backlog abre su seguimiento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('analisis_sos',8,'analisis_sos','editar',NULL,'En el detalle de una muestra usa Abrir informe PDF para ver el informe del laboratorio adjunto y Marcar revisada cuando ya analizaste el resultado. Si la muestra generó un hallazgo, Ver backlog te lleva al Backlog operativo para darle seguimiento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('analisis_sos',9,'analisis_sos','ver',NULL,'Usa Detalle para revisar resultados e historial. Si no encuentras una muestra, revisa filtros y segmento; si falta una acción, revisa la empresa y solicita los permisos correspondientes.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('api_keys','pantalla','api_keys','API Keys','Llaves de acceso para integrar otros sistemas con el ERP.','["src/pages_api_keys.jsx#ApiKeys"]'::jsonb,'e7d844db55')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('api_keys',1,'api_keys',NULL,NULL,'Crea una llave con Nuevo API Key y Crear API Key.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('api_keys',2,'api_keys',NULL,NULL,'La llave se muestra una sola vez: cópiala con Copiar y confirma con Entendido, ya lo guardé.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('api_keys',3,'api_keys',NULL,NULL,'Editar permisos cambia lo que la llave puede hacer.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('api_keys',4,'api_keys',NULL,NULL,'Revocar key la desactiva de forma irreversible.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('api_keys',5,'api_keys',NULL,NULL,'Para qué sirve: dar acceso controlado al ERP a otros sistemas (una web, un formulario, un tablero), cada uno con su propia llave y solo con los permisos que necesita. Si una llave se filtra, se revoca sin afectar a las demás.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('api_keys',6,'api_keys',NULL,NULL,'Guardar permisos conserva los cambios hechos con Editar permisos. Al copiar la llave, el botón cambia a Copiado para confirmar que ya está en el portapapeles.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('api_keys',7,'api_keys',NULL,NULL,'Si no guardaste la llave al crearla, no se puede volver a ver: revócala y crea otra. No aparece esta pantalla si tu rol no administra integraciones. Una llave revocada no se reactiva.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('backlog_operativo','pantalla','backlog','Backlog operativo','Hallazgos y necesidades de mantenimiento hasta su atención en una orden de trabajo.','["operaciones-app/src/zahory-mock/pages/confiabilidad/BacklogOperativoPage.jsx#BacklogOperativoPage"]'::jsonb,'d7e7793323')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('backlog_operativo',1,'backlog','ver',NULL,'Para qué sirve: aquí se anotan y priorizan los hallazgos de mantenimiento de cada equipo (una fuga, un desgaste, un resultado de aceite crítico, un PM vencido) desde que se detectan hasta que se atienden en una OT, para que nada se pierda y se trabaje primero lo más crítico. Se usa a diario por supervisores y planificadores de mantenimiento de flota, taller y equipos de clientes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('backlog_operativo',2,'backlog','ver',NULL,'Consulta los hallazgos de Flota en alquiler, Máquinas de taller y Equipos de clientes. Selecciona Todos, Flota, Taller o Cliente para acotar los indicadores y la lista.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('backlog_operativo',3,'backlog','ver',NULL,'Usa Lista o Tablero, la búsqueda por equipo o descripción y los filtros Ciclo, Prioridad, Fuente y Sistema. Los cerrados y descartados se muestran en Lista.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('backlog_operativo',4,'backlog','crear',NULL,'Usa Nuevo hallazgo, indica descripción, impacto y urgencia, y completa los demás datos disponibles; selecciona un equipo si luego necesitarás crear una OT. Pulsa Guardar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('backlog_operativo',5,'backlog','ver',NULL,'El puntaje es impacto × urgencia: emergencia desde 20, urgente desde 12, programable desde 6 y baja por debajo de 6.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('backlog_operativo',6,'backlog','editar',NULL,'Abre un hallazgo y usa Evaluar, Pendiente de recursos o Listo para OT según corresponda. El ciclo va de nuevo a evaluado, pendiente de recursos, listo para OT, en OT y cerrado; también puede descartarse con un motivo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('backlog_operativo',7,'backlog','editar',NULL,'Crear OT lleva el hallazgo a Nueva OT. Aparece para un hallazgo evaluado o listo para OT, con equipo y sin OT asociada; completa y crea la orden allí.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('backlog_operativo',8,'backlog','editar',NULL,'Para Descartar indica el motivo y usa Confirmar descarte. Reabrir devuelve un hallazgo cerrado o descartado a nuevo. Guarda o descarta cambios antes de cambiar el ciclo o crear la OT.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('backlog_operativo',9,'backlog','editar',NULL,'En el detalle, si el hallazgo aún no tiene equipo verás Sin equipo: elige el equipo antes de crear la OT. Si cambiaste datos y quieres volver atrás usa Descartar cambios. Cuando el hallazgo ya está en una OT, Ver OT en bandeja abre la bandeja de órdenes para seguir su avance.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('backlog_operativo',10,'backlog','ver',NULL,'Si no aparece un hallazgo, revisa el segmento, la búsqueda y los filtros. Si falta un botón o aparece un aviso de permiso, revisa la empresa y solicita acceso para ver, crear o editar según la acción.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('backlog','pantalla','backlog','Backlog','Consulta de requerimientos de Administración; el backlog se gestiona en Operaciones.','["src/pages_ops.jsx#Backlog"]'::jsonb,'d348b762df')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('backlog',1,'backlog',NULL,NULL,'Para qué sirve: dar a Administración una vista de consulta de los requerimientos y hallazgos pendientes de la empresa, sin modificarlos. La gestión del backlog (registrar, priorizar, cambiar el ciclo y llevarlo a una OT) se hace en Operaciones › Confiabilidad › Backlog operativo, donde trabajan los equipos de mantenimiento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('backlog',2,'backlog',NULL,NULL,'Esta vista de Administración es solo de consulta. Revisa los requerimientos en Kanban o Lista y usa la búsqueda para encontrar uno por descripción, cuenta o servicio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('backlog',3,'backlog',NULL,NULL,'En la vista Lista, además del servicio, la cuenta, el monto, la prioridad, la fecha y el estado, se muestran el Equipo, el Ciclo (nuevo, evaluado, pendiente de recursos, listo para OT, en OT, cerrado o descartado) y la Prioridad calculada que se registraron en Operaciones. Un valor que no se registró aparece como Sin dato.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('backlog',4,'backlog',NULL,NULL,'Para registrar o gestionar hallazgos y llevarlos a una OT, usa Ir a Operaciones y entra a Confiabilidad › Backlog operativo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('backlog',5,'backlog',NULL,NULL,'Si no puedes gestionar un hallazgo en Operaciones, revisa la empresa y solicita los permisos de backlog necesarios.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('backlog',6,'backlog',NULL,NULL,'Si un requerimiento no aparece, revisa la búsqueda y la vista Kanban o Lista. Si necesitas cambiar algo y no encuentras cómo hacerlo aquí, es porque esta pantalla es solo de consulta: usa Ir a Operaciones.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('bandeja_ots','pantalla','ot','Bandeja de OTs','Lista todas las órdenes de trabajo con sus indicadores, filtros y búsqueda, y permite iniciar una OT programada.','["operaciones-app/src/zahory-mock/pages/pages2_v2.jsx#OTsListadoPage"]'::jsonb,'b22cbde9d1')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('bandeja_ots',1,'ot',NULL,NULL,'Los indicadores de arriba (abiertas, programadas, en ejecución, sin técnico, por valorizar, con sobrecosto) filtran la lista al tocarlos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('bandeja_ots',2,'ot',NULL,NULL,'Busca por número, cliente o servicio y filtra por estado o técnico. Solo retrabajos muestra las OT de retrabajo propio. Limpiar quita todos los filtros.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('bandeja_ots',3,'ot',NULL,NULL,'Para iniciar una OT programada usa Iniciar en su fila: la OT debe tener técnico responsable y centro de costo, y necesitas una sociedad operativa seleccionada (la vista consolidada es solo de lectura).');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('bandeja_ots',4,'ot',NULL,NULL,'Nueva OT abre el asistente de creación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('bandeja_ots',5,'ot',NULL,NULL,'Para qué sirve: ver todas las órdenes de trabajo del taller y de campo con su estado, su responsable y su fecha, para saber qué está en marcha, qué falta iniciar y qué va atrasado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('bandeja_ots',6,'ot',NULL,NULL,'La lista se pagina: Sig. pasa a la página siguiente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('bandeja_ots',7,'ot',NULL,NULL,'No deja iniciar una OT sin técnico responsable ni sin centro de costo: asígnalos primero. Si avisa que la vista es de solo lectura, elige una sociedad operativa en el selector. Si dice que la OT ya no está programada, alguien la inició o la cambió: actualiza la bandeja.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('sourcing_bandeja','pantalla','ordenes_compra','Bandeja de Sourcing','Reparte los materiales de las SOLPE aprobadas entre proveedores, línea por línea, y genera una orden de compra por proveedor.','["src/pages_ops.jsx#BandejaSourcing"]'::jsonb,'59f4c3339c')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('sourcing_bandeja',1,'ordenes_compra',NULL,NULL,'Para qué sirve: aquí llegan las líneas de las SOLPE aprobadas que aún no tienen orden de compra. Permite comprar una misma SOLPE a varios proveedores, o juntar líneas de varias SOLPE en una sola orden. Está en Compras › Bandeja de Sourcing y también se abre con Generar OC desde la SOLPE.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('sourcing_bandeja',2,'ordenes_compra',NULL,NULL,'Filtra por Familia, SOLPE de origen, Estado de campo o Comprador de campo, y usa Actualizar para recargar la bandeja.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('sourcing_bandeja',3,'ordenes_compra',NULL,NULL,'Asigna un proveedor a cada línea. Los marcados como «sugerido» son los habilitados para la familia de ese material; con + Otro proveedor buscas cualquier otro. Si eliges uno que no está habilitado para esa familia, la pantalla pregunta si es Solo esta compra o si quieres Habilitar para esta familia en adelante.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('sourcing_bandeja',4,'ordenes_compra',NULL,NULL,'Las líneas asignadas se agrupan en una columna por proveedor con su total. Generar OC crea la orden de compra de ese proveedor con sus líneas; repítelo por cada proveedor. Quitar proveedor devuelve la línea a la bandeja.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('sourcing_bandeja',5,'ordenes_compra',NULL,NULL,'Una línea «en campo» la tomó un comprador de campo para comprarla en persona: mientras tanto no se le puede asignar proveedor. Quitar al comprador la libera, previa confirmación, porque esa persona podría estar comprándola en ese momento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('sourcing_bandeja',6,'ordenes_compra',NULL,NULL,'Si un proveedor no entregará parte de una orden, Liberar pendiente en la orden de compra devuelve ese saldo a esta bandeja para comprarlo a otro proveedor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('sourcing_bandeja',7,'ordenes_compra',NULL,NULL,'Si no aparece una línea, revisa que su SOLPE esté aprobada y que no tenga ya orden de compra. No deja asignar proveedor a una línea «en campo» hasta quitársela al comprador. Si no ves un proveedor entre los sugeridos, no está habilitado para la familia de ese material: búscalo con + Otro proveedor.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('bi_cs','pantalla','bi_cs','BI Customer Success','Indicadores de retención, salud y crecimiento de los clientes.','["src/pages_cs.jsx#BICustomerSuccess"]'::jsonb,'41eae9e552')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('bi_cs',1,'bi_cs',NULL,NULL,'Es un tablero de consulta: clientes saludables, clientes en riesgo, health score promedio y NPS promedio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('bi_cs',2,'bi_cs',NULL,NULL,'También muestra los onboardings en curso y las renovaciones próximas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('bi_cs',3,'bi_cs',NULL,NULL,'Exportar descarga la información.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('bi_cs',4,'bi_cs',NULL,NULL,'Para qué sirve: mostrar a gerencia cómo está la relación con los clientes: cuántos están sanos, cuántos en riesgo de irse y qué renovaciones vienen, para actuar antes de perder una cuenta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('bi_cs',5,'bi_cs',NULL,NULL,'Los indicadores se calculan con lo registrado en Health Score, Fidelización y NPS, Onboarding y Renovaciones.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('bi_cs',6,'bi_cs',NULL,NULL,'Si no ves datos, aún no hay registros en esas pantallas. Si no aparece un cliente, revisa que su cuenta esté activa.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('caja','pantalla','caja','Caja Chica','Administra fondos de caja chica, sus egresos, aportes, rendiciones, arqueos y el cierre del fondo con saldo cero; permite editar y anular egresos y anular aportes desde el historial del fondo.','["src/pages_fin.jsx#CajaChica","src/components/NuevoEgreso.jsx#NuevoEgreso","src/components/CerrarFondoModal.jsx#CerrarFondoModal","src/services/cajaChicaService.js"]'::jsonb,'99d34ba223 2c804b78dc e7344f6212 5c04bfa6a6')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',1,'caja','caja','crear','Usa Nuevo fondo para crear un fondo con su responsable, importe, moneda y origen del dinero (cuenta bancaria o aporte directo). Mientras el fondo no tenga movimientos se puede modificar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',2,'caja',NULL,NULL,'Usa Nuevo egreso para registrar un gasto del fondo. El asistente tiene tres pasos: elige el tipo de gasto (puedes buscar por tipo o por categoría del Estado de Resultados), completa los datos del comprobante y del fondo, y revisa antes de confirmar. Lo puede registrar el responsable del fondo o quien tenga permiso de crear en Caja Chica.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',3,'caja',NULL,NULL,'En el paso de datos del egreso la categoría del Estado de Resultados es obligatoria y editable; la IA puede sugerirla a partir del tipo de gasto y la descripción. Adjunta el comprobante y vincula la OT si corresponde.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',4,'caja',NULL,NULL,'Usa Agregar aporte para reforzar el fondo con dinero de una cuenta bancaria o con un aporte directo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',5,'caja',NULL,NULL,'Usa Solicitar rendición para presentar los egresos del periodo; la solicitud queda disponible para revisión.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',6,'caja','caja','aprobar','Revisa la rendición y usa Aprobar o Rechazar para continuar con la reposición del fondo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',7,'caja',NULL,NULL,'Usa Arqueo y luego Registrar arqueo con el efectivo contado; revisa las diferencias que muestra la pantalla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',8,'caja','caja','editar','Usa Cerrar para cerrar el fondo. Ningún fondo puede cerrar con saldo a favor: transfiere el saldo a otra caja abierta de la misma moneda y sociedad, o devuélvelo a una cuenta bancaria activa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',9,'caja',NULL,NULL,'Para corregir un egreso abre el fondo y, en Historial > Egresos, usa el botón Editar que aparece bajo el estado de la fila; se abre una ventana donde puedes cambiar concepto, categoría del Estado de Resultados, centro de costo, número de comprobante y fecha. El monto no se edita; si está mal, anula el egreso y regístralo de nuevo. Lo puede hacer el responsable del fondo o quien tenga permiso de editar en Caja Chica, solo si el egreso está registrado y no cae en una rendición solicitada, aprobada o repuesta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',10,'caja',NULL,NULL,'Para anular un egreso o un aporte usa el botón Anular que aparece bajo el estado de la fila en Historial e indica el motivo en la ventana que se abre. Un egreso anulado devuelve su monto al saldo y deja de contar en el Estado de Resultados. Un aporte solo lo anula quien tenga permiso de editar o anular en Caja Chica y siempre que el saldo del fondo no quede negativo; si vino de una cuenta bancaria, Tesorería registra el ingreso de reversión. Los anulados quedan visibles con su motivo. Cuando una fila no tiene botones, debajo de su estado se indica por qué: egreso incluido en una rendición (con su periodo), reposición que viene de una rendición aprobada o movimiento ya anulado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',11,'caja',NULL,NULL,'Para corregir los datos de un fondo usa Editar fondo y Guardar cambios. Eliminar fondo lo borra con confirmación y no se puede deshacer; un fondo que ya tiene movimientos no se puede eliminar. En un egreso, Subir adjunto carga el comprobante y Descargar lo baja.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',12,'caja',NULL,NULL,'Al abrir un fondo, la tarjeta Asignado muestra el total que entró al fondo y, debajo, su detalle: apertura, aportes vigentes, transferencias recibidas de otras cajas y reposiciones. Los aportes anulados no suman. Disponible es ese total menos los egresos y las transferencias enviadas. En Historial, las transferencias entre cajas aparecen en Ingresos (recibidas) o en Egresos (enviadas) y no se editan.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',13,'caja',NULL,NULL,'Para qué sirve: manejar el dinero en efectivo que se entrega a un responsable para gastos menores, con control de cada egreso, su comprobante y el saldo. Cada egreso queda también en Compras y Gastos, y el fondo se cierra siempre en cero.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('caja',14,'caja',NULL,NULL,'Registrar aporte suma dinero al fondo a mitad de período. Subir otro adjunto agrega un comprobante más a un egreso. En el asistente de egreso, Revisar pasa al paso final donde se comprueban los datos antes de guardar. Al cerrar un fondo con saldo, la pantalla obliga a elegir entre Transferir a otra caja o Devolver a cuenta bancaria, y Confirmar cierre lo deja en cero.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('servicios','pantalla','servicios','Catalogo Servicios','Catálogo de los servicios que la empresa vende y cotiza.','["src/pages_admin.jsx#Servicios"]'::jsonb,'fb5e7f9dc7')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('servicios',1,'servicios',NULL,NULL,'Crea un servicio con Nuevo servicio. Si la familia no existe, Crear y seleccionar la crea en el momento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('servicios',2,'servicios',NULL,NULL,'Marca Recurrente mensual en los servicios que se cobran todos los meses.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('servicios',3,'servicios',NULL,NULL,'Para cargar muchos servicios descarga la Plantilla y usa Importar Excel; solo se importan las filas válidas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('servicios',4,'servicios',NULL,NULL,'Eliminar borra un servicio y pide confirmación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('servicios',5,'servicios',NULL,NULL,'Para qué sirve: definir una sola vez los servicios que la empresa vende, con su familia y su precio de referencia, para que cotizaciones, órdenes de servicio y órdenes de trabajo usen los mismos nombres y se pueda medir cuánto se vende de cada uno.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('servicios',6,'servicios',NULL,NULL,'Guardar cambios conserva la edición de un servicio. En la carga masiva, Importar filas válidas crea las que pasaron la revisión y Subir otro archivo reemplaza el Excel elegido. Limpiar filtros quita los filtros de la lista.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('servicios',7,'servicios',NULL,NULL,'Si no aparece un servicio al cotizar, revisa que exista aquí y esté activo. No deja importar hasta que carguen las familias. Si no aparece la familia que necesitas, créala desde el mismo formulario.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('catalogo_venta','pantalla','inventario','Catálogo de venta','Productos del almacén que se ofrecen a la venta.','["operaciones-app/src/zahory-mock/pages/wms/CatalogoVentaPage.jsx#CatalogoVentaPage"]'::jsonb,'7819c0b8aa')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('catalogo_venta',1,'inventario',NULL,NULL,'Agregar producto suma un material del almacén al catálogo con Agregar al catálogo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('catalogo_venta',2,'inventario',NULL,NULL,'Un producto que ya está en el catálogo se puede editar con Guardar cambios.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('catalogo_venta',3,'inventario',NULL,NULL,'Para qué sirve: elegir cuáles materiales del almacén se ofrecen a la venta, para que las órdenes de venta y las cotizaciones de repuestos tomen de aquí sus productos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('catalogo_venta',4,'inventario',NULL,NULL,'Un material puede estar en el almacén sin estar en el catálogo: mientras no se agregue, no se puede vender por orden de venta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('catalogo_venta',5,'inventario',NULL,NULL,'Si no aparece un producto al armar una orden de venta, agrégalo aquí primero. Si no aparece el material para agregarlo, debe existir antes en el maestro de materiales.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('certificaciones_activo','pantalla','certificaciones_activo','Certificaciones del Activo','Certificaciones de los equipos y su renovación.','["operaciones-app/src/zahory-mock/pages/flota/CertificacionesActivoPage.jsx#CertificacionesActivoPage"]'::jsonb,'e36b54098c')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('certificaciones_activo',1,'certificaciones_activo',NULL,NULL,'Registrar certificación anota una certificación de un equipo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('certificaciones_activo',2,'certificaciones_activo',NULL,NULL,'Renovar registra su renovación y Anular la deja sin efecto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('certificaciones_activo',3,'certificaciones_activo',NULL,NULL,'Catálogo de tipos define los tipos de certificación: Nuevo tipo crea uno y Cargar tipos sugeridos trae una lista base.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('certificaciones_activo',4,'certificaciones_activo',NULL,NULL,'Para qué sirve: controlar los documentos que cada equipo necesita para operar (SOAT, revisión técnica, pólizas, certificados) y su fecha de vencimiento. Un equipo con una certificación obligatoria vencida no se puede despachar en un acta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('certificaciones_activo',5,'certificaciones_activo',NULL,NULL,'Cada tipo define si la certificación es obligatoria y con cuántos días de anticipación avisa. Renovar crea la certificación nueva y deja la anterior como reemplazada, así se conserva el historial.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('certificaciones_activo',6,'certificaciones_activo',NULL,NULL,'Editar solo aparece si tu rol tiene el permiso de editar certificaciones. Si no aparece un tipo al registrar, créalo en Catálogo de tipos o usa Cargar tipos sugeridos. Si no deja despachar un equipo, revisa aquí qué certificación obligatoria venció.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cierre','pantalla','cierre','Cierre y Calidad','Consulta de las OT cerradas, la conformidad del cliente y su estado de valorización.','["src/pages_ops.jsx#Cierre"]'::jsonb,'db8d14d20f')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre',1,'cierre',NULL,NULL,'La lista muestra las OT cerradas con su cierre técnico, su acta de conformidad y su estado de valorización.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre',2,'cierre',NULL,NULL,'Filtra por OS, cliente, responsable y fecha de cierre; Limpiar quita los filtros.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre',3,'cierre',NULL,NULL,'Detalle abre el cierre de una OT y Valorizar lleva a valorizar una OT lista para ello.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre',4,'cierre',NULL,NULL,'Para qué sirve: revisar los trabajos ya cerrados y comprobar que cada uno tiene su conformidad del cliente y su valorización, para que nada terminado se quede sin cobrar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre',5,'cierre',NULL,NULL,'Una OT cerrada con acta de conformidad y sin valorizar es trabajo entregado pendiente de cobro: Valorizar la lleva al siguiente paso.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre',6,'cierre',NULL,NULL,'Si no aparece una OT, todavía no está cerrada: el cierre se hace en Operaciones › Cierre & Conformidad. Si no ves Valorizar, la OT ya está valorizada o no tiene acta.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cierre_conformidad','pantalla','ot','Cierre & Conformidad','Cierre de las órdenes de trabajo con el acta de conformidad firmada por el técnico y el cliente.','["operaciones-app/src/zahory-mock/pages/CierreConformidadPage.jsx#CierreConformidadPage"]'::jsonb,'b188e26ea6')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre_conformidad',1,'ot',NULL,NULL,'La lista muestra las OT por cerrar y si están listas para acta; busca por OT, servicio o cliente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre_conformidad',2,'ot',NULL,NULL,'Una OT solo admite acta si tiene técnico responsable, al menos un parte aprobado y ningún parte pendiente de aprobar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre_conformidad',3,'ot',NULL,NULL,'El acta recorre seis pasos: Resumen, Fotos, Conformidad, Firma técnico, Firma cliente y Revisión. En el resumen la descripción del trabajo realizado es obligatoria.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre_conformidad',4,'ot',NULL,NULL,'En Conformidad eliges el resultado: conforme, con observaciones o pendiente de firma. Si queda pendiente debes indicar por qué el cliente no firma y un correo para enviarle el enlace.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre_conformidad',5,'ot',NULL,NULL,'Para la firma del cliente se piden su nombre completo, su documento y un correo para recibir el acta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre_conformidad',6,'ot',NULL,NULL,'Para qué sirve: cerrar formalmente un trabajo con la firma del cliente. El acta de conformidad es la prueba de que el servicio se entregó y lo que permite pasar a valorizar y facturar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cierre_conformidad',7,'ot',NULL,NULL,'Si una OT no aparece lista para acta, revisa que tenga técnico responsable, al menos un parte aprobado y ningún parte por aprobar. Si el cliente no puede firmar en el momento, elige pendiente de firma e indica su correo: recibirá un enlace para firmar después.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('comisiones','pantalla','comisiones','Comisiones','Comisiones de los vendedores: aprobación, recibo por honorarios y cuenta por pagar.','["src/pages_admin.jsx#Comisiones"]'::jsonb,'f28b0f4d0f')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('comisiones',1,'comisiones',NULL,NULL,'La pestaña Comisiones lista las comisiones; Recalcular cobradas recupera las de ventas ya cobradas que aún no estaban registradas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('comisiones',2,'comisiones',NULL,NULL,'Revisar abre una comisión: Aprobar la aprueba y Rechazar exige escribir el motivo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('comisiones',3,'comisiones',NULL,NULL,'Corregir monto cobrado y Corregir bonificación ajustan una comisión; Guardar corrección conserva el cambio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('comisiones',4,'comisiones',NULL,NULL,'Generar crea el recibo de la comisión. Para confirmarlo debes ingresar el número de RHE y adjuntar el documento; Confirmar y generar CxP crea la cuenta por pagar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('comisiones',5,'comisiones',NULL,NULL,'Acuerdos pendientes muestra los acuerdos de comisión por aprobar; solo aparece si tu rol puede aprobarlos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('comisiones',6,'comisiones',NULL,NULL,'Para qué sirve: calcular y pagar la comisión de cada vendedor según lo que su cliente ya pagó. La comisión nace del acuerdo aprobado en la oportunidad y se libera cuando la venta está cobrada.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('comisiones',7,'comisiones',NULL,NULL,'Confirmar rechazo rechaza la comisión con el motivo escrito. Ver recibo abre el recibo generado. Completar RHE aparece mientras el recibo está en borrador y sirve para ingresar el número del recibo por honorarios y adjuntarlo. Limpiar filtros quita los filtros.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('comisiones',8,'comisiones',NULL,NULL,'Si no aparece una comisión de una venta ya cobrada, usa Recalcular cobradas. No deja confirmar el recibo sin el número de RHE y su documento. Acuerdos pendientes solo aparece si tu rol puede aprobar acuerdos.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('como_usar_aria','proceso',NULL,'Cómo usar Aria','Cómo preguntarle a Aria escribiendo o dictando, cómo escuchar sus respuestas, cuántas consultas puedes hacer al día y cómo ver o borrar lo que recuerda de ti.','["src/components/AsistenteErpPanel.jsx#AsistenteErpPanelBase","src/components/AriaMicrofono.jsx#AriaMicrofono","src/lib/ariaHabla.js","src/components/AriaConversaciones.jsx#AriaConversaciones","src/components/AriaRecuerdos.jsx#AriaRecuerdos"]'::jsonb,'9d11a7c3fd c65836e99c c4d45aa981 3ed41385e9 cd021d0a54')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',1,'ninguna',NULL,NULL,'Abre Aria con el robot de la esquina inferior derecha, disponible en las pantallas de Administración y de Operaciones, o escribe en el cuadro Pregúntale a Aria del Inicio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',2,'ninguna',NULL,NULL,'Escribe tu pregunta y pulsa Enviar. Aria responde solo con la información que tus permisos te dejan ver y te indica qué módulos revisó.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',3,'ninguna',NULL,NULL,'Para dictar, toca el micrófono, habla y vuelve a tocarlo al terminar; puedes hablar hasta un minuto. La primera vez el navegador te pedirá permiso para usar el micrófono.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',4,'ninguna',NULL,NULL,'Lo que dictaste aparece escrito en el cuadro para que lo revises o corrijas antes de enviarlo; nada se envía solo. Cuando Aria te pide elegir, por ejemplo el fondo, la categoría o el centro de costo de un gasto, toca uno de los botones que muestra debajo de su mensaje.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',5,'ninguna',NULL,NULL,'Cuando preguntas por voz, Aria lee su respuesta en voz alta. Toca Detener voz para callarla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',6,'ninguna',NULL,NULL,'Puedes hacer 30 preguntas y 60 dictados al día; los contadores se renuevan a medianoche, hora de Lima.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',7,'ninguna',NULL,NULL,'Aria puede preparar tres registros: un gasto de caja chica, un lead y una cuenta (prospecto, cliente o partner). Dile los datos que tengas; ella pide lo que falte, avisa si parece duplicado y te muestra una tarjeta. Solo se guarda cuando tú pulsas Confirmar en esa tarjeta, y necesitas el permiso de crear en esa pantalla. Lo demás (editar, borrar, cotizaciones, órdenes) se hace en su pantalla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',8,'ninguna',NULL,NULL,'Aria recuerda lo que vienen conversando. Si vuelves a abrirla dentro de las 24 horas, retoma tu última conversación; con el botón del reloj ves tus conversaciones anteriores, puedes buscarlas por una palabra y abrir cualquiera, y con el botón + empiezas una nueva. Se guardan 180 días y solo tú las ves. También puedes preguntarle qué revisaron antes, por ejemplo la semana pasada.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',9,'ninguna',NULL,NULL,'Aria también recuerda cómo trabajas de una conversación a otra. Dile recuerda que… para que guarde algo, por ejemplo con qué fondo o centro de costo trabajas; además aprende sola y te avisa en el chat con Aria recordó. Cada aviso trae Deshacer. Para ver, buscar o borrar tus recuerdos, o pausar la memoria, abre el botón del reloj y entra a Lo que Aria recuerda de ti. Solo tú ves tus recuerdos, y Aria no guarda montos ni saldos: esos siempre los consulta en el ERP.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',10,'ninguna',NULL,NULL,'Cuando Aria te explica cómo hacer algo, te dice la ruta exacta de la pantalla (aplicación, módulo y pantalla) y debajo de su respuesta muestra el botón Ir a con el nombre de esa pantalla: tócalo y te lleva directo, también si la pantalla está en la otra aplicación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',11,'ninguna',NULL,NULL,'Los administradores de la empresa ven arriba del chat dos pestañas: Aria y Aria experta. Aria experta, en color violeta, responde a fondo: explica el porqué, el recorrido entre pantallas, los errores frecuentes y qué pasa después, y sirve también para pedir análisis. Cada pestaña guarda sus propias conversaciones. La empresa tiene 150 consultas expertas al mes, compartidas entre sus administradores; el pie del chat indica cuántas quedan y se renuevan el día 1. Desde el chat normal, Ampliar en Aria experta abre el chat experto con esa misma pregunta. El chat normal sigue respondiendo todas tus preguntas sin gastar esa cuota.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('como_usar_aria',12,'ninguna',NULL,NULL,'Qué puedes preguntarle con datos reales de tu empresa, según tus permisos: ventas y facturación, quiénes son tus mejores clientes y cuáles dejaron de comprar; cobros y pagos pendientes y por vencer; bancos y caja chica; compras, órdenes y gastos; stock y kárdex; órdenes de trabajo atrasadas, sin parte o con sobrecosto y por qué una OT no avanza; la utilidad del mes con el mismo Estado de Resultados de Finanzas; cómo va el presupuesto del mes y qué partidas se excedieron; márgenes y rentabilidad del taller y la flota; personal, asistencia, planilla y comisiones; préstamos de la empresa; viajes de transporte; y qué contratos de alquiler, documentos de equipos o contratos del personal están por vencer.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('compras_gastos','pantalla','compras_gastos','Compras / Gastos','Consulta y registra compras y gastos con su comprobante, revisa los gastos que llegan desde campo y edita los que no dependen de otro módulo.','["src/pages_ops.jsx#ComprasGastos","src/components/NuevoEgreso.jsx#NuevoEgreso"]'::jsonb,'74938db849 2c804b78dc')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('compras_gastos',1,'compras_gastos',NULL,NULL,'Revisa los gastos y compras registrados con las pestañas Todos, Campo, Backoffice y Pendientes revisión. Usa la búsqueda y los filtros para localizar un documento o proveedor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('compras_gastos',2,'compras_gastos',NULL,NULL,'Usa Nuevo egreso para registrar una compra o gasto con el asistente de tres pasos: tipo de gasto, datos (fecha, monto, comprobante, proveedor, centro de costo, categoría del Estado de Resultados y método de pago) y revisión. Si el pago es por transferencia indica la cuenta bancaria; puedes vincular la orden de compra de origen y la OT.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('compras_gastos',3,'compras_gastos',NULL,NULL,'Los gastos registrados desde campo llegan como pendientes de revisión. Ábrelos, verifica el comprobante y usa Confirmar — marcar revisado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('compras_gastos',4,'compras_gastos','caja','editar','Para editar un gasto ábrelo y usa Editar; la edición exige el permiso de edición de Caja. No se puede editar aquí si tiene una CxP generada, si viene de Personal/Nómina, si está registrado en Caja Chica o si se capitalizó como activo fijo; la pantalla indica dónde editarlo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('compras_gastos',5,'compras_gastos',NULL,NULL,'Para qué sirve: reunir todas las compras y gastos de la empresa con su comprobante, vengan de la oficina, de un comprador de campo, de caja chica o de una orden de compra. Lo que se registra aquí entra al Estado de Resultados según su categoría.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('compras_gastos',6,'compras_gastos',NULL,NULL,'En el asistente, Revisar pasa al paso final y Guardar gasto lo registra. Borrar búsqueda, Quitar fecha y Limpiar filtros limpian la lista. Cuando un gasto pertenece a otro módulo, los enlaces Ir a Caja Chica, Ir a Tesorería e Ir a Financiamiento y Deuda llevan a donde se edita.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('compras_gastos',7,'compras_gastos',NULL,NULL,'No deja guardar un gasto pagado por transferencia sin elegir la cuenta bancaria, ni sin sociedad cuando la empresa tiene varias. Si no ves Editar, tu rol no tiene el permiso de edición o el gasto pertenece a otro módulo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('concepto_acceso_usuario','proceso',NULL,'Tu usuario, tu contraseña, tu rol y la sociedad activa','Cómo entrar, cambiar o recuperar la contraseña, por qué ves unas pantallas y otras no, y cómo cambiar de sociedad.','["src/AuthGate.jsx","src/shell.jsx#SociedadSelector"]'::jsonb,'dd5fb2e78e cb9cdeb2fa')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_acceso_usuario',1,'ninguna',NULL,NULL,'Tu usuario lo crea el administrador de tu empresa en Configuración › Usuarios. Si te dio una contraseña temporal, al entrar por primera vez el sistema te obliga a crear una nueva: debe tener al menos 6 caracteres y debes escribirla dos veces igual.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_acceso_usuario',2,'ninguna',NULL,NULL,'Si olvidaste tu contraseña, en la pantalla de ingreso usa Olvide mi contrasena: el sistema envía a tu correo un enlace para crear una nueva. Si no llega, revisa la carpeta de correo no deseado o pide al administrador que te defina una contraseña temporal desde Usuarios.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_acceso_usuario',3,'ninguna',NULL,NULL,'Lo que puedes ver y hacer depende de tu rol. Cada rol define, pantalla por pantalla, si puedes ver, crear, editar, anular, aprobar y exportar. Por eso un botón puede no aparecerte o aparecer deshabilitado: no es una falla. Pregúntale a Aria "¿por qué no puedo…?" y te dirá si es por tu rol; el cambio lo hace el administrador de la empresa en Configuración › Roles y Permisos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_acceso_usuario',4,'ninguna',NULL,NULL,'Si tu empresa trabaja con varias sociedades (razones sociales), arriba aparece el selector de sociedad. Elige la sociedad con la que vas a trabajar: lo que registres queda en esa sociedad. La opción GRUPO — Vista consolidada muestra todo junto y sirve para consultar; para registrar documentos, movimientos de almacén o iniciar órdenes de trabajo el sistema te pide elegir antes una sociedad concreta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_acceso_usuario',5,'ninguna',NULL,NULL,'Tu acceso puede estar limitado a algunas sociedades: lo define el administrador al crear tu usuario. Si no ves una sociedad en el selector, pídele que te la asigne.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('concepto_almacen','proceso',NULL,'Conceptos de almacén: stock, reserva, kardex, ubicación y conteo','Explica los términos del almacén y cómo se relacionan con las compras y las órdenes de trabajo.','["operaciones-app/src/zahory-mock/pages/InventarioKardexPage.jsx#InventarioKardexPage"]'::jsonb,'8dad26c438')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_almacen',1,'ninguna',NULL,NULL,'El stock es lo que hay de cada material. Se divide en disponible, que se puede usar o vender, y reservado, que ya está apartado para una orden de trabajo o un pedido y no debe tocarse para otra cosa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_almacen',2,'ninguna',NULL,NULL,'El kardex es el historial de movimientos de un material: cada entrada, salida, traslado y ajuste, con su fecha y su origen. Si el stock no coincide con lo que esperas, el kardex dice qué movimiento lo cambió.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_almacen',3,'ninguna',NULL,NULL,'El stock entra con la recepción de una compra y sale con el despacho a una orden de trabajo, a una venta o a un retiro. Cuando una OT necesita repuestos, primero se reservan y luego se despachan al taller; si no se usan, la reserva se libera y vuelven a disponible.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_almacen',4,'ninguna',NULL,NULL,'La ubicación es el lugar físico dentro del almacén (estante, posición). Mover traslada stock entre ubicaciones. Un almacén puede ser central o periférico, por ejemplo el de una mina.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_almacen',5,'ninguna',NULL,NULL,'El conteo cíclico compara lo que dice el sistema con lo que hay físicamente. Las diferencias se vuelven ajustes en el kardex; si superan el umbral que configuró la empresa, otra persona debe aprobarlos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_almacen',6,'ninguna',NULL,NULL,'El stock mínimo es la cantidad por debajo de la cual hay que reponer. La pantalla Stock mínimos & reposición lista los materiales bajo su mínimo y genera la SOLPE para comprarlos.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('concepto_ceco_cebe','proceso',NULL,'Qué son el CECO y el CEBE y por qué el sistema los pide','Explica el centro de costo y el centro de beneficio, dónde se crean y en qué documentos son obligatorios.','["src/pages_admin.jsx#Maestros"]'::jsonb,'50855bc116')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_ceco_cebe',1,'ninguna',NULL,NULL,'El CECO (centro de costo) responde a la pregunta "¿a qué área o actividad se le carga este gasto?": taller, administración, un proyecto, una mina. El CEBE (centro de beneficio) responde a "¿qué línea de negocio genera este ingreso?". Con ellos la empresa puede ver cuánto gasta y cuánto gana cada área, y arma su Estado de Resultados y su Presupuesto vs Real.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_ceco_cebe',2,'ninguna',NULL,NULL,'Se crean en Administración › Configuración › Maestros Base, con Agregar CECO y Agregar CEBE. Un CECO en uso no se borra: se desactiva, y deja de aparecer para nuevas asignaciones aunque las órdenes que ya lo usan siguen vinculadas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_ceco_cebe',3,'ninguna',NULL,NULL,'El CECO es obligatorio al pedir y comprar: sin CECO la SOLPE no se guarda, la orden de compra no se emite y la orden de servicio a proveedor no continúa. Si una orden de compra mezcla líneas con CECO distintos o sin CECO, hay que reasignarlas antes de emitirla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_ceco_cebe',4,'ninguna',NULL,NULL,'En el trabajo operativo, cada orden de trabajo necesita un centro de costo para poder iniciarse, y la OS Cliente debe tener CEBE asignado antes de crear sus órdenes de trabajo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_ceco_cebe',5,'ninguna',NULL,NULL,'Si al registrar algo no encuentras el CECO que necesitas, no elijas uno parecido: pide al administrador que lo cree en Maestros Base. Un gasto cargado al CECO equivocado distorsiona los resultados del área.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('concepto_costeo','proceso',NULL,'Cómo se calcula el precio de un trabajo: Hoja de Costeo, margen y costo real','Explica la Hoja de Costeo, las variables que usa, el margen y la comparación entre lo estimado y lo real.','["src/pages_hoja_costeo_wizard.jsx#HojaCosteoWizard","src/pages_costeo_variables.jsx#CosteoVariables"]'::jsonb,'c181c07274 f42c3b0172')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_costeo',1,'ninguna',NULL,NULL,'La Hoja de Costeo calcula cuánto le cuesta a la empresa hacer un trabajo antes de cotizarlo, para ponerle un precio que deje ganancia. Suma mano de obra (horas por el costo hora de cada cargo), materiales, depreciación de los equipos que se usan y un porcentaje de gasto administrativo, y sobre eso aplica el margen.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_costeo',2,'ninguna',NULL,NULL,'Los valores base se mantienen en Variables de Costeo: el costo hora por cargo, la depreciación de activos y el gasto administrativo. Si un cargo no tiene costo por hora, la hoja lo avisa: hay que completarlo ahí para que el cálculo sea correcto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_costeo',3,'ninguna',NULL,NULL,'El porcentaje de gasto administrativo más el de margen debe ser menor a 100 %. La hoja se envía a revisión y solo después se puede aprobar; con la hoja aprobada se genera la cotización.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_costeo',4,'ninguna',NULL,NULL,'Si el trabajo viene de un diagnóstico técnico del taller, la hoja se arma a partir de los trabajos y actividades del diagnóstico, y las recetas de actividad definen qué tareas lleva cada actividad.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_costeo',5,'ninguna',NULL,NULL,'Cuando el trabajo se ejecuta, la orden de trabajo acumula su costo real: horas de los partes diarios, repuestos despachados, servicios de terceros y gastos logísticos. Comparar el costo real con el estimado de la hoja muestra si el trabajo dejó el margen esperado o tuvo sobrecosto.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('concepto_detraccion','proceso',NULL,'Qué es la detracción (SPOT) y cómo se registra','Explica la detracción al vender y al comprar, la autodetracción y la cuenta del Banco de la Nación.','["src/pages_fin.jsx#CxC"]'::jsonb,'06993c9c6e')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_detraccion',1,'ninguna',NULL,NULL,'La detracción (SPOT) es una parte del importe de una factura que no se paga al proveedor sino que se deposita en su cuenta del Banco de la Nación. Aplica a determinados bienes y servicios según las reglas de SUNAT. El resultado práctico: el que paga hace dos pagos, el neto al proveedor y la detracción al Banco de la Nación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_detraccion',2,'ninguna',NULL,NULL,'Cuando tú compras: en Cuentas por Pagar registra la obligación con Aplicar detracción y paga al proveedor exactamente el neto; el depósito al Banco de la Nación se registra aparte con su constancia. El proveedor debe tener registrada en su ficha su cuenta del Banco de la Nación, que debe estar en soles.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_detraccion',3,'ninguna',NULL,NULL,'Cuando tú vendes: el cliente te paga el neto y deposita la detracción en tu cuenta del Banco de la Nación. Registra el cobro normal por el neto en Cuentas por Cobrar o en Facturación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_detraccion',4,'ninguna',NULL,NULL,'Si el cliente no depositó la detracción y te pagó el total, te toca hacer el depósito a ti: usa Registrar autodetracción, selecciona las cuentas e ingresa el número y la fecha de la constancia del depósito.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_detraccion',5,'ninguna',NULL,NULL,'Las cuentas de detracciones no se usan para transferencias entre cuentas propias en Tesorería.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('concepto_documentos_compra','proceso',NULL,'Los documentos de una compra: SOLPE, orden de compra, recepción, factura y pago','Explica qué es cada documento del ciclo de compra, quién interviene y las otras formas de registrar un gasto.','["src/pages_ops.jsx#OrdenesServicio","src/pages_ops.jsx#CotizacionesCompras"]'::jsonb,'0144236b2a 1618a00848')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_compra',1,'ninguna',NULL,NULL,'La SOLPE (solicitud de pedido) es el pedido interno: alguien de un área dice qué necesita, para qué CECO y con qué urgencia. Nace en borrador, se envía y alguien la atiende y la aprueba. Una SOLPE no es una compra todavía: es la necesidad.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_compra',2,'ninguna',NULL,NULL,'Con la SOLPE aprobada, Compras decide a quién comprar en la Bandeja de Sourcing: se elige proveedor por cada línea, de modo que un mismo pedido puede repartirse entre varios proveedores y se genera una orden de compra por proveedor. Si hace falta comparar precios, antes se abre un proceso de cotización con proveedores.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_compra',3,'ninguna',NULL,NULL,'La OC (orden de compra) es el compromiso con el proveedor: ítems, cantidades, precios y CECO. Se guarda en borrador, se emite y se puede marcar como confirmada cuando el proveedor la acepta. Permite registrar anticipos y el tránsito de la mercadería.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_compra',4,'ninguna',NULL,NULL,'La recepción registra lo que llegó de verdad y actualiza el stock. La recepción física y la factura van por separado: puede llegar la mercadería sin factura, y la factura se completa después. Si el proveedor no entregará un saldo, esa cantidad se libera y vuelve a la Bandeja de Sourcing.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_compra',5,'ninguna',NULL,NULL,'La factura del proveedor crea la CxP (cuenta por pagar), vinculada a su orden de compra para no duplicar la deuda. El pago se registra en Cuentas por Pagar eligiendo la cuenta bancaria, y admite pagos parciales. Si la factura está sujeta a detracción se paga al proveedor el neto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_compra',6,'ninguna',NULL,NULL,'No toda salida de dinero pasa por una orden de compra. Un servicio contratado a un tercero va con Orden de Servicio a proveedor y su conformidad. Un gasto menor se registra en Compras / Gastos con Nuevo egreso, o en Caja Chica si se pagó con el fondo. Los recibos por honorarios, tributos y reembolsos se registran directo en Cuentas por Pagar.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('concepto_documentos_venta','proceso',NULL,'Los documentos de una venta: cotización, OS Cliente, OT, OF, valorización y factura','Explica qué es cada documento del ciclo de venta, en qué se diferencian y en qué orden nacen.','["src/pages_core.jsx#OSCliente","src/pages_extra.jsx#Cotizaciones","src/pages_extra.jsx#Valorizacion","src/pages_fin.jsx#Ventas"]'::jsonb,'90315ca39a 2e3ef06c5d e710949e0a 9566fef6c9')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_venta',1,'ninguna',NULL,NULL,'La cotización es la oferta al cliente: qué se le va a hacer y por cuánto. Puede salir de una oportunidad del Pipeline y, si el trabajo necesita calcular costos, de una Hoja de Costeo. Mientras no esté aprobada no compromete nada.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_venta',2,'ninguna',NULL,NULL,'La OS Cliente (orden de servicio del cliente) es el compromiso: nace de una cotización aprobada y agrupa todo lo que se le hará a ese cliente por ese pedido. Es el documento que se valoriza y se factura. Vive en Administración › Comercial › OS Cliente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_venta',3,'ninguna',NULL,NULL,'La OT (orden de trabajo) es el trabajo concreto que ejecuta el taller o el equipo de campo para cumplir la OS: tiene técnico responsable, tareas, repuestos, partes diarios y costos reales. Una OS puede tener varias OT. La OF (orden de fabricación) es lo mismo pero para fabricar una pieza: tiene ruta de tareas y lista de materiales. Se usa OT para mantenimiento o servicio y OF para fabricación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_venta',4,'ninguna',NULL,NULL,'La valorización dice cuánto de lo ejecutado ya se puede cobrar. Se registra dentro de la OS Cliente y debe aprobarse; se apoya en el cierre técnico de la OT y en el acta de conformidad del cliente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_venta',5,'ninguna',NULL,NULL,'La factura (comprobante) se emite desde la valorización aprobada, en Administración › Administración › Facturación, y con Generar CxC crea la cuenta por cobrar, que es donde se controla el cobro y la mora.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_venta',6,'ninguna',NULL,NULL,'Ventas y Facturación no son lo mismo. Ventas registra ventas directas que no pasan por orden de servicio (por ejemplo un producto o un servicio simple): se registra la venta, se confirma, se emite su comprobante y se cobra ahí mismo. Facturación reúne todos los comprobantes, vengan de una valorización, de una venta o emitidos directamente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_documentos_venta',7,'ninguna',NULL,NULL,'Un servicio que se cobra todos los meses se configura en la OS Cliente como cobro mensual: indicas la tarifa mensual sin IGV y la fecha de inicio; la primera OT la creas tú y después se crea sola el día 1 de cada mes.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('concepto_personal_planilla','proceso',NULL,'Cómo se conectan el personal, la asistencia y la planilla','Explica qué necesita un trabajador para marcar y cobrar, y cómo la asistencia y las solicitudes llegan a la planilla.','["src/pages_ops.jsx#Nomina","src/pages_ops.jsx#ControlAsistencia"]'::jsonb,'21d2972451 ce8d288576')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_personal_planilla',1,'ninguna',NULL,NULL,'Cada trabajador tiene una ficha en Personal Administrativo o en Personal Operativo, con su contrato, su cargo, su jornada, su cuenta bancaria y sus documentos. Al contratar desde Reclutamiento, el sistema pregunta en cuál de las dos se crea.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_personal_planilla',2,'ninguna',NULL,NULL,'Para marcar asistencia el trabajador necesita un turno asignado en su ficha. Marca desde el celular; la geocerca define desde dónde es válido marcar, y si está fuera puede enviar un reporte para revisión. Sin señal, la marcación se guarda y se sincroniza al recuperar conexión.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_personal_planilla',3,'ninguna',NULL,NULL,'Las vacaciones, permisos y descansos se piden como solicitudes; una vez aprobadas, Aplicar a asistencia crea los registros de esos días para que no cuenten como falta. Una marcación errada se corrige con un ajuste, que exige motivo y aprobación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_personal_planilla',4,'ninguna',NULL,NULL,'La planilla se calcula por período en Nómina: se crea el período y se calcula con Procesar; si se paga por quincenas, la primera quincena se procesa antes que la segunda. Los ingresos o descuentos extraordinarios se registran antes de cerrar. Al cerrar el período se generan los egresos de la planilla, por eso conviene revisar las boletas antes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_personal_planilla',5,'ninguna',NULL,NULL,'El trabajador ve sus boletas en Mi portal, después de registrar su consentimiento de entrega electrónica. Ahí también sube su contrato firmado y pide constancias, horas extra, vacaciones y permisos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_personal_planilla',6,'ninguna',NULL,NULL,'Cuando un trabajador cesa, la Liquidación por Cese calcula lo que se le debe; al confirmarla se genera la cuenta por pagar y se bloquea su acceso al sistema.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('concepto_que_es_opera','proceso',NULL,'Qué es OPERA y para qué sirve cada aplicación','Orientación para quien recién entra: qué es OPERA, qué hace el sistema, para qué sirve cada una de sus tres aplicaciones, cómo está organizado el menú y qué hacer el primer día.','["catalogo/pantallas.json"]'::jsonb,'063dba2ec2')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_que_es_opera',1,'ninguna',NULL,NULL,'OPERA es el sistema donde la empresa lleva todo su trabajo en un solo lugar: lo que vende, lo que compra, lo que cobra y paga, su personal, su taller, su almacén, su flota y su transporte. Lo que una persona registra en un módulo lo usan los demás: por ejemplo, una cotización aprobada se vuelve orden de servicio, la orden genera trabajo en el taller, el trabajo terminado se valoriza y se factura, y la factura queda como cuenta por cobrar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_que_es_opera',2,'ninguna',NULL,NULL,'Tiene tres aplicaciones, que eliges al entrar en la pantalla Elige una aplicación. Administración es para oficina: comercial, compras, finanzas, RRHH y configuración. Operaciones es para el trabajo operativo: órdenes de trabajo del taller, almacén, flota y alquileres, transporte y producción. Control de asistencia y la versión móvil son para el celular: marcar asistencia, registrar partes, aprobar y vender en campo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_que_es_opera',3,'ninguna',NULL,NULL,'En Administración el menú se agrupa por área: Inicio, CRM & Marketing, Comercial, Compras, Logística, Operaciones, Administración (finanzas), RRHH, Customer Success, Dashboards y Configuración. Solo ves las áreas y pantallas que tu rol permite; si no ves algo, no es un error: tu rol no lo tiene asignado y lo habilita el administrador de tu empresa en Roles y Permisos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_que_es_opera',4,'ninguna',NULL,NULL,'Empieza siempre por Inicio: muestra lo que tienes pendiente hoy (aprobaciones, documentos por atender, avisos) y un botón para ir directo a cada cosa. Ahí mismo puedes preguntarle a Aria.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_que_es_opera',5,'ninguna',NULL,NULL,'El primer día conviene: revisar tu ficha y tus documentos en Mi portal, marcar tu asistencia si te corresponde, y pedirle a Aria que te explique la pantalla donde estás. Aria te dice la ruta exacta de cada pantalla y te lleva con el botón Ir a.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('concepto_que_es_opera',6,'ninguna',NULL,NULL,'Casi todas las pantallas funcionan igual: una lista con buscador y filtros, un botón para crear (Nuevo…), y al abrir un registro ves su detalle con las acciones permitidas según su estado. Los indicadores de arriba de cada lista suelen servir también como filtro al tocarlos.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('configuracion_wms','pantalla','inventario','Configuración del WMS','Opciones de funcionamiento del almacén.','["operaciones-app/src/zahory-mock/pages/wms/ConfiguracionWmsPage.jsx#ConfiguracionWmsPage"]'::jsonb,'a3620ec951')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('configuracion_wms',1,'inventario',NULL,NULL,'Activa o desactiva las funciones del almacén y define el umbral de aprobación de los conteos, que debe ser cero o mayor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('configuracion_wms',2,'inventario',NULL,NULL,'Guardar cambios conserva la configuración; el menú de Almacén se actualiza al recargar la página.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('configuracion_wms',3,'inventario',NULL,NULL,'Para qué sirve: decidir qué funciones del almacén usa la empresa, para que el menú muestre solo lo necesario, y fijar a partir de qué diferencia un conteo necesita la aprobación de otra persona.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('configuracion_wms',4,'inventario',NULL,NULL,'Las funciones que se apagan dejan de verse en el menú de Almacén, pero sus datos no se borran: al volver a activarlas reaparecen.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('configuracion_wms',5,'inventario',NULL,NULL,'Si no ves una pantalla del almacén en el menú, revisa aquí que su función esté activada y recarga la página. No deja guardar un umbral negativo. Si no puedes entrar, tu rol no tiene acceso a la configuración del almacén.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('conteos_ciclicos','pantalla','inventario','Conteos cíclicos','Conteo físico del almacén y ajuste de las diferencias.','["operaciones-app/src/zahory-mock/pages/wms/ConteosPage.jsx#ConteosPage"]'::jsonb,'f926063c1c')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('conteos_ciclicos',1,'inventario',NULL,NULL,'Inicia con Nuevo conteo y elige el almacén a contar; Crear conteo genera sus líneas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('conteos_ciclicos',2,'inventario',NULL,NULL,'Registra lo contado y usa Guardar avance para continuar después. Un código que no pertenece al conteo se rechaza.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('conteos_ciclicos',3,'inventario',NULL,NULL,'Cerrar conteo exige contar todas las líneas y registra los ajustes en el kardex.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('conteos_ciclicos',4,'inventario',NULL,NULL,'Si las diferencias superan el umbral, el conteo queda por aprobar por otra persona, que usa Aprobar ajustes o Devolver a recontar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('conteos_ciclicos',5,'inventario',NULL,NULL,'Para qué sirve: comprobar que lo que dice el sistema coincide con lo que hay físicamente en el almacén, contando por partes sin detener la operación, y corregir las diferencias dejando historial.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('conteos_ciclicos',6,'inventario',NULL,NULL,'No deja cerrar el conteo si faltan líneas por contar o si hay cantidades no válidas. Si al escanear dice que el código no está en este conteo, ese material no pertenece al almacén elegido. Si no ves Aprobar ajustes, el conteo no superó el umbral o lo iniciaste tú: debe aprobarlo otra persona.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('contratos_rental','pantalla','contratos_alquiler','Contratos Rental','Contratos de alquiler de equipos y sus tarifas.','["operaciones-app/src/zahory-mock/pages/flota/ContratosRentalPage.jsx#ContratosRentalPage"]'::jsonb,'b8f7626900')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('contratos_rental',1,'contratos_alquiler',NULL,NULL,'Registra un alquiler con Nuevo contrato y Crear contrato.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('contratos_rental',2,'contratos_alquiler',NULL,NULL,'Cambiar tarifa modifica la tarifa y Guardar versión conserva el cambio como una nueva versión del contrato.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('contratos_rental',3,'contratos_alquiler',NULL,NULL,'Cambiar a cambia el estado del contrato.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('contratos_rental',4,'contratos_alquiler',NULL,NULL,'Para qué sirve: el contrato de alquiler fija con qué cliente, qué equipos, en qué moneda y a qué tarifa por hora se alquila, y el mínimo que se cobra aunque el equipo opere menos. Al crear el contrato son obligatorios el cliente, la sociedad, la moneda y el mínimo con su unidad y su periodicidad.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('contratos_rental',5,'contratos_alquiler',NULL,NULL,'La tarifa tiene versiones. Cambiar tarifa pide la nueva tarifa por hora, la fecha desde la que rige y el motivo, y Guardar versión la conserva sin borrar la anterior. La liquidación del mes cobra cada día con la tarifa que estaba vigente ese día, así que un cambio de tarifa a mitad de mes se aplica solo desde su fecha.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('contratos_rental',6,'contratos_alquiler',NULL,NULL,'El contrato alimenta el resto del módulo: los equipos del contrato se entregan y se reciben con Actas & Despachos, sus horas se registran en los partes diarios de Liquidación & DMR, y la liquidación mensual usa su tarifa, su mínimo y su meta de disponibilidad.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('contratos_rental',7,'contratos_alquiler',NULL,NULL,'Quien edita contratos puede crearlos y cambiarlos; los demás roles con acceso solo los consultan. Si no ves Nuevo contrato o Cambiar tarifa, es por tu rol.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('asistencia','pantalla','asistencia','Control de Asistencia','Marcaciones, geocercas, ajustes y reportes de asistencia del personal.','["src/pages_ops.jsx#ControlAsistencia"]'::jsonb,'ce8d288576')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',1,'asistencia',NULL,NULL,'Cada trabajador necesita un turno asignado antes de marcar asistencia; se le asigna desde su ficha en Personal.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',2,'asistencia',NULL,NULL,'Las marcaciones llegan del Reloj Control (Móvil). También puedes registrarlas a mano, con Registro masivo o con Importar marcaciones desde un archivo, que muestra una vista previa antes de Confirmar importacion.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',3,'asistencia',NULL,NULL,'Las geocercas definen dónde se puede marcar: se crean con nombre, latitud y longitud, o dibujando en el mapa un polígono de al menos tres vértices.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',4,'asistencia',NULL,NULL,'Para corregir una marcación se pide un ajuste con su motivo, que es obligatorio; quien aprueba usa Aprobar o Rechazar. Registrar una falta también exige motivo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',5,'asistencia',NULL,NULL,'En operaciones mineras, el ciclo de cada trabajador se registra con Guardar Ciclo, que genera sus registros diarios.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',6,'asistencia',NULL,NULL,'Reporte mensual resume el mes y Exportar Excel descarga los registros.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',7,'asistencia',NULL,NULL,'Para qué sirve: controlar quién asistió, a qué hora y dónde, para pagar la planilla con horas reales y detectar tardanzas, faltas y horas extra. Reúne el régimen general (jornada diaria) y el régimen minero (ciclos de días de trabajo y de descanso).');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',8,'asistencia',NULL,NULL,'Las pestañas son: Vista diaria, Vista semanal, Vista mensual, Resumen por trabajador, Autorizaciones HE, Biometrico, Asistencia minera, Régimen Minero, Roster minero y SAR / Geocercas. Cada una se describe en los pasos siguientes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',9,'asistencia',NULL,NULL,'Vista diaria: muestra la asistencia del día. Columnas elige qué columnas ver, con Ocultar todo y Hecho. En cada fila, Entrada y Salida registran la marca a mano y Guardar registro la conserva. Ver ubicación de marcación abre el punto donde se marcó; si no la hay, indica «Sin ubicación registrada». Eliminar registro de asistencia borra el registro del día, y dice «Sin registro para eliminar» cuando no existe.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',10,'asistencia',NULL,NULL,'Vista semanal: Semana anterior y Siguiente semana cambian de semana y Hoy vuelve a la actual. Grilla muestra a cada persona por día, Totales suma sus horas de la semana y Manual cambia al ingreso manual; Guardar todos los registros conserva lo editado. Vista mensual: Calendario general y Calendario minero alternan entre los dos regímenes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',11,'asistencia',NULL,NULL,'Autorizaciones HE: Enviar solicitud pide autorización de horas extra indicando fecha, horas y motivo; quien aprueba la resuelve en la lista de solicitudes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',12,'asistencia',NULL,NULL,'Biometrico: sirve para cargar las marcas de un reloj biométrico. Descargar plantilla baja el formato, Importar archivo lo carga y Previsualizar muestra cómo quedará antes de confirmar. Guardar perfil conserva cómo leer el archivo de ese reloj para no configurarlo cada vez; Ocultar configuracion avanzada esconde esas opciones y Borrar elimina un perfil. En el historial de lotes, Anular deshace una carga completa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',13,'asistencia',NULL,NULL,'Asistencia minera y Régimen Minero: Registrar estado anota el estado del día de cada trabajador en mina, y Guardar estado real corrige un día cuando lo ocurrido fue distinto de lo programado; en ese caso no se guardan horas trabajadas, tardanza ni horas extra. Editar ciclo cambia el ciclo de un trabajador e Ir a registro de ciclos mineros lleva a crearlo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',14,'asistencia',NULL,NULL,'Roster minero: es la programación de quién sube y quién baja. Unidades Mineras lista las unidades y Actualizar asignación cambia la unidad de un trabajador. Calcular actualiza el cálculo del roster. Solicitar ajuste pide cambiar un día ya programado; quien aprueba usa Aprobar con autorización, y «Forzar cambio (requiere autorización)» lo aplica con una autorización expresa. Reflejar ajuste lo lleva a los totales y Añadir suma un ajuste a la lista.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',15,'asistencia',NULL,NULL,'SAR / Geocercas: Editar geocerca y Eliminar geocerca mantienen las zonas donde se puede marcar, y Cancelar edicion descarta el cambio. Asignar trabajador vincula a una persona con su geocerca. Guardar politica conserva las reglas de GPS y el texto de consentimiento que acepta el trabajador. Generar alertas revisa quién no llegó a su punto a la hora límite y crea el aviso de no llegada.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('asistencia',16,'asistencia',NULL,NULL,'Si un trabajador no puede marcar, revisa en este orden: que tenga turno asignado, que tenga contrato vigente en esa fecha, que esté dentro de su geocerca y que haya dado permiso de ubicación. No deja crear una geocerca sin nombre, latitud y longitud, ni un polígono de menos de tres vértices. Si no ves los botones para aprobar ajustes u horas extra, tu rol no tiene el permiso de aprobar en Asistencia.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('control_horas','pantalla','control_horas','Control de Horas','Horas trabajadas por colaborador en cada OT, con su disponibilidad y su costo imputado.','["src/pages_ops.jsx#ControlHoras"]'::jsonb,'e8ca7edb9b')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('control_horas',1,'control_horas',NULL,NULL,'Muestra las horas por colaborador y por OT del mes elegido; cambia de mes con Mes anterior y Mes siguiente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('control_horas',2,'control_horas',NULL,NULL,'Filtra por colaborador y por modalidad: planilla u honorarios.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('control_horas',3,'control_horas',NULL,NULL,'Evaluar mes revisa la productividad del período y avisa cuántas alertas de baja productividad encontró.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('control_horas',4,'control_horas',NULL,NULL,'Exportar Excel descarga el reporte.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('control_horas',5,'control_horas',NULL,NULL,'Para qué sirve: ver cuántas horas trabajó cada colaborador en cada orden de trabajo durante el mes y cuánto costaron, para saber en qué se va el tiempo del personal y detectar a quien registra pocas horas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('control_horas',6,'control_horas',NULL,NULL,'Las horas vienen de los partes diarios aprobados y de los tareos; el costo sale de las horas por la tarifa por hora de cada persona. Para quien cobra por honorarios muestra también si ya tiene su recibo del período.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('control_horas',7,'control_horas',NULL,NULL,'Si no aparecen horas de un colaborador, revisa que sus partes estén aprobados y sean del mes elegido. Si la pantalla dice que no tienes permiso para ver este módulo, tu rol no tiene acceso a Control de Horas.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cot_compras','pantalla','cot_compras','Cotizaciones de Compras','Procesos de cotización con proveedores hasta generar la orden de compra o de servicio.','["src/pages_ops.jsx#CotizacionesCompras"]'::jsonb,'1618a00848')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cot_compras',1,'cot_compras',NULL,NULL,'Inicia con Nuevo proceso de cotizacion y avanza con Siguiente; al confirmar, el proceso se crea y se envía a los proveedores.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cot_compras',2,'cot_compras',NULL,NULL,'Registrar respuesta anota lo que cotizó cada proveedor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cot_compras',3,'cot_compras',NULL,NULL,'Seleccionar ganador elige la mejor oferta y Confirmar seleccion y generar OC / OS crea la orden de compra o la orden de servicio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cot_compras',4,'cot_compras',NULL,NULL,'Ver proceso abre el detalle de un proceso.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cot_compras',5,'cot_compras',NULL,NULL,'Úsalo cuando quieres comparar precios antes de comprar: el mismo pedido se envía a varios proveedores, registras lo que responde cada uno y eliges al ganador. Si ya sabes a quién comprar, no hace falta: ve directo a la Bandeja de Sourcing o a la orden de compra.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cot_compras',6,'cot_compras',NULL,NULL,'Si cada material conviene comprarlo a un proveedor distinto, usa la Bandeja de Sourcing: ahí se asigna el proveedor línea por línea y se genera una orden por proveedor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cot_compras',7,'cot_compras',NULL,NULL,'Para qué sirve: pedir precio a varios proveedores por lo mismo y elegir con datos antes de comprar. Deja constancia de quién cotizó cuánto y por qué se eligió al ganador.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cot_compras',8,'cot_compras',NULL,NULL,'Si no ves el botón para generar la orden, aún no hay un proveedor ganador elegido. Si un proveedor no aparece para invitarlo, regístralo primero en Proveedores.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cotizaciones','pantalla','cotizaciones','Cotizaciones','Elaboración, envío y aprobación de cotizaciones, y su paso a orden de servicio.','["src/pages_extra.jsx#Cotizaciones"]'::jsonb,'2e3ef06c5d')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cotizaciones',1,'cotizaciones',NULL,NULL,'Crea una cotización con Nueva cotización: elige la cuenta, agrega las partidas con Agregar partida e indica la condición de pago. Puedes dividir el pago en hitos con Agregar hito.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cotizaciones',2,'cotizaciones',NULL,NULL,'Si sales con cambios sin guardar, la pantalla pregunta si quieres Salir sin guardar o Seguir editando.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cotizaciones',3,'cotizaciones',NULL,NULL,'Envía la cotización con PDF o con Copiar enlace. Página de firmas muestra la hoja de firmas del documento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cotizaciones',4,'cotizaciones',NULL,NULL,'Cuando el cliente acepta usa Confirmar aprobación e indica el canal de aprobación; puedes adjuntar el sustento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cotizaciones',5,'cotizaciones',NULL,NULL,'Con la cotización aprobada usa Crear OS Cliente, como Crear nueva OS o Agregar a OS existente. El indicador Por convertir filtra las aprobadas que aún no tienen OS.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cotizaciones',6,'cotizaciones',NULL,NULL,'Para qué sirve: armar la propuesta económica al cliente, registrar su aprobación y convertirla en orden de servicio. Sin cotización aprobada no se crea la OS del cliente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cotizaciones',7,'cotizaciones',NULL,NULL,'En cada partida, Sub-ítems detalla su contenido, Incl. marca un sub-ítem como incluido sin costo y Quitar incluido lo desmarca. La validez se indica en Días o con Fecha exacta. Página de firmas · vista previa muestra cómo saldrá la hoja de firmas. Limpiar filtros quita los filtros del listado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cotizaciones',8,'cotizaciones',NULL,NULL,'No deja confirmar la aprobación si falta el canal de aprobación, la fecha en que el cliente aprobó o la evidencia; la evidencia debe ser PDF, JPG o PNG de hasta 10 MB. Si no ves Crear OS Cliente, la cotización aún no está aprobada o ya se convirtió.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cuentas','pantalla','cuentas','Cuentas y Contactos','Ficha de cada cliente: datos, contactos, precios acordados y condiciones comerciales.','["src/pages_ops.jsx#Cuentas"]'::jsonb,'4c81d6e303')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cuentas',1,'cuentas',NULL,NULL,'Crea un cliente con Nueva cuenta. Editar cuenta cambia sus datos y Eliminar cuenta lo borra con confirmación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cuentas',2,'cuentas',NULL,NULL,'Agrega a las personas del cliente con Nuevo contacto y marca al Principal.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cuentas',3,'cuentas',NULL,NULL,'Agregar precio registra un precio acordado con ese cliente, y Guardar condiciones conserva sus condiciones comerciales.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cuentas',4,'cuentas',NULL,NULL,'Para cargar muchas cuentas descarga la plantilla y usa Importar Excel.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cuentas',5,'cuentas',NULL,NULL,'Tipos de cuenta: Prospecto es una empresa que aún no compra; Cliente ya compra; Partner es un aliado comercial. Para crear una cuenta basta la razón social; el RUC es opcional pero conviene registrarlo para facturar y para detectar duplicados.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cuentas',6,'cuentas',NULL,NULL,'También puedes pedirle a Aria que cree la cuenta: dile la razón social y lo que tengas (RUC, tipo, nombre comercial, industria, tamaño, teléfono, correo, dirección, condición de pago, límite de crédito, origen y el contacto principal). Aria avisa si ya existe una cuenta con ese RUC o ese nombre, muestra una tarjeta con los datos y nada se graba hasta pulsar Confirmar. Requiere permiso de crear en Cuentas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cuentas',7,'cuentas',NULL,NULL,'Para qué sirve: tener en un solo lugar a cada empresa con la que se cotiza y factura, con sus contactos, sus precios pactados y sus condiciones comerciales. Es la base de cotizaciones, órdenes de servicio y facturas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cuentas',8,'cuentas',NULL,NULL,'Descargar plantilla baja el Excel modelo para la carga masiva. En la ficha, Más acciones reúne las acciones menos frecuentes, Guardar cambios conserva la edición y Cerrar ficha vuelve a la lista. Crear contacto guarda al contacto nuevo. Actualizar precio cambia un precio pactado ya registrado. Ver en módulo abre el documento relacionado en su pantalla. Limpiar filtros quita los filtros de la lista. El consejo de arriba recuerda registrar primero un lead y convertirlo: Ir a Leads lleva allí y Cerrar consejo lo oculta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cuentas',9,'cuentas',NULL,NULL,'Si no ves Nueva cuenta, Editar cuenta o Eliminar cuenta, tu rol no tiene ese permiso en Cuentas. No deja eliminar una cuenta que tiene documentos financieros o cuentas por cobrar asociados: primero hay que anularlos o regularizarlos. Si no aparece una cuenta, usa Limpiar filtros y revisa el filtro de tipo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cxc','pantalla','cxc','Cuentas por cobrar','Controla lo que deben los clientes: cobros, gestiones de cobranza, mora, autodetracciones y carga masiva de facturas desde Excel.','["src/pages_fin.jsx#CxC"]'::jsonb,'06993c9c6e')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxc',1,'cxc',NULL,NULL,'La lista muestra cada cuenta por cobrar con su saldo y vencimiento. Usa Cobrar para registrar un pago: elige el medio de pago e ingresa el número de operación o referencia bancaria.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxc',2,'cxc',NULL,NULL,'Nueva gestión registra una acción de cobranza (llamada, correo, compromiso de pago). Según el resultado, la fecha de próxima acción es obligatoria.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxc',3,'cxc',NULL,NULL,'Si el cliente no depositó la detracción, usa Registrar autodetracción con las cuentas y la constancia del depósito.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxc',4,'cxc','cxc','editar','La mora se calcula con una tasa diaria. Puedes Condonar mora para que deje de calcularse (queda en el historial) o Restaurar tasa al valor estándar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxc',5,'cxc','cxc','anular','Revertir cobros deshace los cobros y conciliaciones de una cuenta; Anular factura y CxC relacionada anula ambas con confirmación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxc',6,'cxc',NULL,NULL,'Carga masiva sube muchas facturas de clientes a la vez desde una plantilla de Excel: descargas la plantilla, la completas con las facturas que tienen saldo pendiente y subes el archivo; la pantalla muestra una revisión antes de importar. Cada fila crea la factura y su cuenta por cobrar, y crea al cliente si no existía. Es el mismo botón Carga masiva de Facturación. Exportar descarga la lista.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxc',7,'cxc',NULL,NULL,'En la cuenta por cobrar puedes guardar sustentos con Adjuntar archivo y bajarlos con Descargar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxc',8,'cxc',NULL,NULL,'Para qué sirve: saber cuánto debe cada cliente, qué está vencido y a quién hay que cobrar hoy. Cada factura emitida crea aquí su cuenta por cobrar, y cada cobro registrado baja el saldo y queda como ingreso en el banco.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxc',9,'cxc',NULL,NULL,'Registrar gestión anota una gestión de cobranza (llamada, correo, promesa de pago) y Guardar gestión la conserva; según el resultado pide la fecha de la próxima acción. Confirmar anulación anula la factura con su cuenta por cobrar y revierte sus cobros. Quitar archivo retira el Excel elegido en la carga masiva. Si no hay cuentas bancarias, el enlace «Ve a Parámetros Generales para agregarlas» lleva a crearlas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxc',10,'cxc',NULL,NULL,'Restaurar tasa devuelve la mora a su valor estándar y, como condonar la mora, requiere el permiso de editar en Cuentas por cobrar; si no ves esos botones, tu rol no lo tiene.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cxp','pantalla','cxp','Cuentas por pagar','Registra y controla las deudas con proveedores, colaboradores y tributos: facturas, recibos por honorarios, notas de crédito o débito, detracciones y pagos.','["src/pages_fin.jsx#CxP"]'::jsonb,'d66ee1335d')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',1,'cxp',NULL,NULL,'Usa Nuevo egreso para registrar una obligación. Según el tipo, completa proveedor y factura, el emisor del recibo por honorarios (interno o externo), el tributo y su periodo, o el colaborador del reembolso.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',2,'cxp',NULL,NULL,'Una factura de compra debe vincularse a su orden de compra de origen. La pantalla avisa si el número de factura ya existe para ese proveedor y sociedad.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',3,'cxp',NULL,NULL,'Para pagar usa Pagar en la CxP: elige la cuenta bancaria de origen, la fecha y el monto. Se admiten pagos parciales y el saldo queda pendiente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',4,'cxp',NULL,NULL,'Si la factura está sujeta a detracción (SPOT), registra la obligación con Aplicar detracción y paga al proveedor exactamente el neto; el depósito al Banco de la Nación se registra con la constancia.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',5,'cxp',NULL,NULL,'Registrar NC y Registrar ND ajustan la deuda con notas de crédito o débito del proveedor. Completar factura agrega los datos de una CxP preliminar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',6,'cxp','cxp','editar','Puedes cambiar la Prioridad de pago de una CxP para ordenar qué se paga primero.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',7,'cxp','cxp','anular','Anular una CxP conserva su historial e indica el motivo; antes la pantalla verifica que no tenga pagos ni dependencias que lo impidan.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',8,'cxp',NULL,NULL,'Para cargar muchas deudas a la vez usa Descargar plantilla, complétala y súbela con Subir plantilla masiva; la pantalla muestra las filas válidas y rechazadas antes de importar. Descargar reporte Excel exporta las cuentas y sus pagos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',9,'cxp',NULL,NULL,'Una CxP preliminar se puede borrar con Eliminar CxP preliminar, que elimina el registro; Anular, en cambio, conserva el historial. Guardar clasificación corrige la clasificación de una CxP, y puedes adjuntar archivos a la cuenta con Adjuntar archivo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',10,'cxp',NULL,NULL,'Para qué sirve: controlar todo lo que la empresa debe: facturas de proveedores, recibos por honorarios, obligaciones con colaboradores y tributos, con su vencimiento y su prioridad de pago. Cada pago sale de una cuenta bancaria y queda en Tesorería.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',11,'cxp',NULL,NULL,'Registrar CxP guarda una deuda nueva y Generar CxP la crea desde un documento de origen. Registrar pago anota el pago. Registrar tributo crea una obligación tributaria, y «Registrar como colaborador interno» una deuda con un trabajador. Confirmar nota guarda la nota de crédito o débito y Confirmar obligación la detracción. En la carga masiva, Importar filas válidas crea las que pasaron la revisión y Quitar archivo descarta el Excel. Anular CxP conserva el historial; eliminarla pide escribir el motivo y pulsar Confirmar eliminación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cxp',12,'cxp',NULL,NULL,'Aplicar detracción y Corregir obligación solo aparecen si tu rol tiene el permiso de editar detracciones de compras. No deja pagar una factura con detracción por un monto distinto del neto: la detracción se deposita aparte. No deja registrar una CxP sin número de factura, fechas y monto.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('custodia_terceros','pantalla','inventario','Custodia de terceros','Mercadería de clientes guardada en el almacén (custodia): ingresos, posiciones, retiros, tarifa y liquidación del almacenaje para facturar.','["operaciones-app/src/zahory-mock/pages/wms/CustodiaPage.jsx#CustodiaPage"]'::jsonb,'b96d4c42a1')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('custodia_terceros',1,'inventario',NULL,NULL,'Registrar ingreso anota la mercadería de un tercero que entra en custodia y Asignar posiciones define dónde se guarda.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('custodia_terceros',2,'inventario',NULL,NULL,'Solicitar retiro crea el retiro de esa mercadería.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('custodia_terceros',3,'inventario',NULL,NULL,'Tarifa define lo que se cobra por la custodia.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('custodia_terceros',4,'inventario',NULL,NULL,'Calcular obtiene la liquidación del período y Enviar a Ventas la envía como venta en borrador.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('custodia_terceros',5,'inventario',NULL,NULL,'Para qué sirve: guardar mercadería de un cliente en tus posiciones. No es tuya: no se valoriza en tu inventario y se cobra por posición-día (cada posición ocupada por cada día) y por movimiento (ingresos y retiros).');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('custodia_terceros',6,'inventario',NULL,NULL,'Antes de liquidar, cada cliente necesita su Tarifa: importe por posición-día, importe por movimiento y moneda. Sin tarifa la pantalla avisa «Sin tarifa» y no se puede liquidar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('custodia_terceros',7,'inventario',NULL,NULL,'Registrar ingreso pide cliente, material, cantidad y, si la hay, la guía del cliente; Asignar posiciones indica en qué ubicación queda. Solicitar retiro crea el retiro por la cantidad indicada; lo solicitado queda como Comprometido hasta que se despacha.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('custodia_terceros',8,'inventario',NULL,NULL,'Para cobrar: elige el cliente, el período (Desde y Hasta) y usa Calcular; verás posiciones-día por tarifa, movimientos por tarifa y el total sin IGV. Enviar a Ventas crea una venta en borrador por ese importe más IGV para que Facturación la emita. Un período ya enviado no se envía de nuevo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('custodia_terceros',9,'inventario',NULL,NULL,'Guardar tarifa conserva la tarifa del cliente y Crear retiro registra el retiro solicitado.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('dashboard_gerencial','pantalla','dashboard','Dashboard Gerencial','Indicadores gerenciales de la operación.','["operaciones-app/src/zahory-mock/pages/dashboardGerencial.jsx#DashboardPage"]'::jsonb,'33352eff28')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('dashboard_gerencial',1,'dashboard',NULL,NULL,'Es un tablero de consulta con los indicadores de la operación del período.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('dashboard_gerencial',2,'dashboard',NULL,NULL,'Exportar PDF descarga el tablero.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('dashboard_gerencial',3,'dashboard',NULL,NULL,'Si no hay tipo de cambio para el período, la pantalla lo avisa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('dashboard_gerencial',4,'dashboard',NULL,NULL,'Para qué sirve: dar a gerencia una lectura rápida de la operación del período: órdenes, márgenes, sobrecostos, retrabajo y uso de la flota, con los mismos datos que usa el resto del sistema.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('dashboard_gerencial',5,'dashboard',NULL,NULL,'Si una cifra no cuadra, revisa el período y la sociedad elegidos. Si avisa que no hay tipo de cambio, regístralo para ese período: sin él no se pueden sumar soles y dólares en los totales de referencia.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('dashboard','pantalla','dashboard','Dashboards','Tableros de indicadores de la empresa.','["src/pages_dashboards.jsx#DashboardsPage"]'::jsonb,'063f9e54c0')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('dashboard',1,'dashboard',NULL,NULL,'Es una pantalla de consulta: reúne los tableros de indicadores disponibles para tu rol.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('dashboard',2,'dashboard',NULL,NULL,'No registra información; los datos vienen de lo que se registra en el resto del sistema.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('dashboard',3,'dashboard',NULL,NULL,'Para qué sirve: reunir en una sola entrada los tableros de la empresa (general, comercial, operativo y financiero) para ver los resultados sin armar reportes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('dashboard',4,'dashboard',NULL,NULL,'Cada pestaña es un tablero; solo ves los que tu rol tiene permitidos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('dashboard',5,'dashboard',NULL,NULL,'Si no aparece una pestaña, tu rol no tiene acceso a ese tablero. Si una cifra no cuadra con una pantalla, revisa el período y la sociedad elegidos.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('despachos_almacen','pantalla','inventario','Despachos de almacén','Cola única de salida del almacén: entregas a taller por OT y por OF, ventas con guía de remisión y retiros de custodia, preparadas con picking.','["operaciones-app/src/zahory-mock/pages/wms/DespachosPage.jsx#DespachosPage"]'::jsonb,'9c94c5971c')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('despachos_almacen',1,'inventario',NULL,NULL,'Filtra la cola por canal (OT, OF, Venta o Custodia) y selecciona un pedido para prepararlo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('despachos_almacen',2,'inventario',NULL,NULL,'Escanea el código del material o de la ubicación para marcar lo preparado, o usa Preparar todo lo listo para cargar las cantidades pendientes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('despachos_almacen',3,'inventario','inventario','despachar','Si faltan unidades en una venta, un retiro o una OF, usa Reintentar reserva para reservar lo que ya está disponible.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('despachos_almacen',4,'inventario','inventario','despachar','Despacha el pedido: en OT queda entregado al taller y se actualiza el kardex; en OF, además, se registra la cantidad real del material en la OF y su costo real; en ventas completa la guía de remisión (modalidad, transporte y peso), que se emite con la serie T001 al despachar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('despachos_almacen',5,'inventario',NULL,NULL,'Para qué sirve: sacar del almacén todo lo que se pidió, desde una sola cola: repuestos para una orden de trabajo o de fabricación, mercadería vendida y retiros de custodia. El despacho es lo que baja el stock y, en las órdenes, lo que carga el costo del material.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('despachos_almacen',6,'inventario',NULL,NULL,'Si al escanear dice que el código no corresponde a ninguna línea, ese material no es de este pedido. Si no aparece un pedido en la cola, revisa el filtro de canal y que la orden tenga su reserva hecha. Si faltan unidades, el pedido no se completa hasta que haya stock: usa Reintentar reserva cuando llegue.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('detalle_of','pantalla','of','Detalle de OF','Ficha de una orden de fabricación (OF): estados, ruta de tareas, materiales, material no planificado, aprobación con reserva de stock y SOLPE, registro y revisión de avance por partes, costo real y calidad.','["operaciones-app/src/zahory-mock/pages/of/DetalleOFPage.jsx#DetalleOFPage"]'::jsonb,'7cb18bcc14')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',1,'of',NULL,NULL,'En Ruta arma la secuencia de trabajo con Agregar tarea.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',2,'of',NULL,NULL,'En Materiales agrega lo que consume la orden con Agregar material; lo que no estaba previsto se agrega como Material no planificado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',3,'of',NULL,NULL,'Editar y Quitar corrigen una tarea o un material.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',4,'of',NULL,NULL,'Aprobar OF aprueba la orden.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',5,'of',NULL,NULL,'Estados de la OF: Borrador e Ingeniería son editables; al aprobar pasa a Aprobada y la ruta queda fija. Una OF anulada ya no admite cambios. La línea de tiempo de la cabecera muestra en qué estado va.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',6,'of',NULL,NULL,'La ruta se ordena como Trabajo › Actividad › Tarea. Cada tarea lleva cargo, horas estimadas y, si corresponde, el equipo con que se hace. La bahía no se escribe: sale del equipo elegido, y si la tarea no tiene equipo la ubica el Planner (se lee «La asigna el Planner»).');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',7,'of',NULL,NULL,'Si la OF nació de una OS con Hoja de Costeo llega precargada con las tareas y materiales de la hoja, y toma su moneda; revísala antes de aprobar. Si se creó como OF adicional llega vacía y se arma a mano.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',8,'of',NULL,NULL,'Después de aprobar solo se puede agregar un Material no planificado, y exige escribir el motivo; ese motivo queda visible en la lista de materiales. Para cambiar la ruta de una OF aprobada no hay botón: hay que pedirlo a quien administra el sistema.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',9,'of',NULL,NULL,'Si no ves Aprobar OF es porque tu rol no tiene el permiso de aprobar Órdenes de Fabricación o porque la OF ya no está en Borrador o Ingeniería. Si no ves Agregar tarea, tu rol no puede editar OF.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',10,'of',NULL,NULL,'Con la OF Aprobada o En producción, Registrar avance crea un parte: elige la operación, el técnico, la fecha (no futura), las horas trabajadas y el avance de la operación (0 a 100; con 100 queda terminada). El parte queda Por aprobar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',11,'of',NULL,NULL,'La pestaña Partes lista los partes de la OF con su estado (Por aprobar, Aprobado, Observado). Revisar abre el parte: Aprobar parte suma las horas, actualiza el avance de la operación y de la OF y el costo real; Observar lo devuelve con una observación y el técnico registra uno corregido. Si cambias el avance reportado, la observación es obligatoria.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',12,'of',NULL,NULL,'La OF pasa de Aprobada a En producción con el primer parte aprobado. Desde ahí la cabecera muestra el avance (ponderado por horas estimadas), las horas reales, el costo real a la fecha y los partes por aprobar; la Ruta muestra por tarea las horas reales, una barra de avance y su estado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',13,'of',NULL,NULL,'El costo real suma la mano de obra de los partes aprobados (horas por la tarifa del técnico; si no tiene, la del cargo de la operación) y los materiales despachados. Si no ves Registrar avance tu rol no puede editar OF o todas las operaciones están terminadas; si no ves Revisar, tu rol no tiene el permiso de aprobar OF.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',14,'of',NULL,NULL,'Con la OF en producción, Enviar a calidad la pasa a En calidad; en la pestaña Calidad se registran las mediciones por unidad y las no conformidades. Liberar OF la deja Lista para entrega cuando todas las críticas están dentro de tolerancia y no hay no conformidades abiertas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',15,'of',NULL,NULL,'Al aprobar la OF (botón Aprobar y reservar) se reserva en el almacén el stock de los materiales de origen Stock y lo que falta va a Compras como SOLPE. El aviso de la OF aprobada dice cuántos materiales quedaron reservados y qué SOLPE cubre cada faltante; un Material no planificado de stock se reserva al guardarlo (Agregar y reservar).');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',16,'of',NULL,NULL,'En Materiales, cada material de stock muestra su reserva: Reservado (por despachar), Despachado o Falta con su SOLPE. El almacén entrega el material desde Despachos (canal OF); al despacharlo se registra en el kárdex, se actualiza la cantidad real del material y se suma su costo al costo real de la OF.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',17,'of',NULL,NULL,'Para qué sirve: es el expediente de una orden de fabricación. Aquí se define cómo se fabrica (ruta y materiales), se aprueba, se registra el avance del taller, se controla la calidad y se ve cuánto está costando frente a lo previsto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',18,'of',NULL,NULL,'Anular OF está disponible con el permiso anular de Órdenes de Fabricación en Borrador, En ingeniería, Aprobada o En producción. Pide un Motivo de al menos 5 caracteres. Al confirmar se liberan las reservas de stock y el pedido sale de Despachos; lo ya despachado queda en el kárdex. Las SOLPE de faltantes se anulan desde Compras si ya no se necesitan. No se puede deshacer. La ficha anulada muestra el motivo y la fecha.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',19,'of',NULL,NULL,'Si no ves Anular OF, revisa que tu rol tenga el permiso anular de Órdenes de Fabricación y que la OF esté en Borrador, En ingeniería, Aprobada o En producción.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_of',20,'of',NULL,NULL,'Al recibir una compra de un material que una OF tiene pendiente (Falta con su SOLPE), el almacén lo reserva automáticamente para esa OF si entra al mismo almacén del pedido. Si entró a otro almacén, en Despachos usa Reintentar reserva después de trasladarlo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('detalle_viaje','pantalla','transporte_comercial','Detalle de viaje','Asignación, despacho y reprogramación de un viaje.','["operaciones-app/src/zahory-mock/pages/transporte/ViajeDetallePage.jsx#ViajeDetallePage"]'::jsonb,'c46cd58937')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_viaje',1,'transporte_comercial',NULL,NULL,'Asignar y despachar define la unidad y el conductor y da la salida del viaje.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_viaje',2,'transporte_comercial',NULL,NULL,'Cambiar asignación reemplaza la unidad o el conductor, y Reprogramar cambia la fecha.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_viaje',3,'transporte_comercial',NULL,NULL,'Desde el detalle puedes ir a la Hoja de Ruta o volver al Monitor de Viajes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_viaje',4,'transporte_comercial',NULL,NULL,'Para qué sirve: desde el detalle se asigna quién hace el viaje y se le da la salida. Solo se puede asignar y despachar un viaje que está programado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_viaje',5,'transporte_comercial',NULL,NULL,'Al asignar, el sistema bloquea una unidad o un conductor que esté inactivo, que pertenezca a otro transportista, que ya esté en otro viaje en curso o que tenga el certificado MTC o el brevete vencido.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_viaje',6,'transporte_comercial',NULL,NULL,'En otros casos deja continuar pero pide escribir un motivo de excepción: cuando la unidad no tiene registrada su capacidad o esta no alcanza para la carga, o cuando el MTC o el brevete no tienen fecha de vigencia registrada. En ese caso el botón dice Despachar con excepción.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_viaje',7,'transporte_comercial',NULL,NULL,'Guardar asignación deja la unidad y el conductor definidos sin dar la salida, y queda anotado en la bitácora del viaje. Agregar nota suma una nota a la bitácora sin cambiar el estado. Cancelar viaje pide confirmación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_viaje',8,'transporte_comercial',NULL,NULL,'El sistema no recibe GPS de las unidades: la posición y la hora de llegada que muestra un viaje en ruta son estimadas por el tiempo transcurrido desde la salida. Un incidente deja el viaje en estado con incidente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_viaje',9,'transporte_comercial',NULL,NULL,'Si no puedes despachar, lo más frecuente es un brevete o un MTC vencido: actualiza su vigencia en Transporte › Flota.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('detalle_viaje',10,'transporte_comercial',NULL,NULL,'Cuando un viaje comercial queda entregado, Liquidar abre Liquidación de transporte en la pestaña Por liquidar. En un viaje en liquidación o cerrado, Ver liquidación abre directamente su liquidación activa; si no existe, abre la lista.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('devoluciones_almacen','pantalla','inventario','Devoluciones','Ingreso de mercadería devuelta y su inspección.','["operaciones-app/src/zahory-mock/pages/wms/DevolucionesPage.jsx#DevolucionesPage"]'::jsonb,'895a94a0ee')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('devoluciones_almacen',1,'inventario',NULL,NULL,'Registrar devolución ingresa la mercadería devuelta por un cliente o por una OT; queda en cuarentena para inspección.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('devoluciones_almacen',2,'inventario',NULL,NULL,'Revisa las cantidades de cada línea antes de registrar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('devoluciones_almacen',3,'inventario',NULL,NULL,'Cerrar inspección termina la revisión; en una devolución de venta, Administración recibe el aviso para emitir la nota de crédito.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('devoluciones_almacen',4,'inventario',NULL,NULL,'Para qué sirve: recibir de vuelta mercadería que ya había salido, sea de un cliente o de una orden de trabajo que no la usó, y revisarla antes de devolverla al stock disponible.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('devoluciones_almacen',5,'inventario',NULL,NULL,'Al registrar eliges el origen: Cliente (venta) para lo que devuelve un cliente, u orden de trabajo para lo que regresa del taller. Cerrar panel cierra el formulario sin registrar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('devoluciones_almacen',6,'inventario',NULL,NULL,'No deja registrar si las cantidades de las líneas no son válidas. Si la mercadería devuelta no aparece disponible, sigue en cuarentena: falta Cerrar inspección.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('diagnostico_tecnico','pantalla','diagnostico_tecnico','Diagnóstico Técnico','Evaluación técnica del equipo: hallazgos, trabajos, actividades, informe al cliente y hoja de costeo.','["operaciones-app/src/zahory-mock/pages/DiagnosticoTecnicoPage.jsx#DiagnosticoTecnicoPage"]'::jsonb,'e945eecb6f')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('diagnostico_tecnico',1,'diagnostico_tecnico',NULL,NULL,'Elige si el diagnóstico es de Mantenimiento o de Fabricación y avanza por sus pasos con Siguiente; Abrir borrador retoma uno sin terminar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('diagnostico_tecnico',2,'diagnostico_tecnico',NULL,NULL,'Registra lo encontrado con Agregar hallazgo y guárdalo con Guardar hallazgo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('diagnostico_tecnico',3,'diagnostico_tecnico',NULL,NULL,'Arma los trabajos con Agregar trabajo y sus actividades con Agregar actividad. Un trabajo sin actividades ni tareas impide continuar: agrega una o quita el trabajo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('diagnostico_tecnico',4,'diagnostico_tecnico',NULL,NULL,'Emitir diagnóstico lo cierra. Informe al cliente prepara el informe y Emitir informe lo emite.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('diagnostico_tecnico',5,'diagnostico_tecnico',NULL,NULL,'Generar hoja de costeo crea la Hoja de Costeo del diagnóstico; si ya existe, el botón la abre.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('diagnostico_tecnico',6,'diagnostico_tecnico',NULL,NULL,'Si la empresa operativa está en modo solo lectura no se pueden guardar diagnósticos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('diagnostico_tecnico',7,'diagnostico_tecnico',NULL,NULL,'Para qué sirve: dejar por escrito qué tiene el equipo del cliente y qué trabajos necesita, antes de cotizar. De un diagnóstico de mantenimiento o de fabricación salen el informe al cliente y la Hoja de Costeo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('diagnostico_tecnico',8,'diagnostico_tecnico',NULL,NULL,'Al iniciar eliges la recepción del equipo; si el tipo no es el correcto, Corregir tipo u Otro tipo lo cambian, y Crear borrador y continuar abre el diagnóstico. Los botones «Siguiente: Hallazgos», «Siguiente: Trabajos», «Siguiente: Diagnóstico e informe» y «Siguiente: Revisión e informe» avanzan por los pasos. En un trabajo, «Buscar o crear» encuentra un trabajo del catálogo o lo crea si no existe. Generar con IA redacta el texto del diagnóstico a partir de los hallazgos, para que lo revises antes de emitir. En fabricación, Ver dibujo abre el plano de la pieza y «sin dibujo» indica que no tiene. Guardar cambios y Guardar todo conservan lo editado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('diagnostico_tecnico',9,'diagnostico_tecnico',NULL,NULL,'Agregar trabajo, Agregar actividad, Generar con IA y Guardar todo solo aparecen si tu rol puede editar el diagnóstico y este sigue en borrador. No deja continuar con trabajos sin actividades ni tareas. Un diagnóstico emitido queda de solo lectura.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('disponibilidad_mecanica','pantalla','disponibilidad_mecanica','Disponibilidad mecánica','Disponibilidad contractual de flota y disponibilidad de máquinas del taller.','["operaciones-app/src/zahory-mock/pages/confiabilidad/DisponibilidadMecanicaPage.jsx#DisponibilidadMecanicaPage"]'::jsonb,'36c25270ac')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('disponibilidad_mecanica',1,'disponibilidad_mecanica','ver',NULL,'Para qué sirve: controlar la disponibilidad mecánica que se compromete con el cliente en los contratos de alquiler (DMR) y la disponibilidad de las máquinas propias del taller, para anticipar penalidades y detectar los equipos que están por debajo de la meta. Se usa durante el mes para vigilar el DMR y al cierre junto con la liquidación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('disponibilidad_mecanica',2,'disponibilidad_mecanica','ver',NULL,'Selecciona el período y Flota o Taller para consultar disponibilidad, horas de parada y equipos o máquinas bajo la meta mostrada.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('disponibilidad_mecanica',3,'disponibilidad_mecanica','ver',NULL,'En Flota por equipo y mes consulta horas programadas, paradas, DMR y meta. El DMR es (horas programadas − paradas del proveedor) ÷ horas programadas, expresado en porcentaje.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('disponibilidad_mecanica',4,'disponibilidad_mecanica','ver',NULL,'Las paradas del cliente y las neutrales se muestran por separado; solo las del proveedor reducen el DMR. Ver liquidación abre la liquidación cuando existe.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('disponibilidad_mecanica',5,'disponibilidad_mecanica','ver',NULL,'En Máquinas del taller consulta horas posibles, horas de falla y disponibilidad: (horas posibles − horas de falla) ÷ horas posibles, expresado en porcentaje.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('disponibilidad_mecanica',6,'disponibilidad_mecanica','ver',NULL,'En Cliente se indica que la disponibilidad contractual no aplica; consulta los días entre fallas en KPIs de confiabilidad.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('disponibilidad_mecanica',7,'disponibilidad_mecanica','ver',NULL,'Si no hay datos, revisa el período y los partes o registros de fallas correspondientes. Si aparece Sin liquidación, revisa Liquidación & DMR; si no tienes acceso, revisa la empresa y solicita el permiso de disponibilidad mecánica.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('tenants','pantalla','tenants','Empresas / Tenants','Alta y mantenimiento de las empresas de la plataforma.','["src/pages_admin.jsx#Tenants"]'::jsonb,'859eca11fc')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tenants',1,'tenants',NULL,NULL,'Crea una empresa con Nuevo grupo y Crear grupo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tenants',2,'tenants',NULL,NULL,'Editar cambia sus datos y Eliminar la borra.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tenants',3,'tenants',NULL,NULL,'Reporte plataforma descarga el reporte general.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tenants',4,'tenants',NULL,NULL,'Para qué sirve: es la pantalla del personal de la plataforma para dar de alta a cada empresa cliente del sistema y mantener sus datos. Cada empresa trabaja aislada de las demás.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tenants',5,'tenants',NULL,NULL,'Guardar cambios conserva la edición de una empresa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('tenants',6,'tenants',NULL,NULL,'No aparece esta pantalla para los usuarios de una empresa cliente: es solo de la plataforma. Si al crear o actualizar aparece un error, la pantalla muestra el motivo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('equipos_clientes','pantalla','os_cliente','Equipos de Clientes','Consulta de los equipos de los clientes y su historial de órdenes de servicio.','["src/pages_equipos_clientes.jsx#EquiposClientes"]'::jsonb,'c24d7b5762')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('equipos_clientes',1,'os_cliente',NULL,NULL,'Es una pantalla de consulta: busca por código, equipo o cliente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('equipos_clientes',2,'os_cliente',NULL,NULL,'Muestra los activos en custodia y el historial de OS Cliente de cada equipo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('equipos_clientes',3,'os_cliente',NULL,NULL,'Necesita una empresa activa seleccionada para mostrar datos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('equipos_clientes',4,'os_cliente',NULL,NULL,'Para qué sirve: saber qué equipos de cada cliente han pasado por la empresa y qué trabajos se les hicieron, para cotizar con historial y atender garantías.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('equipos_clientes',5,'os_cliente',NULL,NULL,'Los equipos no se crean aquí: se registran al recibirlos en Recepción de Activos o al crear la OS del cliente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('equipos_clientes',6,'os_cliente',NULL,NULL,'Si no aparece un equipo, revisa que tenga una recepción o una OS registrada y que estés en la empresa correcta. Si la pantalla dice que no se pudieron cargar los equipos, recarga la página.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('resultados','pantalla','resultados','Estado Resultados','Estado de Resultados (ganancias y pérdidas) del mes: ingresos, costos, gastos, utilidad bruta, resultado operativo y neto, con sus márgenes y el detalle de cada línea.','["src/pages_fin.jsx#Resultados"]'::jsonb,'07b83d2f9d')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('resultados',1,'resultados',NULL,NULL,'Elige el período y revisa el resultado por línea.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('resultados',2,'resultados',NULL,NULL,'Abre una línea para ver el detalle de sus gastos y ciérralo con Cerrar detalle.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('resultados',3,'resultados',NULL,NULL,'PDF descarga el reporte.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('resultados',4,'resultados',NULL,NULL,'Para qué sirve: muestra si la empresa ganó o perdió en un mes. Se lee de arriba abajo: Ingresos menos Costo de ventas da la Utilidad bruta; menos Gastos operativos da el Resultado operativo; luego se restan los Gastos financieros y la Depreciación hasta el Resultado neto. Cada resultado muestra su margen, que es su porcentaje sobre los ingresos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('resultados',5,'resultados',NULL,NULL,'De dónde sale cada cifra: los ingresos son las facturas y boletas emitidas en el mes, sin IGV y sin las anuladas, más las ventas cobradas sin comprobante. Los costos y gastos salen de lo registrado en Compras y Gastos, cuentas por pagar, caja chica, la planilla del período y los costos de las órdenes de trabajo; los gastos financieros incluyen los intereses de los préstamos pagados en el mes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('resultados',6,'resultados',NULL,NULL,'Si una cifra no cuadra, revisa primero la categoría del gasto: cada egreso cae en la línea que indica su categoría del Estado de Resultados, que se elige al registrarlo. Un gasto mal categorizado aparece en la línea equivocada; abre la línea para ver su detalle y ubicar el registro.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('resultados',7,'resultados',NULL,NULL,'Soles y dólares se muestran por separado y no se suman. Los filtros de centro de costo y de centro de beneficio permiten ver el resultado de un área o de una línea de negocio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('resultados',8,'resultados',NULL,NULL,'En empresas con varias sociedades eliges ver una sociedad, compararlas lado a lado o el consolidado, que elimina las operaciones entre sociedades del grupo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('resultados',9,'resultados',NULL,NULL,'Solo lo ven los roles con acceso a Estado de Resultados y con permiso para ver finanzas. También puedes pedírselo a Aria (por ejemplo «¿cuál fue la utilidad de octubre?»): usa este mismo cálculo, para la sociedad activa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('resultados',10,'resultados',NULL,NULL,'El selector de centros de costo y de beneficio muestra cuántos hay elegidos («seleccionados»); al abrirlo marcas los que quieres ver. Cada línea indica cuántos registros de ingreso o de gasto la componen.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('etiquetas_almacen','pantalla','inventario','Etiquetas','Impresión de etiquetas del almacén.','["operaciones-app/src/zahory-mock/pages/wms/EtiquetasPage.jsx#EtiquetasPage"]'::jsonb,'3cbd212622')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('etiquetas_almacen',1,'inventario',NULL,NULL,'Marca las etiquetas que necesitas; debes marcar al menos una.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('etiquetas_almacen',2,'inventario',NULL,NULL,'Descargar PDF genera el archivo para imprimir.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('etiquetas_almacen',3,'inventario',NULL,NULL,'Para qué sirve: imprimir las etiquetas con código que se pegan en ubicaciones y materiales, para trabajar el almacén escaneando en vez de escribiendo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('etiquetas_almacen',4,'inventario',NULL,NULL,'Las etiquetas de ubicación identifican cada posición y las de material cada artículo; se generan en un PDF listo para imprimir.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('etiquetas_almacen',5,'inventario',NULL,NULL,'No deja descargar sin marcar al menos una etiqueta. Si no aparece una ubicación o un material para etiquetar, primero debe existir en Ubicaciones o en el maestro de materiales.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('evaluaciones_desempeno','pantalla','evaluaciones_desempeno','Evaluación de Desempeño','Plantillas de evaluación, autoevaluación, evaluación del jefe y resultados.','["src/pages_evaluaciones.jsx#EvaluacionesDesempeno"]'::jsonb,'fcea293bf5')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('evaluaciones_desempeno',1,'evaluaciones_desempeno',NULL,NULL,'Quien administra crea la evaluación con Nueva plantilla: Agregar competencia y Agregar objetivo definen qué se evalúa, y Crear y activar plantilla la pone en marcha.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('evaluaciones_desempeno',2,'evaluaciones_desempeno',NULL,NULL,'Cada colaborador usa Autoevaluarme; puede Guardar borrador y, una vez enviada, ya no puede editarla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('evaluaciones_desempeno',3,'evaluaciones_desempeno',NULL,NULL,'El jefe usa Evaluar; al enviar su evaluación tampoco puede editarla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('evaluaciones_desempeno',4,'evaluaciones_desempeno',NULL,NULL,'Cerrar plantilla publica los resultados a los colaboradores, que los ven con Ver resultado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('evaluaciones_desempeno',5,'evaluaciones_desempeno',NULL,NULL,'Exportar Excel descarga los resultados.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('evaluaciones_desempeno',6,'evaluaciones_desempeno',NULL,NULL,'Para qué sirve: evaluar una vez por período a cada colaborador por competencias y objetivos, con su autoevaluación y la de su jefe, y dejar el resultado en su historial.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('evaluaciones_desempeno',7,'evaluaciones_desempeno',NULL,NULL,'Al armar la plantilla, Bajar cambia el orden de una competencia u objetivo. Completar abre una evaluación pendiente y Enviar evaluacion del jefe la entrega; una vez enviada no se puede editar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('evaluaciones_desempeno',8,'evaluaciones_desempeno',NULL,NULL,'Nueva plantilla solo aparece si tu rol puede administrar evaluaciones. Si un colaborador no ve su resultado, falta Cerrar plantilla, que es lo que publica los resultados.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('facturacion','pantalla','facturacion','Facturación','Emite y consulta los comprobantes de venta, genera su cuenta por cobrar, registra cobros y autodetracciones, emite notas de crédito o débito y permite la carga masiva de facturas desde Excel.','["src/pages_fin.jsx#Facturacion"]'::jsonb,'e697a23316')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('facturacion',1,'facturacion','facturacion','crear','Emite un comprobante desde una valorización, desde una venta o como comprobante directo eligiendo cliente y partidas. El número es obligatorio y se necesita al menos una partida; no se emite a un cliente con la cuenta bloqueada, y la pantalla pide confirmar un número repetido o un monto que excede el saldo de la OS.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('facturacion',2,'facturacion',NULL,NULL,'Desde el comprobante usa Generar CxC para crear la cuenta por cobrar; Ver CxC la abre si ya existe.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('facturacion',3,'facturacion',NULL,NULL,'Registrar cobro deja constancia del pago del cliente. Si el cliente no depositó la detracción, usa Registrar autodetracción con las cuentas y la constancia del depósito.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('facturacion',4,'facturacion',NULL,NULL,'Nota de Crédito y Nota de Débito emiten un ajuste vinculado al comprobante original. Una nota de crédito por devolución puede generar la cuenta por pagar al cliente si tienes permiso de cuentas por pagar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('facturacion',5,'facturacion','facturacion','editar','Editar permite corregir datos del comprobante; Anular lo deja sin efecto con confirmación, y Restaurar lo devuelve a emitido.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('facturacion',6,'facturacion',NULL,NULL,'Ver OS y Ver valorización abren la orden de servicio o la valorización que originó la factura. Puedes adjuntar archivos al comprobante.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('facturacion',7,'facturacion','facturacion','crear','Para subir muchas facturas de clientes a la vez usa Carga masiva, en la lista de Facturación: descarga la plantilla de Excel, complétala con las facturas que tienen saldo pendiente y sube el archivo. La pantalla muestra una revisión antes de importar; cada fila crea la factura y su cuenta por cobrar, y crea al cliente si no existía. El mismo botón está en Cuentas por cobrar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('facturacion',8,'facturacion',NULL,NULL,'Para qué sirve: emitir las facturas, boletas y notas de crédito o débito de la empresa. Cada comprobante emitido crea su cuenta por cobrar y cuenta como ingreso del mes en el Estado de Resultados.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('facturacion',9,'facturacion',NULL,NULL,'En una factura directa, Agregar partida suma una línea al comprobante. Ver factura abre el comprobante. Registrar pago anota el cobro desde aquí. Confirmar anulación anula la factura y su cuenta por cobrar. Quitar archivo retira el Excel elegido en la carga masiva.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cs_fidelizacion','pantalla','cs_fidelizacion','Fidelizacion y NPS','Encuestas de satisfacción y oportunidades que nacen de clientes satisfechos.','["src/pages_cs.jsx#CSFidelizacion"]'::jsonb,'7031d7e4c6')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_fidelizacion',1,'cs_fidelizacion',NULL,NULL,'Enviar encuesta manda la encuesta de satisfacción a un cliente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_fidelizacion',2,'cs_fidelizacion',NULL,NULL,'En los casos de éxito, Solicitar autorización al cliente pide su permiso para publicar el caso.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_fidelizacion',3,'cs_fidelizacion',NULL,NULL,'Convertir a lead crea un prospecto en Leads.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_fidelizacion',4,'cs_fidelizacion',NULL,NULL,'Para qué sirve: medir qué tan satisfechos están los clientes con una encuesta corta y aprovechar a los más contentos: pedirles un caso de éxito o una recomendación que se convierte en un nuevo prospecto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_fidelizacion',5,'cs_fidelizacion',NULL,NULL,'El NPS resume en un número cuántos clientes recomendarían a la empresa frente a cuántos no.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_fidelizacion',6,'cs_fidelizacion',NULL,NULL,'Si no aparece un cliente para enviarle la encuesta, revisa que exista como cuenta activa en Cuentas y Contactos.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('financiamiento','pantalla','financiamiento','Financiamiento y Deuda','Registra los préstamos, leasing y líneas de crédito de la empresa, agrupados por acreedor, con su cronograma, sus pagos y el reporte de deuda por moneda.','["src/pages_fin_deuda.jsx#FinanciamientoDeuda","src/pages/financiamiento/FinanciamientoListado.jsx#FinanciamientoListado","src/pages/financiamiento/FinanciamientoDetalle.jsx#FinanciamientoDetalle","src/pages/financiamiento/FinanciamientoAsistente.jsx#FinanciamientoAsistente","src/pages/financiamiento/FinanciamientoPago.jsx#FinanciamientoPago"]'::jsonb,'e70663fd74 28c6bf4edc 482865b9e7 13ebb51f4c 727b981b96')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',1,'financiamiento',NULL,NULL,'Revisa arriba el capital pendiente, lo que vence este mes, los intereses del mes, lo vencido y los préstamos activos; los importes se muestran por moneda. Los préstamos se agrupan por acreedor: toca un acreedor para ver u ocultar sus préstamos, usa Vigentes, Cancelados o Todos y busca por acreedor, código o banco.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',2,'financiamiento','financiamiento','crear','Usa Nuevo préstamo para abrir el asistente de cuatro pasos. En Acreedor indicas quién presta (banco, persona o tercero, leasing) y, si aplica, la sociedad. En Condiciones eliges la modalidad: cuota fija, cuota decreciente, solo intereses con vencimiento o interés sobre saldo sin plazo (cada mes se paga un porcentaje del capital que se debe y el capital se amortiza cuando se puede); luego la moneda, el monto, la fecha, la tasa (TEA, TNA o TEM; en interés sobre saldo, la tasa mensual), el día de pago o de corte y, en las modalidades con cuotas, el plazo y los meses de gracia. En Desembolso eliges la cuenta de Tesorería donde entró el dinero y, si lo marcas, se registra el ingreso (con tipo de cambio si la cuenta está en otra moneda). En Revisión ves el resumen y las primeras cuotas antes de registrar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',3,'financiamiento',NULL,NULL,'Toca un préstamo para abrir su detalle: arriba ves el saldo de capital, el próximo pago, el capital amortizado y los intereses pagados; en Movimientos, lo que falta pagar y lo ya pagado; en Cronograma, cada cuota o período con su estado; a la derecha, las condiciones del préstamo. Un préstamo vencido sin pagar aparece como Atrasado con los días de atraso.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',4,'financiamiento','financiamiento','editar','En el detalle usa Registrar pago, o toca una cuota o un período pendiente en Cronograma. En interés sobre saldo eliges Interés del mes, Abono a capital o Interés + capital; el interés del período se calcula sobre el saldo al corte y el capital abonado baja el interés de los meses siguientes. En las demás modalidades eliges Cuota pactada, Abono a capital (se recalculan las cuotas que faltan) o Cancelar el capital. Siempre eliges la cuenta de Tesorería y, si está en otra moneda, el tipo de cambio; el pago genera el egreso en Tesorería y, si incluye interés, el gasto financiero.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',5,'financiamiento','financiamiento','editar','En el detalle del préstamo usa Editar: se abre el mismo asistente con los datos cargados y puedes saltar a cualquier paso. Las cuotas pagadas no cambian y las pendientes se recalculan sobre el saldo que queda; si ya tiene pagos, no se puede cambiar la moneda ni pasar entre interés sobre saldo y cuotas. Si sales con cambios sin guardar, el sistema te pide confirmar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',6,'financiamiento','financiamiento','anular','En el detalle del préstamo usa Eliminar. Tras la primera confirmación, una segunda alerta detalla todo lo que se borrará: cuotas, pagos, egresos de Tesorería por cuenta (cuyo saldo subirá) y gastos de intereses. Marca que lo entiendes y confirma; la acción no se puede deshacer.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',7,'financiamiento',NULL,NULL,'En la pestaña Documentos del detalle puedes descargar el contrato, el cronograma del banco u otros respaldos. Usa Reporte de deuda para ver el resumen por moneda, la deuda por acreedor y el calendario de pagos; desde ahí, Exportar reporte Excel descarga el reporte.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',8,'financiamiento','financiamiento','editar','En la pestaña Documentos usa Adjuntar para subir un PDF, imagen, Word, Excel o ZIP de hasta 20 MB, y Eliminar para quitar un documento. Al eliminar el préstamo también se borran sus documentos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',9,'financiamiento',NULL,NULL,'Para qué sirve: controlar la deuda de la empresa con bancos y otros acreedores: cuánto se debe, en qué moneda, qué cuota vence y cuánto se paga de interés. Los intereses pagados entran al Estado de Resultados como gasto financiero.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('financiamiento',10,'financiamiento',NULL,NULL,'Guardar cambios conserva la edición de un préstamo. En el registro de un pago, «Todo el saldo» llena el importe con lo que falta por pagar. Eliminar pide Eliminar definitivamente y borra el préstamo con sus cuotas, pagos y movimientos de banco vinculados.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('flota_transporte','pantalla','transporte_comercial','Flota de transporte','Unidades, conductores y transportistas del transporte.','["operaciones-app/src/zahory-mock/pages/transporte/FlotaPage.jsx#FlotaPage"]'::jsonb,'56162d01ba')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('flota_transporte',1,'transporte_comercial',NULL,NULL,'Nueva unidad, Nuevo conductor y Nuevo transportista registran cada uno; solo aparecen si tu rol puede crear.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('flota_transporte',2,'transporte_comercial',NULL,NULL,'La lista distingue lo propio de lo de terceros y avisa de documentos por vencer, como el certificado MTC o el brevete.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('flota_transporte',3,'transporte_comercial',NULL,NULL,'Revisar abre el registro que tiene una alerta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('flota_transporte',4,'transporte_comercial',NULL,NULL,'Para qué sirve: aquí se mantienen los transportistas, las unidades y los conductores que se asignan a los viajes. Cada unidad lleva placa, tipo, certificado MTC con su vigencia y su capacidad en toneladas y en metros cúbicos; cada conductor, su brevete con categoría y vigencia.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('flota_transporte',5,'transporte_comercial',NULL,NULL,'Mantén al día las vigencias y la capacidad: un MTC o un brevete vencido impide despachar, y una capacidad sin registrar obliga a justificar una excepción en cada despacho.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('flota_transporte',6,'transporte_comercial',NULL,NULL,'Una unidad o un conductor que ya no se usa se inactiva, no se elimina, porque los viajes y las guías de remisión anteriores lo siguen referenciando. Lo que registres aquí también aparece al emitir guías de remisión.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('flota_transporte',7,'transporte_comercial',NULL,NULL,'Nueva unidad, Nuevo conductor y Nuevo transportista solo aparecen si tu rol tiene el permiso de crear. Si no aparece una unidad o un conductor al asignar un viaje, revisa aquí que esté activo y, si es de un tercero, que su transportista esté registrado.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('gemelo_digital','pantalla','inventario','Gemelo digital','Plano del almacén con sus posiciones, su stock y la ruta hacia cada ubicación.','["operaciones-app/src/zahory-mock/pages/gemelo/GemeloAlmacenPage.jsx#GemeloAlmacenPage"]'::jsonb,'94a9ef772e')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gemelo_digital',1,'inventario',NULL,NULL,'Muestra el plano del almacén con las posiciones que tienen stock y las que están bajo su punto de reorden. Vista 3D cambia a la vista en tres dimensiones.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gemelo_digital',2,'inventario',NULL,NULL,'Ruta desde la puerta traza el camino hasta una posición.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gemelo_digital',3,'inventario',NULL,NULL,'Editor de plano o Dibujar el plano permite armar el plano; al guardarlo se crean, actualizan o desactivan las ubicaciones.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gemelo_digital',4,'inventario',NULL,NULL,'Ver con datos de ejemplo muestra un almacén de muestra y Volver a mis datos regresa al tuyo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gemelo_digital',5,'inventario',NULL,NULL,'Para qué sirve: ver el almacén como un plano, saber dónde está cada cosa y cuánto hay, y llegar a una posición sin buscarla. Sirve para ubicar material, para detectar posiciones vacías y para entrenar a personal nuevo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gemelo_digital',6,'inventario',NULL,NULL,'Los indicadores de arriba muestran el porcentaje de posiciones con stock y cuántas están bajo reorden; al pulsarlos se resaltan en el plano. En el editor, Descartar y salir cierra sin guardar los cambios del plano.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gemelo_digital',7,'inventario',NULL,NULL,'Si no ves posiciones en el plano, aún no se ha dibujado: usa Dibujar el plano. Si una posición no muestra stock, revisa que el material tenga esa ubicación asignada.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('gestion_garantias','pantalla','garantias_flota','Gestión de Garantías','Garantías de los equipos y sus reclamos.','["operaciones-app/src/zahory-mock/pages/flota/GarantiasFlotaPage.jsx#GarantiasFlotaPage"]'::jsonb,'0d2ed03b84')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_garantias',1,'garantias_flota',NULL,NULL,'Registrar garantía anota una garantía; Renovar la extiende y Anular la deja sin efecto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_garantias',2,'garantias_flota',NULL,NULL,'Sobre una garantía vigente, Liberar y Ejecutar registran su liberación o su ejecución, cada una con su motivo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_garantias',3,'garantias_flota',NULL,NULL,'Registrar reclamo abre un reclamo y Actualizar estado lo hace avanzar; algunos estados exigen escribir la resolución.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_garantias',4,'garantias_flota',NULL,NULL,'Catálogo de tipos define los tipos de garantía: Nuevo tipo crea uno y Cargar tipos sugeridos trae una lista base.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_garantias',5,'garantias_flota',NULL,NULL,'Para qué sirve: llevar las garantías de los equipos, tanto las que cubren a la empresa como las que respaldan un contrato, y los reclamos que se hacen sobre ellas, para no perder una cobertura por dejar pasar la fecha.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_garantias',6,'garantias_flota',NULL,NULL,'Una garantía vigente termina de tres formas: se libera, se ejecuta o vence; Renovar la extiende antes de que venza.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_garantias',7,'garantias_flota',NULL,NULL,'Editar solo aparece si tu rol tiene el permiso de editar garantías. No deja pasar un reclamo a ciertos estados sin escribir la resolución. Si no aparece un tipo de garantía, créalo en Catálogo de tipos.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('gestion_partes_taller','pantalla','partes','Gestión de partes de taller','Lista de partes diarios del taller para revisarlos: aprobar, observar, rechazar o reabrir un parte.','["operaciones-app/src/zahory-mock/pages/pages2_v2.jsx#GestionPartesTallerPage"]'::jsonb,'5ebecf6ab0')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_partes_taller',1,'partes',NULL,NULL,'La lista muestra los partes diarios del taller.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_partes_taller',2,'partes',NULL,NULL,'Nuevo Parte Diario registra un parte y Ver detalle del Parte Diario lo abre.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_partes_taller',3,'partes',NULL,NULL,'Desde aquí el jefe de taller revisa los partes: los que están En revisión esperan su decisión. Aprobar confirma horas y avance; Observar y Rechazar exigen escribir el motivo, que el técnico verá para corregir.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_partes_taller',4,'partes',NULL,NULL,'Solo aprueba, observa, rechaza o reabre quien tiene el permiso de aprobar Partes. Si no ves esos botones, pide ese permiso en Roles y permisos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_partes_taller',5,'partes',NULL,NULL,'Para saber qué OT no tienen parte en los últimos días, pregúntale a Aria por las OT sin parte, o filtra la bandeja de OT por las que están en ejecución y revisa su pestaña de partes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('gestion_partes_taller',6,'partes',NULL,NULL,'Para qué sirve: que el jefe de taller revise cada día lo que reportaron los técnicos. Solo los partes aprobados cuentan en el avance y en el costo real de la OT, así que revisar a tiempo mantiene los costos al día.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cs_health','pantalla','cs_health','Health Score','Puntaje de salud de cada cliente y planes de retención.','["src/pages_cs.jsx#CSHealthScore"]'::jsonb,'05155164d5')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_health',1,'cs_health',NULL,NULL,'La lista muestra el puntaje de salud de cada cliente; Ver detalle abre su desglose.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_health',2,'cs_health',NULL,NULL,'Crear plan retención inicia un plan para un cliente en riesgo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_health',3,'cs_health',NULL,NULL,'Exportar descarga la lista.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_health',4,'cs_health',NULL,NULL,'Para qué sirve: detectar a tiempo qué clientes están en riesgo de irse. Cada cliente tiene un puntaje de salud; los de puntaje bajo necesitan un plan de retención.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_health',5,'cs_health',NULL,NULL,'Ver detalle muestra de qué se compone el puntaje del cliente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_health',6,'cs_health',NULL,NULL,'Si no aparece un cliente, revisa que su cuenta esté activa. Si no ves datos, aún no se ha calculado el puntaje de ese cliente.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('hoja_costeo_lista','pantalla','hoja_costeo','Hoja de Costeo (listado)','Listado de hojas de costeo, su revisión, aprobación y paso a cotización.','["src/pages_extra.jsx#HojaCosteo"]'::jsonb,'6a72bdfbb6')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo_lista',1,'hoja_costeo',NULL,NULL,'La lista muestra las hojas de costeo. El indicador Por cotizar filtra las aprobadas que aún no tienen cotización.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo_lista',2,'hoja_costeo',NULL,NULL,'Abrir wizard lleva a la hoja en el asistente de costeo paso a paso.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo_lista',3,'hoja_costeo',NULL,NULL,'Agregar línea suma una línea de costo y Guardar y Continuar conserva el avance.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo_lista',4,'hoja_costeo',NULL,NULL,'Enviar a revision la manda a revisión, Aprobar Costeo la aprueba y Volver a borrador la devuelve para corregir.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo_lista',5,'hoja_costeo',NULL,NULL,'Con la hoja aprobada, Generar Cotización crea la cotización. PDF descarga la hoja.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo_lista',6,'hoja_costeo',NULL,NULL,'Para qué sirve: reunir todas las hojas de costeo y su estado, para saber cuáles faltan revisar, cuáles están aprobadas y cuáles aún no se cotizaron. La hoja define el costo y el margen antes de ofrecer un precio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo_lista',7,'hoja_costeo',NULL,NULL,'Eliminar linea quita una línea de costo de la hoja y Limpiar filtros quita los filtros del listado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo_lista',8,'hoja_costeo',NULL,NULL,'Si no ves Aprobar Costeo, la hoja no está en revisión o tu rol no tiene permiso de aprobar. No deja generar la cotización de una hoja que no está aprobada.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('hoja_costeo','pantalla','hoja_costeo','Hoja de Costeo','Costeo de un servicio: trabajos, materiales, gasto administrativo y margen, hasta su aprobación.','["src/pages_hoja_costeo_wizard.jsx#HojaCosteoWizard"]'::jsonb,'c181c07274')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo',1,'hoja_costeo',NULL,NULL,'Agrega los trabajos con Agregar trabajo: cada uno necesita tarea, cargo y horas mayores a cero. Si el cargo no tiene costo por hora, la pantalla lo avisa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo',2,'hoja_costeo',NULL,NULL,'Agrega los materiales con Agregar material indicando descripción, cantidad, unidad y un costo unitario mayor a cero.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo',3,'hoja_costeo',NULL,NULL,'Define el porcentaje de gasto administrativo y el de margen; la suma de ambos debe ser menor a 100 %.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo',4,'hoja_costeo',NULL,NULL,'Si la hoja nació de un diagnóstico, Actualizar desde el diagnóstico trae sus cambios.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo',5,'hoja_costeo',NULL,NULL,'Usa Enviar a revisión; solo después se puede aprobar con Aprobar hoja. Crear nueva versión abre una versión nueva de la hoja y Generar cotización especial crea la cotización a partir de ella.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo',6,'hoja_costeo',NULL,NULL,'Para qué sirve: calcular cuánto cuesta un servicio antes de cotizarlo, sumando mano de obra, materiales, depreciación de equipos y gasto administrativo, y fijar el margen. El resultado es el precio que pasa a la cotización.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo',7,'hoja_costeo',NULL,NULL,'El trabajo se arma en tres niveles: Trabajo › Actividad › Tarea. Crear trabajo, Crear actividad y Crear tarea agregan uno nuevo al catálogo desde aquí. Al elegir una actividad con receta, Aplicar actividad trae sus tareas; Agregar tareas y Agregar a la tarea suman tareas sueltas. Los enlaces «actividades ›» y «tareas en receta ›» muestran lo que contiene cada nivel. Eliminar material quita un material. Abrir diagnóstico lleva al diagnóstico del que nació la hoja. Cerrar panel y Cerrar menú cierran los paneles laterales.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_costeo',8,'hoja_costeo',NULL,NULL,'No deja guardar un trabajo sin tarea, cargo y horas mayores a cero, ni un material sin descripción, cantidad, unidad y costo. Si avisa que un activo no tiene costo por hora, cárgalo en Variables de Costeo. Si no ves Aprobar hoja, primero hay que usar Enviar a revisión y tener permiso de aprobar.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('hoja_ruta','pantalla','transporte_comercial','Hoja de Ruta','Programación diaria de las rutas de transporte y logística.','["operaciones-app/src/zahory-mock/pages/transporte/HojaDeRutaPage.jsx#HojaDeRutaPage"]'::jsonb,'fb0b722c0a')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_ruta',1,'transporte_comercial',NULL,NULL,'Crea una ruta del día y agrégale pedidos con Agregar; Nueva ruta de logística crea una ruta propia de logística.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_ruta',2,'transporte_comercial',NULL,NULL,'Asignar define la unidad y el conductor de la ruta, y Editar la modifica.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_ruta',3,'transporte_comercial',NULL,NULL,'Hoja imprime la hoja de una ruta e Imprimir hojas del día las de todo el día.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_ruta',4,'transporte_comercial',NULL,NULL,'Para qué sirve: armar las rutas de cada día: qué unidad y qué conductor llevan qué pedidos y en qué orden, tanto para viajes de clientes como para recojos y entregas propios de logística.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_ruta',5,'transporte_comercial',NULL,NULL,'Un pedido se puede retirar de la ruta mientras no haya salido; al retirarlo vuelve a quedar pendiente de programar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('hoja_ruta',6,'transporte_comercial',NULL,NULL,'Si no aparece un pedido para agregarlo, ya está en otra ruta o no está listo para despacho. Si no deja asignar una unidad o un conductor, revisa en Flota de transporte que estén activos.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('inicio_operaciones','pantalla','app_operativo','Inicio de Operaciones con Aria','Muestra tu día en Operaciones: resumen de Aria, indicadores, pendientes por resolver de taller, producción, almacén, transporte, flota y compras, avisos, tus OT y accesos rápidos.','["operaciones-app/src/InicioOperaciones.jsx#InicioOperaciones","src/inicio/Inicio.jsx#InicioBase","src/inicio/datos.js"]'::jsonb,'29fababf8c 6912d1acde ab320441f0')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',1,'app_operativo',NULL,NULL,'Al entrar a Operaciones se abre Inicio. Aria te saluda y resume tu día; Escuchar mi día lo lee en voz alta y Preséntame mi día recorre contigo los indicadores y pendientes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',2,'app_operativo',NULL,NULL,'Los indicadores muestran tus pendientes, las OT en ejecución, los partes por revisar y los repuestos por despachar. Cada uno aparece solo si tienes permiso para ver esa información.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',3,'app_operativo',NULL,NULL,'En Por resolver elige Míos para ver lo asignado a ti o Mi área para ver todo lo de tu área, y filtra por Taller, Almacén, Producción, Transporte, Flota o Compras. El botón de cada pendiente abre la pantalla donde se resuelve; el reloj lo pospone hasta mañana.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',4,'app_operativo',NULL,NULL,'La bandeja reúne partes diarios por revisar, órdenes de fabricación con compromiso vencido, viajes programados sin iniciar, reservas de repuestos por despachar, diagnósticos técnicos en borrador, SOLPE por aprobar, certificaciones de equipos que vencen en 30 días y OT en ejecución sin parte desde ayer.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',5,'app_operativo',NULL,NULL,'En la columna derecha, Aria te avisa de certificaciones por vencer, viajes atrasados y OT con mucho tiempo en ejecución; Mi día lista tus OT programadas y en ejecución, y Accesos rápidos te lleva al Planner, a Nueva OT, a la Bandeja de OT y al Monitor de viajes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',6,'app_operativo',NULL,NULL,'Para preguntar o registrar algo usa el cuadro Pregúntale a Aria o el robot de Aria, que está disponible en todas las pantallas de Operaciones.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',7,'app_operativo',NULL,NULL,'En celular y tablet el menú se abre con el botón ☰ de arriba a la izquierda; ahí también están las notificaciones, el modo oscuro y la salida.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',8,'app_operativo',NULL,NULL,'Para qué sirve: empezar el día sabiendo qué te toca. Reúne en una pantalla tus pendientes de todas las áreas de Operaciones para que no tengas que revisar pantalla por pantalla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',9,'app_operativo',NULL,NULL,'Cada pendiente trae su acción: Abrir OT, Abrir monitor de viajes, Ver certificación o Ver orden de compra llevan directo al registro. Posponer para mañana lo saca de la lista por hoy. Enviar manda tu pregunta a Aria.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inicio_operaciones',10,'app_operativo',NULL,NULL,'Si no aparece un pendiente que esperabas, cambia entre Míos y Mi área y revisa el filtro de área: solo se muestran las áreas que tu rol puede ver. Si la pantalla dice que no se pudo cargar tu inicio, inténtalo de nuevo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('inventario_kardex','pantalla','inventario','Inventario & Kardex','Existencias por material y sus movimientos.','["operaciones-app/src/zahory-mock/pages/InventarioKardexPage.jsx#InventarioKardexPage"]'::jsonb,'8dad26c438')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_kardex',1,'inventario',NULL,NULL,'La pestaña Stock muestra las existencias y Kardex los movimientos de cada material.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_kardex',2,'inventario',NULL,NULL,'Registrar entrada y Registrar salida registran movimientos manuales; Mover traslada stock y Ajustar stock corrige una diferencia.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_kardex',3,'inventario',NULL,NULL,'Liberar devuelve stock reservado al disponible.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_kardex',4,'inventario',NULL,NULL,'Antes de registrar un movimiento debes elegir una sociedad concreta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_kardex',5,'inventario',NULL,NULL,'Para qué sirve: saber cuánto hay de cada material, cuánto está reservado y cuánto disponible, y ver cada movimiento que lo explica. El kardex es la prueba de por qué el stock es el que es.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_kardex',6,'inventario',NULL,NULL,'El disponible es el stock menos lo reservado para órdenes y pedidos. Una reserva baja el disponible pero no el stock: el stock baja recién con el despacho.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('inventario_kardex',7,'inventario',NULL,NULL,'No deja registrar un movimiento sin elegir una sociedad concreta en el selector superior. Si el stock no cuadra con lo físico, revisa el Kardex del material y, si la diferencia es real, corrígela con un conteo o con Ajustar stock.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('kpis_confiabilidad','pantalla','confiabilidad_kpis','KPIs de confiabilidad','Indicadores y registro de fallas por período, equipo y segmento.','["operaciones-app/src/zahory-mock/pages/confiabilidad/KpisConfiabilidadPage.jsx#KpisConfiabilidadPage"]'::jsonb,'cc74ea7017')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('kpis_confiabilidad',1,'confiabilidad_kpis','ver',NULL,'Para qué sirve: medir qué tan confiables son los equipos y si el mantenimiento está funcionando: cuántas fallas hubo, cada cuántas horas falla un equipo (MTBF), cuánto tarda en volver a operar (MTTR), su disponibilidad y la proporción de mantenimiento preventivo frente al correctivo. Se usa en las revisiones mensuales de mantenimiento y para decidir en qué equipos o sistemas actuar primero.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('kpis_confiabilidad',2,'confiabilidad_kpis','ver',NULL,'Selecciona el período y el segmento de Flota en alquiler, Máquinas de taller o Equipos de clientes. En Resumen consulta indicadores, tendencias y gráficos de fallas y mantenimiento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('kpis_confiabilidad',3,'confiabilidad_kpis','ver',NULL,'MTBF es horas operadas ÷ fallas y MTTR es horas de parada ÷ fallas. Para equipos de clientes se usan días entre fallas, pues no se dispone de horas operadas ni disponibilidad contractual propias.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('kpis_confiabilidad',4,'confiabilidad_kpis','ver',NULL,'En Por equipo busca y abre un equipo para revisar su detalle; en Calidad de datos identifica información pendiente de completar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('kpis_confiabilidad',5,'confiabilidad_kpis','ver',NULL,'Registro de fallas reúne fallas de OT correctivas con equipo, paradas del proveedor en partes de flota y registros manuales. Vincular una parada a su OT evita contar el mismo evento dos veces.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('kpis_confiabilidad',6,'backlog','crear',NULL,'En Registro de fallas usa Registrar falla para registrar una parada manual, por ejemplo de un torno o CNC; completa los datos solicitados y guarda.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('kpis_confiabilidad',7,'backlog','editar',NULL,'Según el estado y origen de la falla, usa Cerrar, Vincular a OT o Anular. Vincula la parada a la OT correspondiente cuando ambas describen el mismo evento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('kpis_confiabilidad',8,'confiabilidad_kpis','ver',NULL,'Si faltan datos o gráficos, revisa el período, el segmento y los registros de origen. Si no puedes entrar o falta una acción, revisa la empresa y los permisos de consulta de KPIs y de creación o edición de backlog.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('leads','pantalla','leads','Leads y Scoring','Registro y seguimiento de prospectos hasta convertirlos en clientes o descartarlos.','["src/pages_core.jsx#Leads"]'::jsonb,'5cd977019c')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('leads',1,'leads',NULL,NULL,'Registra un prospecto con Nuevo lead. Puedes verlos en Lista o en Kanban y acotar con Filtros.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('leads',2,'leads',NULL,NULL,'Registrar Actividad deja constancia de cada contacto con el prospecto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('leads',3,'leads',NULL,NULL,'Cuando el prospecto califica usa Convertir: el paso Convertir y crear cuenta crea su cuenta de cliente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('leads',4,'leads',NULL,NULL,'Descartar saca al lead del seguimiento y Reactivar lo devuelve. Eliminar lo borra de forma definitiva y pide confirmación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('leads',5,'leads',NULL,NULL,'Diferencia entre lead y cuenta: el lead es una persona interesada a la que se le da seguimiento hasta saber si hay negocio; la cuenta es la empresa (prospecto, cliente o partner) con la que se cotiza y factura. Un lead que califica se convierte y crea su cuenta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('leads',6,'leads',NULL,NULL,'También puedes pedirle a Aria que registre el lead: dile el nombre del contacto y su empresa, y agrega lo que tengas (RUC o DNI, cargo, teléfono, correo, LinkedIn, origen, industria, necesidad, presupuesto, urgencia, campaña). Aria avisa si ya existe un lead o una cuenta con ese documento o correo, muestra una tarjeta con los datos y nada se graba hasta pulsar Confirmar. Requiere permiso de crear en Leads.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('leads',7,'leads',NULL,NULL,'Para qué sirve: llevar el seguimiento de cada persona interesada desde que aparece hasta que se convierte en cliente o se descarta, para que ningún prospecto se quede sin atender. Se usa al recibir un contacto nuevo y cada vez que se habla con él.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('leads',8,'leads',NULL,NULL,'En la vista Kanban, Agregar lead crea uno en esa columna y al arrastrar una tarjeta a otra columna la pantalla pide Confirmar movimiento. Editar lead abre sus datos y Guardar cambios los conserva. En la conversión, Continuar con la conversión avanza al paso siguiente. Eliminar lead pide Eliminar definitivamente, y Reactivar lead devuelve al seguimiento uno descartado. Ver en módulo abre el registro relacionado en su propia pantalla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('leads',9,'leads',NULL,NULL,'Si no ves Nuevo lead o Eliminar lead, tu rol no tiene ese permiso en Leads. Si no aparece un lead que registraste, revisa los Filtros y el estado: los descartados y los convertidos salen de la vista de seguimiento. No deja guardar un lead de empresa sin el nombre de la empresa; solo una persona con DNI puede ir sin empresa.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('liquidacion_dmr','pantalla','liquidacion_flota','Liquidación & DMR','Partes diarios de los equipos alquilados y su liquidación mensual.','["operaciones-app/src/zahory-mock/pages/flota/LiquidacionFlotaPage.jsx#LiquidacionFlotaPage"]'::jsonb,'fa96e9f580')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidacion_dmr',1,'liquidacion_flota',NULL,NULL,'En Partes diarios registra cada día con Nuevo parte: horas operadas, horómetro y paradas, que se agregan con Agregar parada. Guardar parte lo conserva y Anular parte lo deja sin efecto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidacion_dmr',2,'liquidacion_flota',NULL,NULL,'En Liquidaciones usa Liquidar un mes y Crear liquidación; la liquidación queda en borrador. Recalcular la actualiza con los partes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidacion_dmr',3,'liquidacion_flota',NULL,NULL,'Enviar a revisión la manda a aprobación; quien revisa usa Aprobar o Devolver.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidacion_dmr',4,'liquidacion_flota',NULL,NULL,'Para qué sirve: aquí se controla cuánto operó cada equipo alquilado y se calcula lo que se le cobra al cliente en el mes. La fuente de las horas es el parte diario: uno por equipo y por día, con horómetro de inicio y de fin, horas programadas, paradas con su causa y el nombre de quien da el visto bueno por el cliente. Un día sin trabajo se registra como Sin operación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidacion_dmr',5,'liquidacion_flota',NULL,NULL,'El horómetro no puede retroceder respecto a los partes del día anterior o siguiente, y la pantalla avisa si las horas operadas superan las disponibles: revisa el horómetro o las paradas. Cada parte actualiza el horómetro actual del equipo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidacion_dmr',6,'liquidacion_flota',NULL,NULL,'La causa de cada parada define a quién se atribuye: al proveedor, al cliente o a nadie. Solo las paradas del proveedor bajan la disponibilidad. El DMR es la disponibilidad: horas programadas menos paradas del proveedor, dividido entre horas programadas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidacion_dmr',7,'liquidacion_flota',NULL,NULL,'Qué se cobra: las horas facturables son el mayor valor entre las horas operadas y el mínimo del contrato, prorrateado por los días del mes que el equipo estuvo en contrato. Lo operado se cobra con la tarifa vigente de cada día. Si el DMR quedó por debajo de la meta del contrato, se descuenta una penalidad proporcional a esa diferencia, por equipo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidacion_dmr',8,'liquidacion_flota',NULL,NULL,'La liquidación pasa por Borrador, En revisión y Aprobada. No se puede enviar a revisión si faltan partes de algún día ni antes de que termine el mes. Quien revisa usa Aprobar o Devolver con un motivo. Mientras la liquidación está en revisión o aprobada, los partes de ese mes quedan de solo lectura.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidacion_dmr',9,'liquidacion_flota',NULL,NULL,'Si no puedes editar un parte, casi siempre es porque el mes ya está liquidado. Si no puedes enviar la liquidación, revisa en Partes diarios qué días faltan. Aprobar y anular liquidaciones corresponde a los administradores de la empresa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidacion_dmr',10,'liquidacion_flota',NULL,NULL,'La pantalla se muestra mientras cargan los permisos; las acciones que requieren permiso permanecen deshabilitadas hasta que se comprueben. Si falla la carga de permisos, aparece un mensaje de error.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('liquidaciones_cese','pantalla','liquidaciones_cese','Liquidación por Cese','Cálculo y confirmación de la liquidación de un trabajador que cesa.','["src/pages_liquidaciones.jsx#LiquidacionesCese"]'::jsonb,'8409cfda1b')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidaciones_cese',1,'liquidaciones_cese',NULL,NULL,'Inicia con Nueva liquidación: elige al colaborador, el tipo de cese y la fecha de cese, que no puede ser anterior a su fecha de ingreso. El colaborador debe tener fecha de ingreso en su ficha.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidaciones_cese',2,'liquidaciones_cese',NULL,NULL,'Si el cese es por falta grave debes indicar el motivo específico. Recalcular vuelve a calcular los importes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidaciones_cese',3,'liquidaciones_cese',NULL,NULL,'Para confirmar marca la casilla de confirmación y usa Confirmar liquidación: se genera la cuenta por pagar y se bloquea el acceso del trabajador al sistema. Ver CxP generada abre esa cuenta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidaciones_cese',4,'liquidaciones_cese',NULL,NULL,'Anular deja sin efecto una liquidación; el motivo es obligatorio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidaciones_cese',5,'liquidaciones_cese',NULL,NULL,'Para qué sirve: calcular lo que la empresa debe pagar a un trabajador que se va (beneficios pendientes según el tipo de cese) y dejar la deuda registrada para pagarla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidaciones_cese',6,'liquidaciones_cese',NULL,NULL,'Nueva liquidación solo aparece si tu rol puede gestionar liquidaciones. Al confirmar, el monto queda como cuenta por pagar al trabajador.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('liquidaciones_cese',7,'liquidaciones_cese',NULL,NULL,'No deja calcular si el colaborador no tiene fecha de ingreso en su ficha: complétala primero en RRHH. No deja confirmar sin marcar la casilla de confirmación, ni anular sin escribir el motivo. Si el pago va a un beneficiario, pide su nombre y su DNI.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('lugares_transporte','pantalla','transporte_comercial','Lugares','Lugares de carga y de entrega del transporte.','["operaciones-app/src/zahory-mock/pages/transporte/LugaresPage.jsx#LugaresPage"]'::jsonb,'ca6f642574')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('lugares_transporte',1,'transporte_comercial',NULL,NULL,'Nuevo lugar registra un punto de carga o de entrega.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('lugares_transporte',2,'transporte_comercial',NULL,NULL,'Un lugar que ya no se usa se inactiva.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('lugares_transporte',3,'transporte_comercial',NULL,NULL,'Para qué sirve: los lugares son los puntos de carga y de entrega que usan las rutas y las paradas de los viajes: almacenes, plantas, obras, minas, puertos o locales de clientes. Un lugar puede ser general o pertenecer a un cliente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('lugares_transporte',4,'transporte_comercial',NULL,NULL,'La ubicación es obligatoria para guardar: se marca con un clic en el mapa o pegando un enlace de Google Maps. También se registran el contacto, el horario de atención, los requisitos de ingreso y las restricciones, que después ve quien programa y quien conduce.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('lugares_transporte',5,'transporte_comercial',NULL,NULL,'El lugar muestra en Usado en las rutas que lo emplean. No se puede repetir el nombre de un lugar. Un lugar que ya no se usa se inactiva.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('maestro_rutas','pantalla','transporte_comercial','Maestro de Rutas','Rutas de transporte.','["operaciones-app/src/zahory-mock/pages/transporte/MaestroRutasPage.jsx#MaestroRutasPage"]'::jsonb,'aaec02a4ba')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestro_rutas',1,'transporte_comercial',NULL,NULL,'Nueva ruta registra una ruta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestro_rutas',2,'transporte_comercial',NULL,NULL,'Editar cambia sus datos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestro_rutas',3,'transporte_comercial',NULL,NULL,'Para qué sirve: una ruta es un trayecto de un lugar a otro que la empresa atiende con frecuencia; sobre ella se definen las tarifas y se crean los viajes. Nueva ruta abre una sola vista con el mapa: eliges origen y destino del maestro de Lugares y el sistema propone el nombre, un código que empieza con R, la distancia y la duración.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestro_rutas',4,'transporte_comercial',NULL,NULL,'La distancia y la duración son estimadas a partir de la ubicación de los dos lugares y se pueden corregir a mano. En la misma vista puedes definir la tarifa base de la ruta y crear también la ruta de regreso: en ese caso el botón dice Guardar 2 rutas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestro_rutas',5,'transporte_comercial',NULL,NULL,'Si ya existe una ruta entre esos dos lugares, la pantalla lo avisa: Ver ruta abre la existente y Crear igual sigue adelante. Puedes cambiar el trayecto de una ruta que ya tiene viajes; los viajes anteriores conservan sus datos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestro_rutas',6,'transporte_comercial',NULL,NULL,'Si no aparece una ruta al crear una orden de viaje, revisa aquí que exista y esté activa. Si falta el origen o el destino entre las opciones, créalo primero en Lugares.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('maestros','pantalla','maestros','Maestros Base','Datos comunes de la empresa: centros de costo y de beneficio, materiales, familias y otros catálogos.','["src/pages_admin.jsx#Maestros"]'::jsonb,'50855bc116')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestros',1,'maestros',NULL,NULL,'Aquí se mantienen los centros de costo (Agregar CECO), los centros de beneficio (Agregar CEBE), los materiales y sus familias.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestros',2,'maestros',NULL,NULL,'Para cargas grandes usa Descargar plantilla e Importar Excel; la pantalla muestra una vista previa antes de confirmar la importación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestros',3,'maestros',NULL,NULL,'Un registro en uso no se borra: se desactiva. Si un CECO tiene órdenes de trabajo activas, la pantalla avisa que seguirán vinculadas aunque ya no aparezca para nuevas asignaciones.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestros',4,'maestros',NULL,NULL,'Fusionar une dos registros duplicados en uno solo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestros',5,'maestros',NULL,NULL,'Para qué sirve: mantener los catálogos que usa todo el sistema, para que cada área elija de la misma lista y los reportes cuadren. Lo que no existe aquí no se puede elegir en un documento. Se configura al implantar y se actualiza cuando el negocio cambia.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestros',6,'maestros',NULL,NULL,'Los maestros son: Industrias; Sedes y ubicaciones GPS; Almacenes; Centros de Costo y Beneficio; Unidades Organizacionales; Cargos de la empresa; Tipos de Documento; Requisitos por Cargo; Especialidades técnicas; Niveles Jerárquicos; Materiales e insumos; Familias de servicio; Monedas, impuestos y unidades; Catálogo de Actividades Operativas; Recetas de actividad; Catálogo de componentes; Trabajos; Catálogo Servicios; Fabricantes y Tipos de Contrato. Gestionar abre cada uno. Solo ves los que tu rol tiene permitidos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestros',7,'maestros',NULL,NULL,'En cualquier maestro: Crear agrega un registro y Guardar cambios lo conserva; Cancelar edición descarta el cambio. Desactivar o Inactivar lo retira de las listas sin borrarlo y Activar lo devuelve. Eliminar seleccionados borra los marcados que no están en uso. Exportar Excel descarga la lista y Limpiar filtros quita los filtros. Para unir duplicados, «Fusionar con» elige el registro que queda y Confirmar fusión pasa a él todo lo vinculado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestros',8,'maestros',NULL,NULL,'Carga masiva: Descargar plantilla baja el formato y Subir plantilla lo carga. Tras la vista previa, Confirmar importación continúa y el botón final cambia según el maestro: Importar CECOs, Importar CEBEs, Importar registros, Importar filas válidas, Importar actividades válidas o Importar tipos. Importar otro archivo o Subir otro archivo reemplazan el Excel y Cancelar carga lo descarta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestros',9,'maestros',NULL,NULL,'Materiales: Actualizar material guarda la edición. Un material puede tener números de parte alternativos: Alternativo agrega uno y Quitar número alternativo lo retira. El contador «sub-familias» muestra cuántas tiene cada familia.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestros',10,'maestros',NULL,NULL,'Tipos de Documento y Requisitos por Cargo: Nuevo tipo de documento y Guardar Tipo definen un documento del personal, con su categoría y si vence. Importar Plantilla Base trae una lista sugerida. Los enlaces Tipos de Documento y Requisitos por Cargo pasan de un panel al otro; en los requisitos se marca qué documentos necesita cada cargo, y los marcados «req.» son obligatorios. Ir a Tipos de Documento vuelve al primer panel.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestros',11,'maestros',NULL,NULL,'Trabajos, actividades y servicios: Editar trabajo y Eliminar trabajo mantienen el catálogo de Trabajos. En una actividad operativa, + Planificación, + Recursos y + Seguridad (HSE) despliegan sus datos opcionales. Nuevo servicio agrega un servicio al catálogo, Recurrente mensual lo marca como de cobro mensual y Crear y seleccionar crea una familia desde el mismo formulario.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestros',12,'maestros',NULL,NULL,'Algunos datos no se mantienen aquí y la pantalla lleva a su lugar: Ir a Cuentas, Ir a Proveedores, Ir a RRHH Administrativo, Ir a RRHH Operativo e Ir a ficha.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('maestros',13,'maestros',NULL,NULL,'Si no aparece un maestro, tu rol no tiene acceso a Maestros o a ese catálogo. No deja eliminar un registro en uso: desactívalo. Si en la carga masiva hay filas rechazadas, la vista previa indica el motivo de cada una; corrige el Excel y vuelve a subirlo. Si un dato no aparece al registrar un documento, revisa aquí que exista y esté activo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('marketing','pantalla','marketing','Marketing Automation','Campañas de marketing, su audiencia y su activación.','["src/pages_core.jsx#Marketing"]'::jsonb,'7bd4a6c570')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('marketing',1,'marketing',NULL,NULL,'Crea una campaña con Nueva campaña y Crear campaña. Editar cambia sus datos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('marketing',2,'marketing',NULL,NULL,'Audiencia muestra a quién va dirigida.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('marketing',3,'marketing',NULL,NULL,'Activar la pone en marcha, Pausar la detiene y Reactivar la retoma.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('marketing',4,'marketing',NULL,NULL,'Eliminar campana la borra y no se puede deshacer.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('marketing',5,'marketing',NULL,NULL,'Para qué sirve: organizar las campañas con las que se consiguen prospectos y medir cuántos leads trae cada una. Los leads cuyo origen coincide con el código de la campaña se le atribuyen solos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('marketing',6,'marketing',NULL,NULL,'Si no ves leads en una campaña, revisa que el origen del lead sea el mismo código de la campaña. No aparece Activar en una campaña que ya está activa: ahí el botón es Pausar.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('mi_portal','pantalla','mi_portal','Mi portal','Espacio personal del trabajador: boletas, documentos, contrato y solicitudes.','["src/pages_mi_portal.jsx#MiPortal"]'::jsonb,'8a66482254')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('mi_portal',1,'mi_portal',NULL,NULL,'Para abrir tus boletas primero debes registrar el consentimiento de entrega electrónica; la pantalla te lleva a Firma y consentimiento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('mi_portal',2,'mi_portal',NULL,NULL,'Abrir muestra una boleta y Me doy por enterado registra tu acuse.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('mi_portal',3,'mi_portal',NULL,NULL,'Pedir vacaciones, Pedir permiso, Solicitar HE y Solicitar constancia envían tus solicitudes; las horas extra exigen completar todos los campos obligatorios.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('mi_portal',4,'mi_portal',NULL,NULL,'Subir firmado carga tu contrato o documento firmado, que queda en revisión por RRHH. El archivo no puede estar vacío ni pasar de 20 MB.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('mi_portal',5,'mi_portal',NULL,NULL,'Para pedir un cambio en tus datos, ingresa el nuevo valor propuesto y usa Enviar a RRHH.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('mi_portal',6,'mi_portal',NULL,NULL,'Para qué sirve: es el espacio personal de cada trabajador. Aquí ve sus boletas, firma sus documentos, pide vacaciones, permisos, horas extra y constancias, y consulta sus resultados, sin pasar por RRHH.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('mi_portal',7,'mi_portal',NULL,NULL,'Nueva solicitud abre el formulario y Enviar solicitud lo manda a aprobación. Ver documento abre un documento tuyo; Subir nueva versión reemplaza uno ya cargado y Confirmar subida lo envía. Revisar y firmar abre un documento pendiente de firma: Enviar OTP manda un código a tu correo y Validar OTP lo comprueba. Ir a Firma y consentimiento lleva a registrar tu consentimiento. Reautenticar y abrir pide tu contraseña otra vez antes de mostrar una boleta. Responder contesta una observación de RRHH y Ver resultados muestra tu evaluación. La firma electrónica desde aquí aparece como próximamente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('mi_portal',8,'mi_portal',NULL,NULL,'No deja abrir boletas hasta registrar el consentimiento de entrega electrónica. No deja subir un archivo vacío o de más de 20 MB. Si no aparece un tipo de documento para subir, RRHH debe completar la configuración de tipos de documento.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('minas_proyectos','pantalla','inventario','Minas y proyectos','Minas, sus proyectos y sus almacenes periféricos.','["operaciones-app/src/zahory-mock/pages/MinasProyectosPage.jsx#MinasProyectosPage"]'::jsonb,'67b307ee29')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('minas_proyectos',1,'inventario',NULL,NULL,'Nueva mina registra una mina y Editar mina cambia sus datos; ambos dependen de lo que tu rol puede crear o editar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('minas_proyectos',2,'inventario',NULL,NULL,'Nuevo proyecto crea un proyecto en la mina y Asignar proyecto existente vincula uno ya creado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('minas_proyectos',3,'inventario',NULL,NULL,'Agregar almacén periférico crea el almacén de la mina.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('minas_proyectos',4,'inventario',NULL,NULL,'Devolver a central regresa el material del almacén periférico al almacén central.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('minas_proyectos',5,'inventario',NULL,NULL,'Para qué sirve: organizar el trabajo en campo. Cada mina o unidad tiene sus proyectos y su almacén periférico, que guarda en sitio el material enviado desde el almacén central.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('minas_proyectos',6,'inventario',NULL,NULL,'Guardar mina, Guardar proyecto y Guardar almacén conservan cada registro. La tarjeta de la mina muestra cuántos proyectos tiene y si está Activa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('minas_proyectos',7,'inventario',NULL,NULL,'Nueva mina y Nuevo proyecto requieren el permiso de crear; Editar mina y Devolver a central, el de editar. Si no ves esos botones, tu rol no lo tiene. Si no aparece un proyecto para asignarlo, créalo con Nuevo proyecto.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('mis_ots_dia','pantalla','ot','Mis OTs del día','Muestra al técnico las OT asignadas para hoy y le permite registrar su parte diario.','["operaciones-app/src/zahory-mock/pages/MisOTsPage.jsx#MisOTsPage"]'::jsonb,'aa0aa52182')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('mis_ots_dia',1,'ot',NULL,NULL,'Verás las OT que tienes asignadas para el día con su estado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('mis_ots_dia',2,'ot',NULL,NULL,'Registrar parte abre el parte diario de esa OT. Registrar parte sin OT sirve para trabajo que todavía no tiene orden.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('mis_ots_dia',3,'ot',NULL,NULL,'Para qué sirve: que el técnico vea en su celular o tablet qué órdenes tiene hoy y registre su parte sin buscar en la bandeja.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('mis_ots_dia',4,'ot',NULL,NULL,'El parte registrado aquí queda en revisión hasta que el jefe de taller lo apruebe; recién entonces sus horas cuentan en el avance y el costo de la OT.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('mis_ots_dia',5,'ot',NULL,NULL,'Si no aparece una OT, no está asignada a ti para hoy: pide al jefe de taller que te la asigne en el Planner. Si no puedes registrar el parte, la OT debe estar programada o en ejecución y tener al menos una tarea.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('monitor_viajes','pantalla','transporte_comercial','Monitor de viajes','Seguimiento de los viajes de transporte comercial: estado, filtros, asignación de unidad y conductor, y creación de órdenes de viaje.','["operaciones-app/src/zahory-mock/pages/transporte/MonitorViajesPage.jsx#MonitorViajesPage"]'::jsonb,'89fb9d5ef7')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('monitor_viajes',1,'transporte_comercial',NULL,NULL,'El tablero agrupa los viajes por estado (programado, despachado y siguientes) y marca los atrasados, los que salen hoy, los que no tienen unidad asignada y los que tienen incidentes. Usa los filtros y Limpiar filtros para volver a verlos todos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('monitor_viajes',2,'transporte_comercial',NULL,NULL,'Nueva orden de viaje abre el registro de un viaje nuevo con su ruta y cliente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('monitor_viajes',3,'transporte_comercial',NULL,NULL,'Cuando hay viajes atrasados o que salen hoy sin unidad, aparece un aviso con Asignar y despachar, que abre el viaje para asignar unidad y conductor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('monitor_viajes',4,'transporte_comercial',NULL,NULL,'Abre un viaje para ver su detalle y su hoja de ruta. Exportar descarga la lista.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('monitor_viajes',5,'transporte_comercial',NULL,NULL,'Para qué sirve: seguir en vivo todos los viajes de transporte comercial, desde que se programan hasta que se entregan, y detectar a tiempo los que van atrasados o no tienen unidad.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('monitor_viajes',6,'transporte_comercial',NULL,NULL,'Si no aparece un viaje, usa Limpiar filtros y revisa el estado. Si no deja despachar, al viaje le falta unidad o conductor: usa Asignar y despachar.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('movil_asistencia','pantalla','campo','Móvil — Asistencia','Marcación de entrada, refrigerio y salida desde el celular.','["src/pages_mobile.jsx#AsistenciaMobileView"]'::jsonb,'823e538216')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_asistencia',1,'campo',NULL,NULL,'Entrada y Salida registran tu marcación con la ubicación del celular; debes dar permiso de ubicación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_asistencia',2,'campo',NULL,NULL,'Sin señal, la marcación se guarda en el celular y se sincroniza sola al recuperar la conexión.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_asistencia',3,'campo',NULL,NULL,'Si marcas la salida con un refrigerio sin cerrar, la pantalla pide confirmación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_asistencia',4,'campo',NULL,NULL,'Si estás fuera de la geocerca puedes enviar un reporte con Enviar reporte, que queda para revisión.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_asistencia',5,'campo',NULL,NULL,'Para qué sirve: que cada trabajador marque su asistencia desde su celular en el lugar de trabajo, con la ubicación como prueba, sin reloj físico. Las marcas alimentan el control de asistencia y la planilla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_asistencia',6,'campo',NULL,NULL,'La primera vez la pantalla pide tu consentimiento para usar la ubicación: Acepto lo registra. Nuevo registro inicia una marcación. Si hay marcas guardadas sin enviar, Reintentar ahora las sincroniza. Cerrar reporte cierra el aviso de fuera de geocerca.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_asistencia',7,'campo',NULL,NULL,'Si no puedes marcar, revisa que el celular tenga la ubicación activada y el permiso concedido al navegador; algunos equipos no la soportan. Si dice que no tienes un turno asignado, pide a RRHH que te lo asigne. Una marca hecha sin señal no se pierde: se envía sola al volver la conexión.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('movil_compras','pantalla','campo','Móvil — Compras','Registro de un gasto con la foto del comprobante desde el celular.','["src/pages_mobile.jsx#ComprasView"]'::jsonb,'51d45cfa58')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_compras',1,'campo',NULL,NULL,'Adjuntar foto del comprobante o Tomar captura la factura; también puedes usar Ingresar datos manualmente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_compras',2,'campo',NULL,NULL,'El total de las líneas debe coincidir con el de la factura; Recalcular lo actualiza.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_compras',3,'campo',NULL,NULL,'Si la factura tiene más de 30 días, la pantalla pide confirmar antes de continuar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_compras',4,'campo',NULL,NULL,'Para qué sirve: que un comprador de campo registre una compra en el momento, con la foto del comprobante, para que llegue a Administración sin esperar a que vuelva a la oficina. Lo registrado queda pendiente de revisión en Compras y Gastos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_compras',5,'campo',NULL,NULL,'Nueva captura vuelve a tomar la foto. Recargar actualiza la lista de materiales que tienes asignados para comprar, y Liberar devuelve uno a la Bandeja de Sourcing si no vas a comprarlo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_compras',6,'campo',NULL,NULL,'No deja guardar si el total de las líneas no coincide con el de la factura: corrige las líneas o usa Recalcular. Si la foto no se sube, revisa la conexión y vuelve a intentarlo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('movil_gerencia','pantalla','campo','Móvil — Gerencia','Aprobaciones pendientes desde el celular.','["src/pages_mobile.jsx#GerenciaView"]'::jsonb,'a2308d7303')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_gerencia',1,'campo',NULL,NULL,'Aprobar pendientes muestra lo que espera tu decisión.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_gerencia',2,'campo',NULL,NULL,'Aprobar o Rechazar resuelve cada pendiente y pide confirmación; el comentario es obligatorio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_gerencia',3,'campo',NULL,NULL,'Para qué sirve: que gerencia apruebe o rechace desde el celular lo que espera su decisión, para no frenar la operación cuando no está en la oficina.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_gerencia',4,'campo',NULL,NULL,'Cada decisión se confirma en una segunda pantalla con Confirmar aprobacion o Confirmar rechazo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_gerencia',5,'campo',NULL,NULL,'No deja confirmar sin escribir el comentario. Si no aparece un pendiente, no te corresponde aprobarlo según tu rol o ya fue resuelto.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('movil_logistica','pantalla','campo','Móvil — Logística','Rutas y viajes del conductor desde el celular.','["src/pages_mobile.jsx#LogisticaView","src/components/ConductorApp.jsx#ConductorApp"]'::jsonb,'4d6a4cf5e2 a0da71777e')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_logistica',1,'campo',NULL,NULL,'Para qué sirve: el conductor sigue sus viajes comerciales y rutas de logística desde el celular, registra su avance y entrega evidencia para la operación y liquidación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_logistica',2,'campo',NULL,NULL,'Abrir viaje abre el servicio comercial. Inspección antes de salir permite marcar Bien o Falla, describir cada falla y registrar km de salida; la foto del tablero es opcional. Guardar inspección guarda el control. Si hay fallas críticas, espera la autorización del despachador; el viaje programado también debe ser despachado antes de salir.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_logistica',3,'campo',NULL,NULL,'Salí · registrar hora y GPS inicia el viaje comercial. Registra en orden la llegada a carga, fin de carga, llegada a destino y fin de descarga con los botones de hitos; la pantalla calcula las esperas entre llegada y fin de carga y entre llegada y fin de descarga. Continuar ruta reanuda un viaje con incidente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_logistica',4,'campo',NULL,NULL,'Registrar conformidad del cliente abre la constancia: nombre, DNI, bultos recibidos, estado de carga, firma y foto de la guía firmada son obligatorios; también pide km de llegada en destino y observaciones si hay novedad. Limpiar borra la firma; Finalizar entrega guarda la constancia, hora y GPS disponible. La foto de carga es opcional.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_logistica',5,'campo',NULL,NULL,'En logística propia, Iniciar ruta inicia una ruta programada o despachada. Llegué registra la llegada a una parada pendiente y Cómo llegar abre el mapa. Gestionar parada abre la constancia: nombre y firma son obligatorios, la foto de guía es opcional. Finalizar parada la completa; Omitir parada y Confirmar: omitir parada exigen un motivo en Observaciones y devuelven el pedido a Por enviar a ruta. Terminar ruta aparece cuando no quedan paradas pendientes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_logistica',6,'campo',NULL,NULL,'Gasto abre el registro comercial: elige tipo, indica monto positivo y toma Foto del comprobante; Guardar gasto lo envía a la liquidación. Cada gasto muestra Por revisar, Aprobado u Observado y el motivo si existe; el total excluye los observados. Hoja y Ver hoja de ruta (PDF) descargan la hoja de ruta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_logistica',7,'campo',NULL,NULL,'Incidente pide tipo, severidad y descripción; la foto es opcional. Guardar incidente registra el incidente y en un viaje comercial lo deja con incidente para el Monitor. En logística, Lectura permite guardar odómetro o horómetro con valor y Foto del tablero obligatoria; Guardar lectura registra el dato. Parada permite agregar una parada libre.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_logistica',8,'campo',NULL,NULL,'El acceso corresponde al perfil móvil Logística; los viajes se consultan para la empresa y el usuario autenticado. Si el usuario no está vinculado a una ficha de conductor, la pantalla avisa que muestra los viajes de la empresa y pide vincularlo en Operaciones › Flota.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_logistica',9,'campo',NULL,NULL,'Si no ves tu viaje, revisa la asignación, fecha y estado en la Hoja de Ruta; Reintentar vuelve a consultar si hubo error de carga. No deja salir con una inspección crítica sin autorización ni antes del despacho. No deja guardar un gasto sin monto positivo y foto, ni finalizar una constancia si faltan sus datos obligatorios.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('movil_mi_portal','pantalla','campo','Móvil — Mi portal','Espacio personal del trabajador en el celular: documentos, contrato y solicitudes.','["src/pages_mobile.jsx#MiEspacioMobileView"]'::jsonb,'1f9e81e467')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_mi_portal',1,'campo',NULL,NULL,'Marcar entrada/salida lleva a la asistencia.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_mi_portal',2,'campo',NULL,NULL,'Solicitudes, Nueva licencia, Solicitar HE y Solicitar constancia envían tus pedidos; debes completar los campos obligatorios.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_mi_portal',3,'campo',NULL,NULL,'Subir contrato firmado carga tu contrato, que queda en revisión por RRHH. El archivo no puede estar vacío ni pasar de 20 MB.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_mi_portal',4,'campo',NULL,NULL,'Si no aparece tu ficha de personal, contacta a RRHH.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_mi_portal',5,'campo',NULL,NULL,'Para qué sirve: que el trabajador gestione lo suyo desde el celular: ver sus documentos, firmar y subir su contrato y enviar sus solicitudes, sin ir a RRHH.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_mi_portal',6,'campo',NULL,NULL,'Revisar abre un documento marcado como Pendiente; Firma electrónica lo firma desde el celular y Confirmar y enviar lo entrega. Confirmar subida envía el archivo elegido. Responder contesta una observación de RRHH.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_mi_portal',7,'campo',NULL,NULL,'No deja subir un archivo vacío ni de más de 20 MB. Si no aparece tu ficha de personal, contacta a RRHH.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('movil_supervisor','pantalla','campo','Móvil — Supervisor','Revisión de partes y solicitudes desde el celular.','["src/pages_mobile.jsx#SupervisorView"]'::jsonb,'a634a954c2')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_supervisor',1,'campo',NULL,NULL,'Aprobar, Observar o Rechazar resuelve cada pendiente y pide confirmación; el comentario es obligatorio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_supervisor',2,'campo',NULL,NULL,'Solicitudes RRHH muestra las solicitudes del personal por atender.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_supervisor',3,'campo',NULL,NULL,'Para qué sirve: que el supervisor revise en campo los partes de su equipo y atienda sus solicitudes desde el celular, para que el avance y los costos de las órdenes no esperen.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_supervisor',4,'campo',NULL,NULL,'Rechazar se completa con Confirmar rechazo, después de escribir el comentario.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_supervisor',5,'campo',NULL,NULL,'No deja resolver un pendiente sin comentario. Si no aparece un parte, el técnico aún no lo envió a revisión o no pertenece a tu equipo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('movil_tareo','pantalla','campo','Móvil — Tareo','Registro de horas del día desde el celular.','["src/pages_mobile.jsx#AdministrativoView"]'::jsonb,'098b9894da')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_tareo',1,'campo',NULL,NULL,'Registrar anota tus horas: las horas y la descripción son obligatorias.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_tareo',2,'campo',NULL,NULL,'Enviar registro del día manda tu jornada y pide confirmación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_tareo',3,'campo',NULL,NULL,'Para qué sirve: que el personal registre desde el celular las horas que trabajó en el día y en qué, cuando no marca con reloj de asistencia.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_tareo',4,'campo',NULL,NULL,'Al enviar el día, la pantalla pide confirmar con «Sí, enviar registro».');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_tareo',5,'campo',NULL,NULL,'No deja registrar sin horas y sin descripción. Si no puedes enviar el día, primero registra al menos una línea de horas.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('movil_tecnico','pantalla','campo','Móvil — Técnico','Trabajo del técnico en campo desde el celular.','["src/pages_mobile.jsx#TecnicoView"]'::jsonb,'3940dcb878')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_tecnico',1,'campo',NULL,NULL,'Iniciar esta tarea comienza una tarea y Continuar trabajando en esta tarea la retoma.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_tecnico',2,'campo',NULL,NULL,'Escanear Material registra el material usado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_tecnico',3,'campo',NULL,NULL,'Parte registra el parte del día y Enviar al supervisor lo manda a revisión.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_tecnico',4,'campo',NULL,NULL,'Firmar y Completar cierra el trabajo con firma.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_tecnico',5,'campo',NULL,NULL,'SSOMA abre la sección de seguridad y SOS sirve para pedir ayuda.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_tecnico',6,'campo',NULL,NULL,'Para qué sirve: que el técnico trabaje con el celular en la mano: ver sus tareas, marcar en cuál está, registrar el material que usa y enviar su parte, sin papeles.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_tecnico',7,'campo',NULL,NULL,'El parte enviado queda en revisión del supervisor; sus horas cuentan en la orden cuando lo aprueba.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_tecnico',8,'campo',NULL,NULL,'Si no aparece una tarea, la orden no está asignada a ti o no está programada. Si no deja escanear, revisa el permiso de cámara del navegador.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('movil_vendedor','pantalla','campo','Móvil — Vendedor','Leads, oportunidades, agenda y comisión del vendedor desde el celular.','["src/pages_mobile.jsx#VendedorView"]'::jsonb,'30d5a9d29f')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_vendedor',1,'campo',NULL,NULL,'Agregar lead registra un prospecto a mano; Crear lead con foto de tarjeta extrae los datos de la tarjeta automáticamente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_vendedor',2,'campo',NULL,NULL,'Convertir pasa un lead a oportunidad y Descartar lo saca del seguimiento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_vendedor',3,'campo',NULL,NULL,'Registrar Actividad anota un contacto y Planificar en agenda agenda la próxima reunión o visita. Llamar marca al teléfono del contacto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_vendedor',4,'campo',NULL,NULL,'Una oportunidad se marca como Perdida con Confirmar perdida.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_vendedor',5,'campo',NULL,NULL,'En Comisión, Proponer acuerdo especial envía tu propuesta con Enviar a aprobación; Retirar solicitud la retira.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_vendedor',6,'campo',NULL,NULL,'Sincronizar ahora actualiza los datos cuando hay conexión.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_vendedor',7,'campo',NULL,NULL,'Para qué sirve: que el vendedor lleve su trabajo de campo en el celular: registrar prospectos al instante, anotar cada contacto, agendar la siguiente visita y ver su comisión.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_vendedor',8,'campo',NULL,NULL,'Abajo están las pestañas de leads, Opps (oportunidades), Acts (actividades) y agenda. Guardar Lead registra el prospecto y Guardar borrador lo deja sin terminar. Guardar en Agenda agenda un evento y Realizado lo marca como hecho, con la opción de registrarlo como actividad. El Centro de notificaciones muestra los avisos sin leer; Activar enciende las notificaciones del celular, Probar envía una de prueba y Silenciar las apaga. Info muestra los datos de la sesión, Salir campo vuelve a la aplicación completa y Cerrar sesion sale del sistema.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('movil_vendedor',9,'campo',NULL,NULL,'Si no puedes llamar, el lead o su contacto principal no tiene un teléfono válido. Si dice «Sin conexion para sincronizar», los datos se envían al recuperar la señal con Sincronizar ahora. Si el navegador no soporta notificaciones, no aparecerá la opción de activarlas.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('nomina','pantalla','nomina','Nomina','Cálculo, revisión y cierre de la planilla de cada período: cómo procesar la planilla del mes o de la quincena.','["src/pages_ops.jsx#Nomina"]'::jsonb,'21d2972451')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nomina',1,'nomina',NULL,NULL,'Crea el período con Nuevo período y calcula la planilla con Procesar. Si pagas por quincenas, debes procesar la primera quincena antes de la segunda.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nomina',2,'nomina',NULL,NULL,'Nuevo ingreso y Nuevo descuento registran conceptos extraordinarios con su descripción y su monto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nomina',3,'nomina',NULL,NULL,'Boleta abre la boleta de un trabajador y Descargar boleta PDF la descarga. Descargar Excel PLAME genera el archivo del período.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nomina',4,'nomina',NULL,NULL,'Cierra el período con Confirmar cierre: debe estar procesado y, cuando corresponde gratificación, antes hay que confirmar la gratificación real. Al cerrar se generan los egresos de la planilla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nomina',5,'nomina',NULL,NULL,'Para qué sirve: calcular la planilla de cada período, con sueldos, horas extra, descuentos y aportes, emitir las boletas y dejar registrado el gasto. Al cerrar el período se crea el egreso de planilla y el de cargas sociales en Compras y Gastos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nomina',6,'nomina',NULL,NULL,'Crear período guarda el período nuevo. Registrar guarda un ingreso o un descuento extraordinario. Boletas lista las boletas del período. En horas extra, cada registro se resuelve con Pagar, que lo lleva a la planilla, o Compensar, que lo cambia por un día libre. En la pestaña de gratificación, Autorizar sobretasa aplica un factor distinto a un trabajador y Confirmar gratificación real, con Confirmar pago real, aplica el pago real a la nómina procesada y recalcula la retención de quinta categoría. Si la pantalla advierte algo antes de calcular, Procesar de todos modos continúa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nomina',7,'nomina',NULL,NULL,'No deja cerrar un período que no está procesado, ni uno con gratificación sin confirmar. No deja procesar la segunda quincena sin haber procesado la primera. Un período cerrado no se vuelve a cerrar ni genera egresos de nuevo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('notificaciones_config','pantalla','parametros','Notificaciones','Avisos automáticos de la empresa (contratos y documentos por vencer, tardanzas, OT y partes): a quién llegan, por campana, correo o WhatsApp, y su historial de envíos.','["src/pages_notificaciones_config.jsx#NotificacionesConfig"]'::jsonb,'37041730c7')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('notificaciones_config',1,'parametros',NULL,NULL,'Debes tener seleccionada una empresa para configurar sus notificaciones.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('notificaciones_config',2,'parametros',NULL,NULL,'En Eventos activas cada aviso y defines a quién llega; Agregar aviso suma uno nuevo y Guardar cambios conserva la configuración.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('notificaciones_config',3,'parametros',NULL,NULL,'Probar ahora ejecuta el aviso en el momento para comprobar que funciona.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('notificaciones_config',4,'parametros',NULL,NULL,'Historial de envíos muestra lo que ya se envió.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('notificaciones_config',5,'parametros',NULL,NULL,'Avisos disponibles: contratos por vencer (por defecto a 30, 15 y 7 días; hasta 5 avisos entre 1 y 180 días), contratos vencidos sin renovar, documentos por vencer, resumen diario de tardanzas (más de 10 minutos por defecto), OT creadas en el día y partes no llenados. Todos nacen apagados: cada empresa activa los que quiere.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('notificaciones_config',6,'parametros',NULL,NULL,'Cada aviso define a quién llega (RRHH o administración, jefe directo, colaborador, Operaciones) y por qué canal: campana del sistema, correo o WhatsApp. Se pueden sumar hasta 10 correos y 10 teléfonos adicionales por aviso, y elegir qué roles cuentan como RRHH u Operaciones.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('notificaciones_config',7,'parametros',NULL,NULL,'La campana avisa al instante. El correo llega como una lista diaria por destinatario, alrededor de las 7:20 a. m. El resumen de tardanzas admite una hora de envío propia para recibir las del mismo día.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('notificaciones_config',8,'parametros',NULL,NULL,'Si alguien no recibe un aviso, revisa: que el aviso esté activo, que su rol esté entre los destinatarios, que tenga correo real en su usuario (o teléfono para WhatsApp) y, para el jefe directo, que el organigrama indique a quién reporta. Historial de envíos muestra qué salió, a quién y si falló.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('notificaciones_config',9,'parametros',NULL,NULL,'Un contrato con renovación aprobada que empalma no genera aviso de vencimiento, y las adendas tampoco.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('notificaciones_config',10,'parametros',NULL,NULL,'Para qué sirve: decidir qué avisos automáticos envía el sistema, a quién y por qué medio, para que la gente se entere a tiempo de lo que vence o de lo que no se hizo, sin que alguien tenga que revisarlo a mano.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('notificaciones_config',11,'parametros',NULL,NULL,'No deja configurar sin elegir una empresa. Si no llega un aviso, revisa el Historial de envíos: ahí se ve si salió, a quién y si falló. Si no ves esta pantalla, tu rol no es administrador.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('nueva_of','pantalla','of','Nueva OF','Creación de una orden de fabricación a partir de la orden de servicio del cliente.','["operaciones-app/src/zahory-mock/pages/of/CrearOFPage.jsx#CrearOFPage"]'::jsonb,'4ff52824a1')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_of',1,'of',NULL,NULL,'La OF se crea a partir de la OS del cliente; Cambiar permite elegir otra.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_of',2,'of',NULL,NULL,'La pantalla indica si la OS tiene Hoja de Costeo, que sirve de base a la orden.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_of',3,'of',NULL,NULL,'Crear OF registra la orden. Si la OS ya tiene una, el botón dice Crear OF adicional.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_of',4,'of',NULL,NULL,'Para qué sirve: abrir la orden de fabricación de un pedido del cliente. La OF toma de la Hoja de Costeo de la OS las tareas y los materiales, así el taller fabrica lo mismo que se cotizó.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_of',5,'of',NULL,NULL,'El enlace Órdenes de Fabricación, arriba, vuelve a la bandeja sin crear nada.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_of',6,'of',NULL,NULL,'Si no aparece la OS para elegirla, no es de tipo fabricación o mixta: el tipo se define en la Hoja de Costeo. Si el botón dice Crear OF adicional, la OS ya tiene una OF y la nueva nace vacía.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('nueva_ot','pantalla','ot','Nueva OT','Asistente de cinco pasos para crear una orden de trabajo: contexto, lugar, matriz DBS, responsable y revisión.','["operaciones-app/src/zahory-mock/pages/CrearOTPage.jsx#CrearOTPage"]'::jsonb,'972837319f')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',1,'ot',NULL,NULL,'Paso 1, Contexto: elige la línea de negocio y el objeto de costo raíz: un contrato de alquiler activo, una OS de cliente o un equipo interno de la plataforma.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',2,'ot',NULL,NULL,'Paso 2, Lugar: indica dónde se ejecuta el trabajo. El horómetro actual del equipo es obligatorio en OTs de campo, bajo contrato o con equipo asociado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',3,'ot',NULL,NULL,'Paso 3, Matriz DBS: clasifica el cargo financiero (facturable al cliente, absorbido, recuperable del fabricante o retrabajo propio, que exige motivo) y arma segmentos con operaciones, mano de obra, repuestos y terceros. La pantalla suma los costos estimados.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',4,'ot',NULL,NULL,'Paso 4, Responsable: asigna el técnico responsable, las fechas y el centro de costo; si la OS o el equipo no lo definen, debes elegirlo a mano.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',5,'ot',NULL,NULL,'Paso 5, Revisión: revisa el resumen, agrega la descripción técnica y usa Crear OT. Desde el asistente también puedes vincular hallazgos y backlog del diagnóstico.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',6,'ot',NULL,NULL,'Toda OT declara de dónde sale su costo: un contrato de alquiler, una OS de cliente o un equipo propio. Eso define a qué centro de costo se carga y si el trabajo se factura. Sin ese dato el asistente no deja avanzar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',7,'ot',NULL,NULL,'Si la OT viene de una OS de cliente, hereda cliente y centro de costo. Si viene de un contrato de alquiler, queda ligada al contrato y su costo cuenta en la rentabilidad del alquiler.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',8,'ot',NULL,NULL,'Retrabajo propio es un trabajo que se repite por error interno: no se cobra y exige motivo. Recuperable del fabricante es garantía del proveedor. Absorbido es un costo que la empresa asume sin cobrar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',9,'ot',NULL,NULL,'Al programar la OT, los repuestos de sus segmentos se reservan en el almacén: bajan del disponible pero no salen hasta el despacho. Si falta stock se pide por SOLPE.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',10,'ot',NULL,NULL,'Para qué sirve: abrir una orden de trabajo con todo lo necesario para ejecutarla y costearla: para quién es, dónde se hace, qué trabajos incluye, qué repuestos y terceros necesita y quién responde por ella.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',11,'ot',NULL,NULL,'En el primer paso, Limpiar cliente quita el cliente elegido, e Ir a Recepción de Activos lleva a registrar el equipo si aún no ingresó. En la matriz de trabajo, Agregar Segmento crea un bloque y Agregar Operación una operación dentro de él; Eliminar segmento y Eliminar operación los quitan. Agregar cargo suma mano de obra, Agregar repuesto un repuesto y Agregar tercero un servicio de terceros. Cerrar panel de hallazgos y backlog oculta el panel lateral con lo pendiente del equipo. Al terminar, Ver OTs vuelve a la bandeja.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('nueva_ot',12,'ot',NULL,NULL,'En las OT de tipo Correctivo o Preventivo (PM) el equipo es obligatorio, porque con él se calculan las fallas, el MTBF y el programa de mantenimiento en Confiabilidad. Si la OT se abre desde Backlog operativo (Crear OT) o desde Programación PM (Generar OT), el formulario llega con el equipo, el tipo y la descripción, muestra el origen y, al guardar, deja vinculado el hallazgo o el plan PM.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('cs_onboarding','pantalla','cs_onboarding','Onboarding','Seguimiento de la puesta en marcha de los clientes nuevos.','["src/pages_cs.jsx#CSOnboarding"]'::jsonb,'6a67ec3d29')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_onboarding',1,'cs_onboarding',NULL,NULL,'Inicia la puesta en marcha de un cliente con Nuevo onboarding.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_onboarding',2,'cs_onboarding',NULL,NULL,'Ver detalle muestra su avance.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_onboarding',3,'cs_onboarding',NULL,NULL,'Para qué sirve: acompañar a un cliente nuevo en sus primeras semanas, con los pasos de su puesta en marcha y su avance, para que empiece bien y no se enfríe la relación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_onboarding',4,'cs_onboarding',NULL,NULL,'Cada onboarding pertenece a una cuenta y muestra su avance en porcentaje.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('cs_onboarding',5,'cs_onboarding',NULL,NULL,'Si no aparece un cliente para iniciar su onboarding, primero debe existir como cuenta en Cuentas y Contactos.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('orden_viaje','pantalla','transporte_comercial','Nueva orden de viaje','Registro de un viaje de transporte, desde una orden de servicio o como viaje directo.','["operaciones-app/src/zahory-mock/pages/transporte/OrdenViajePage.jsx#OrdenViajePage"]'::jsonb,'aa6bbffce0')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('orden_viaje',1,'transporte_comercial',NULL,NULL,'Elige si el viaje parte Desde OS del cliente o es un Viaje directo, y avanza con Siguiente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('orden_viaje',2,'transporte_comercial',NULL,NULL,'Guardar borrador conserva el viaje sin programarlo; Guardar y programar lo deja programado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('orden_viaje',3,'transporte_comercial',NULL,NULL,'Si sales con cambios sin guardar, la pantalla pregunta si quieres Salir o Seguir editando.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('orden_viaje',4,'transporte_comercial',NULL,NULL,'Para qué sirve: la orden de viaje es el encargo de transporte: qué se lleva, de dónde a dónde, para qué cliente, cuándo y a qué precio. Puede nacer de una OS del cliente o registrarse como viaje directo. Cada viaje recibe un código que empieza con TV.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('orden_viaje',5,'transporte_comercial',NULL,NULL,'El asistente tiene cuatro pasos y un resumen al costado. El origen, el destino y las paradas intermedias se eligen del maestro de Lugares; si un lugar no existe se puede crear ahí mismo. Un viaje puede tener varias paradas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('orden_viaje',6,'transporte_comercial',NULL,NULL,'El precio se resuelve solo: si el cliente tiene una tarifa propia para esa ruta se usa esa, y si no, la tarifa base de la ruta. También puedes escribir un precio manual.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('orden_viaje',7,'transporte_comercial',NULL,NULL,'Guardar borrador deja el viaje incompleto para seguir después. Guardar y programar lo deja programado y listo para asignarle unidad y conductor. Un viaje programado ya no vuelve a borrador: se corrige con Guardar cambios.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('ordenes_compra','pantalla','ordenes_compra','Órdenes de compra','Crea y emite órdenes de compra de bienes, registra anticipos, tránsito y recepción, y enlaza la factura del proveedor como cuenta por pagar.','["src/pages_ops.jsx#OrdenesCompra","src/components/EnviarARuta.jsx#EnviarARuta"]'::jsonb,'0fbfbec78b 4ad574d7bf')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_compra',1,'ordenes_compra',NULL,NULL,'Usa Nueva OC para crear una orden: elige proveedor, centro de costo (CECO), sociedad si tu empresa usa varias, y agrega los ítems con cantidad y precio unitario. La pantalla calcula subtotal, IGV y total.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_compra',2,'ordenes_compra',NULL,NULL,'Guardar borrador deja la OC editable. Emitir OC exige proveedor válido, CECO y al menos un ítem con cantidad mayor a cero; si las líneas tienen CECO distintos o sin CECO, reasígnalas antes de emitir.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_compra',3,'ordenes_compra',NULL,NULL,'Una OC emitida se puede Marcar como confirmada cuando el proveedor la acepta. Mientras está en borrador puedes editarla desde su detalle.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_compra',4,'ordenes_compra',NULL,NULL,'En el detalle usa Registrar anticipo para dejar constancia de un pago adelantado al proveedor, con fecha, monto y referencia del pago.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_compra',5,'ordenes_compra',NULL,NULL,'Si la mercadería viaja, registra el tránsito (transportista, vehículo, conductor, guía y fecha de salida); solo se permite con la OC emitida o confirmada. Con la OC emitida, Registrar recepción permite ingresar lo que llegó.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_compra',6,'ordenes_compra',NULL,NULL,'Si el proveedor no entregará un saldo, usa Liberar pendiente en la línea, indica la cantidad y el motivo: esa cantidad vuelve a la Bandeja de Sourcing para comprarla a otro proveedor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_compra',7,'ordenes_compra',NULL,NULL,'Cuando la OC tiene saldo por facturar, Registrar CxP vincula la factura del proveedor a la OC y evita duplicar la deuda; Ver CxP abre las cuentas por pagar ya registradas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_compra',8,'ordenes_compra',NULL,NULL,'Para qué sirve: formalizar la compra con el proveedor: qué se pide, a qué precio, con qué condición de pago y a qué centro de costo se carga. La recepción y la cuenta por pagar se hacen contra esta orden.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_compra',9,'ordenes_compra',NULL,NULL,'Agregar item suma una línea a la orden. Marcar OC como confirmada registra que el proveedor la aceptó. Registrar en transito indica que la mercadería ya viene en camino. Registrar primer anticipo y Nuevo anticipo anotan pagos adelantados al proveedor. Liberar cantidad devuelve a la Bandeja de Sourcing lo que el proveedor no entregará.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_compra',10,'ordenes_compra',NULL,NULL,'No deja emitir una orden sin proveedor, sin al menos un ítem con cantidad mayor a cero o sin centro de costo. Una orden con líneas de centros de costo distintos o sin centro de costo no se puede emitir: guarda el borrador y reasigna las líneas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_compra',11,'ordenes_compra',NULL,NULL,'Enviar a ruta aparece en Tránsito para un recojo propio registrado o en tránsito, si la OC no está recibida totalmente, cerrada ni anulada y no hay pedido activo. Elige Recoger o Entregar, indica lugar, texto para el despachador y día; dirección, horario e indicaciones son opcionales. Enviar a la Hoja de Ruta deja el pedido en Por enviar a ruta para asignación. Retirar está disponible mientras está pendiente.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('ordenes_fabricacion','pantalla','of','Órdenes de Fab. (OF)','Bandeja de las órdenes de fabricación.','["operaciones-app/src/zahory-mock/pages/of/BandejaOFPage.jsx#BandejaOFPage"]'::jsonb,'6f1d2aaebd')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_fabricacion',1,'of',NULL,NULL,'La bandeja lista las órdenes de fabricación; Todas muestra todos los estados y Limpiar filtros quita los filtros.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_fabricacion',2,'of',NULL,NULL,'Nueva OF abre el registro de una orden nueva.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_fabricacion',3,'of',NULL,NULL,'Abre una orden para ver su ruta y sus materiales.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_fabricacion',4,'of',NULL,NULL,'Para qué sirve: ver todas las órdenes de fabricación con su estado, su avance y su fecha de compromiso, para saber cuáles van atrasadas y cuáles vencen pronto.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_fabricacion',5,'of',NULL,NULL,'Los indicadores de arriba (En curso, Borrador, Atrasadas y Vencen en 7 días) filtran la lista al pulsarlos. Cada orden muestra su avance, su costo y si tiene tareas sin bahía asignada.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_fabricacion',6,'of',NULL,NULL,'Si no aparece una orden, usa Todas y Limpiar filtros. Si la bandeja está vacía, las órdenes se crean desde una OS de fabricación o con Nueva OF.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('ordenes_servicio','pantalla','ordenes_servicio','Ordenes de Servicio','Órdenes de servicio a proveedores y su conformidad.','["src/pages_ops.jsx#OrdenesServicio"]'::jsonb,'0144236b2a')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_servicio',1,'ordenes_servicio',NULL,NULL,'Crea una orden con Nueva OS: debes tener seleccionada una sociedad y elegir un CECO, que es obligatorio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_servicio',2,'ordenes_servicio',NULL,NULL,'Emitir OS la emite al proveedor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_servicio',3,'ordenes_servicio',NULL,NULL,'Conformidad registra que el servicio se recibió conforme.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_servicio',4,'ordenes_servicio',NULL,NULL,'Para qué sirve: contratar un servicio a un proveedor (un trabajo de terceros, un flete, una reparación) con su alcance y su precio. Es el equivalente de la orden de compra cuando no llega mercadería sino un trabajo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_servicio',5,'ordenes_servicio',NULL,NULL,'La conformidad reemplaza a la recepción: al registrarla el servicio queda aceptado y puede seguir su cuenta por pagar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ordenes_servicio',6,'ordenes_servicio',NULL,NULL,'No deja crear la orden sin seleccionar una sociedad ni sin elegir un centro de costo. Si no ves Emitir OS, la orden ya está emitida o tu rol no tiene ese permiso.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('ot_admin','pantalla','ot','Ordenes de Trabajo','Órdenes de trabajo desde Administración: tareas, técnicos, costos, partes y cierre.','["src/pages_ops.jsx#OT"]'::jsonb,'00534e2e64')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ot_admin',1,'ot',NULL,NULL,'Dentro de una OT, Agregar tarea o Nueva tarea arma el trabajo y Asignar tecnico define quién lo hace y sirve también para reasignar la OT a otro técnico. Gestionar en Planner lleva a la programación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ot_admin',2,'ot',NULL,NULL,'El estimado de la OT se arma con Agregar material, Agregar servicio de tercero y Agregar gasto logístico; Importar desde HC trae la Hoja de Costeo como estimado editable, que debes revisar y guardar con Guardar estimado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ot_admin',3,'ot',NULL,NULL,'Iniciar OT comienza el trabajo. Para registrar un parte con Registrar Parte Diario debe existir al menos una tarea.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ot_admin',4,'ot',NULL,NULL,'Los partes se envían con Enviar a revisión; quien revisa usa Aprobar, Observar o Rechazar, y Reabrir para editar devuelve un parte ya revisado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ot_admin',5,'ot',NULL,NULL,'Guardar costos reales y Recalcular costo real actualizan el costo real de la OT. Registrar Incidente deja constancia de un incidente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ot_admin',6,'ot',NULL,NULL,'Abrir en Operaciones y Cerrar en Operaciones llevan a la aplicación de Operaciones, donde se cierra la OT. Anular OT la deja sin efecto y pide confirmación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ot_admin',7,'ot',NULL,NULL,'Para qué sirve: es la vista de Administración de las órdenes de trabajo: su plan, su estimado, sus partes y lo que realmente costó. Sirve para comparar lo estimado con lo real y decidir si el trabajo fue rentable.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ot_admin',8,'ot',NULL,NULL,'Nuevo parte diario abre un parte: Agregar actividad suma una tarea trabajada, Agregar ítem un material o gasto, y Guardar borrador lo conserva sin enviar. Actualizar avance cambia el avance de una tarea y exige una nota. Cada decisión sobre un parte se confirma con Confirmar aprobación, Confirmar rechazo o Confirmar reapertura; Observar se envía con Enviar observación. «Enviar con restricción» manda el parte aunque tenga una advertencia pendiente. Ver cierre técnico abre el cierre de una OT terminada. Quitar participante administrativo retira del parte a una persona de apoyo. Completar marca una tarea como terminada, Restablecer devuelve el estimado a su valor anterior y «Sí, anular» confirma la anulación de la OT.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('ot_admin',9,'ot',NULL,NULL,'No deja registrar un parte si la OT no tiene al menos una tarea. Si no ves Aprobar, Observar o Rechazar, tu rol no tiene el permiso de aprobar partes. Si el costo real no cuadra, usa Recalcular costo real: solo cuentan los partes aprobados.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('organigrama','pantalla','organigrama','Organigrama','Estructura de la empresa: unidades, cargos y posiciones, con el rol que recibe cada posición.','["src/pages_organigrama_v2.jsx#OrganigramaV2Page"]'::jsonb,'c1965a30ee')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('organigrama',1,'organigrama',NULL,NULL,'Crea las áreas con Nueva unidad organizacional y elige su nivel.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('organigrama',2,'organigrama',NULL,NULL,'Dentro de una unidad defines el cargo y la cantidad de posiciones; al guardar se crean sus sillas vacantes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('organigrama',3,'organigrama',NULL,NULL,'Cada posición lleva un rol sugerido, que puedes editar, y los módulos de campo habilitados para la aplicación móvil.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('organigrama',4,'organigrama',NULL,NULL,'Al guardar un cambio de rol o de módulos, se aplica a las personas que ocupan esa posición.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('organigrama',5,'organigrama',NULL,NULL,'Eliminar cargo retira un cargo del organigrama.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('organigrama',6,'organigrama',NULL,NULL,'Para qué sirve: dibujar cómo está organizada la empresa: unidades, cargos y posiciones, y quién reporta a quién. De aquí salen el rol de cada persona en el sistema y su jefe directo, que se usa en aprobaciones y avisos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('organigrama',7,'organigrama',NULL,NULL,'Nueva UO y Crear UO agregan una unidad organizativa. Crear cargo y posiciones crea un cargo dentro de una unidad con sus puestos; si las posiciones no se generaron, Reintentar generar posiciones lo vuelve a intentar. Guardar cambios conserva la edición.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('organigrama',8,'organigrama',NULL,NULL,'Eliminar una unidad o un cargo es permanente y borra también sus posiciones vacantes; la pantalla pide confirmarlo. Si no ves a una persona con el acceso esperado, revisa que su posición tenga un rol de sistema asignado.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('os_cliente','pantalla','os_cliente','OS Cliente','Órdenes de servicio del cliente: alcance aprobado, órdenes de trabajo, valorizaciones y cierre.','["src/pages_core.jsx#OSCliente"]'::jsonb,'90315ca39a')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('os_cliente',1,'os_cliente',NULL,NULL,'Crea una orden con Nueva OS. Vincular cotización la relaciona con una cotización aprobada e Importar desde cotización trae sus partidas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('os_cliente',2,'os_cliente',NULL,NULL,'Crea el trabajo con Crear OT, o con Crear OF si es fabricación. La OS debe tener CEBE asignado, y cada OT un servicio y un centro de costo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('os_cliente',3,'os_cliente',NULL,NULL,'Registra lo facturable con Nueva valorización. Agregar hito define los hitos de pago de la orden.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('os_cliente',4,'os_cliente',NULL,NULL,'Para un servicio recurrente elige el cobro mensual e indica la tarifa mensual sin IGV y la fecha de inicio: la primera OT la creas tú y luego se crea sola el día 1 de cada mes. El filtro Cobro mensual muestra solo estas órdenes.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('os_cliente',5,'os_cliente',NULL,NULL,'Pausar OS detiene la orden y Reactivar OS la retoma. Cerrar OS la termina y Anular OS la deja sin efecto. Abrir en Operaciones lleva a la orden de trabajo en la aplicación de Operaciones.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('os_cliente',6,'os_cliente',NULL,NULL,'Para qué sirve: es el pedido confirmado del cliente. Reúne lo que se aprobó en la cotización, las órdenes de trabajo o de fabricación que lo ejecutan, lo que se valoriza y lo que falta facturar. Todo trabajo para un cliente cuelga de su OS.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('os_cliente',7,'os_cliente',NULL,NULL,'Crear OS guarda la orden nueva. Nueva OT y Agregar OT preparan una o varias órdenes de trabajo, y Nueva OF una de fabricación. Ver cotización y Ver cotización especial abren el documento de origen; Desvincular quita la cotización ligada. En repuestos con número de parte, Usar original y Usar promedio alternos eligen el precio referencial, y detallar despliega el detalle. Guardar y seleccionar crea un dato y lo deja elegido. Más acciones reúne lo menos frecuente y Eliminar OS borra una orden sin registros. Limpiar filtros quita los filtros.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('os_cliente',8,'os_cliente',NULL,NULL,'No deja crear OT si la OS no tiene CEBE asignado, o si alguna OT va sin CECO o sin servicio. Si la OS es de otra sociedad, Cambiar a te pasa a esa sociedad; solo aparece si tu rol tiene acceso a ella. No deja eliminar una OS que ya tiene OT, valorizaciones o facturas: en ese caso se anula.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('panel_flota','pantalla','flota_panel','Panel de Flota','Equipos de la flota, su estado y su despacho o recepción.','["operaciones-app/src/zahory-mock/pages/flota/FlotaPanelPage.jsx#FlotaPanelPage"]'::jsonb,'a4bc77e2dd')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('panel_flota',1,'flota_panel',NULL,NULL,'Registrar equipo da de alta un equipo de la flota.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('panel_flota',2,'flota_panel',NULL,NULL,'Despachar equipo inicia la entrega de un equipo y Recibir equipo su devolución; ambos requieren acceso a Actas & Despachos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('panel_flota',3,'flota_panel',NULL,NULL,'Para qué sirve: ver de un vistazo toda la flota: qué equipos están disponibles, cuáles alquilados y cuáles en mantenimiento, y desde ahí despachar o recibir un equipo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('panel_flota',4,'flota_panel',NULL,NULL,'Despachar y recibir se hacen con un acta: el panel solo abre el acta con el equipo ya elegido.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('panel_flota',5,'flota_panel',NULL,NULL,'Si no ves Despachar equipo o Recibir equipo, tu rol no tiene acceso a Actas & Despachos. Si no deja despachar, el equipo tiene una certificación obligatoria vencida o no tiene un contrato vigente.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('panel_produccion','pantalla','os_cliente','Panel de Producción','Tablero de las órdenes de servicio en producción y sus atrasos.','["src/pages_produccion_os_cliente.jsx#PanelProduccionOSCliente"]'::jsonb,'25f708de95')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('panel_produccion',1,'os_cliente',NULL,NULL,'Muestra las OS Cliente en Tablero o en Lista. Solo atrasadas filtra las que están fuera de plazo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('panel_produccion',2,'os_cliente',NULL,NULL,'Nueva OS Cliente crea una orden: cliente y descripción son obligatorios y debes seleccionar o crear un activo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('panel_produccion',3,'os_cliente',NULL,NULL,'Recepciones e Ir a Recepción de Activos llevan al ingreso de equipos al taller.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('panel_produccion',4,'os_cliente',NULL,NULL,'Una OS con registros asociados no se puede eliminar.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('panel_produccion',5,'os_cliente',NULL,NULL,'Para qué sirve: ver de un vistazo todas las órdenes de servicio en curso, en qué etapa va cada una y cuáles están atrasadas, para priorizar el taller.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('panel_produccion',6,'os_cliente',NULL,NULL,'El indicador Atrasadas filtra al pulsarlo y Quitar filtros vuelve a mostrar todo. Guardar OS Cliente conserva la orden nueva o editada.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('panel_produccion',7,'os_cliente',NULL,NULL,'Si no ves una OS en el tablero, revisa Quitar filtros y que la orden no esté cerrada o anulada.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('parametros','pantalla','parametros','Parametros Generales','Configuración general de la empresa: sociedades, series, cuentas bancarias, tipo de cambio, feriados y nómina.','["src/pages_admin.jsx#Parametros"]'::jsonb,'980cef576e')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('parametros',1,'parametros',NULL,NULL,'Nueva sociedad registra cada sociedad de la empresa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('parametros',2,'parametros',NULL,NULL,'Las series de los documentos se crean con Agregar serie indicando documento y serie, y las cuentas bancarias con Agregar cuenta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('parametros',3,'parametros',NULL,NULL,'Guardar TC registra el tipo de cambio; Actualizar ahora lo trae de la fuente externa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('parametros',4,'parametros',NULL,NULL,'Agregar feriado suma un feriado con su fecha y su nombre.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('parametros',5,'parametros',NULL,NULL,'Las secciones de nómina y de evaluaciones guardan sus propios parámetros, entre ellos las tasas de AFP con Editar tasa AFP.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('parametros',6,'parametros',NULL,NULL,'Para qué sirve: reunir la configuración base de la empresa, la que se define una vez y usan todos los módulos: sociedades, series de comprobantes, cuentas bancarias, tipo de cambio, feriados y reglas de nómina y de evaluaciones.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('parametros',7,'parametros',NULL,NULL,'Guardar sociedad conserva una sociedad e Ir a Sociedades lleva a esa pestaña. Guardar feriado y Eliminar feriado mantienen el calendario, e Ir a Feriados lleva a él. La carga por Excel usa Descargar plantilla y Confirmar e importar. Guardar configuración de nómina y Guardar configuracion de evaluaciones conservan esas reglas. Actualizar SLA guarda una plantilla de tiempos de atención. En el diccionario de términos, que cambia cómo se nombran las cosas en tu empresa, Actualizar frase guarda un texto, Restablecer lo devuelve a su nombre original y Ocultar overrides esconde los ya cambiados. Desactivar apaga una categoría sin borrarla y Guardar cambios conserva cada edición.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('parametros',8,'parametros',NULL,NULL,'No deja guardar una serie sin documento y serie, ni una entrada del diccionario sin clave y texto. Si no aparece una cuenta bancaria al cobrar o pagar, créala aquí y asígnale su sociedad. Si no ves esta pantalla, tu rol no tiene acceso a Parámetros.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('partes','pantalla','partes','Partes Diarios','Revisión y aprobación de los partes diarios de trabajo.','["src/pages_ops.jsx#Partes"]'::jsonb,'294d071ef7')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes',1,'partes',NULL,NULL,'La lista muestra los partes diarios registrados; Limpiar quita los filtros.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes',2,'partes',NULL,NULL,'Enviar a revisión manda un parte a su revisor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes',3,'partes',NULL,NULL,'Quien revisa usa Aprobar, Observar, que envía una observación al autor, o Rechazar; cada acción pide confirmación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes',4,'partes',NULL,NULL,'Reabrir para editar devuelve un parte ya revisado para corregirlo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes',5,'partes',NULL,NULL,'Para qué sirve: revisar desde Administración los partes de trabajo que registran los técnicos. Solo los partes aprobados suman horas y costo a su orden de trabajo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes',6,'partes',NULL,NULL,'Cada decisión se confirma en una ventana: Confirmar aprobación, Confirmar rechazo o Confirmar reapertura; Observar pide escribir la observación y enviarla con Enviar observación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes',7,'partes',NULL,NULL,'Si no ves Aprobar, Observar o Rechazar, tu rol no tiene el permiso de aprobar partes. Si no aparece un parte, revisa los filtros y que el técnico lo haya enviado a revisión.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('partes_taller','pantalla','partes','Parte diario de taller','Registra el trabajo diario del técnico sobre una OT: actividades, fotos, hallazgos y repuestos, y lo envía a revisión.','["operaciones-app/src/zahory-mock/pages/pages3.jsx#ParteTallerPage"]'::jsonb,'a7974170a2')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes_taller',1,'partes',NULL,NULL,'Elige la OT (programada o en ejecución), el técnico y la fecha del parte.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes_taller',2,'partes',NULL,NULL,'Agrega cada actividad realizada con su tiempo; puedes adjuntar fotos y usar Dictar por voz para describirla.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes_taller',3,'partes',NULL,NULL,'Reportar hallazgo adicional registra un problema encontrado durante el trabajo. Agrega los repuestos usados o pide los que faltan; si el pedido falla, usa Reintentar pedido de repuestos.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes_taller',4,'partes',NULL,NULL,'Guardar borrador conserva el parte para seguirlo luego. Enviar a revisión exige al menos una actividad y deja el parte en revisión del supervisor.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes_taller',5,'partes',NULL,NULL,'El parte es la base del avance y del costo real de la OT: las horas del parte por la tarifa del técnico se suman al costo real cuando el parte queda aprobado. Un parte en borrador o en revisión todavía no cuenta.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes_taller',6,'partes',NULL,NULL,'Ciclo del parte: Borrador → En revisión → Aprobado. Quien revisa puede Aprobar (confirma el avance), Observar (lo devuelve para corregir, con motivo obligatorio) o Rechazar (con motivo obligatorio). Un parte aprobado se corrige solo si quien aprueba usa Reabrir para editar e indica el motivo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes_taller',7,'partes',NULL,NULL,'Si no puedes registrar el parte: la OT debe estar programada o en ejecución y tener al menos una tarea; si no aparece en la lista, pide al jefe de taller que la inicie o le agregue tareas.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes_taller',8,'partes',NULL,NULL,'Cada parte corresponde a un técnico, una OT y una fecha. Si el trabajo siguió al día siguiente, se hace otro parte con esa fecha.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes_taller',9,'partes',NULL,NULL,'Para qué sirve: que el técnico deje constancia de lo que hizo cada día en una orden: horas, actividades, fotos, lo que encontró y los repuestos que usó. Es la base del avance y del costo real de la OT.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('partes_taller',10,'partes',NULL,NULL,'Agregar actividad suma una tarea trabajada con sus horas. Agregar repuesto anota un repuesto usado. Al registrar un hallazgo eliges su tipo, Mecánico o Eléctrico, y Guardar hallazgo lo conserva para que se atienda después.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('pasaporte_equipos','pantalla','pasaporte_equipos','Pasaporte de Equipos','Documentos de cada equipo de la flota.','["operaciones-app/src/zahory-mock/pages/flota/PasaporteEquiposPage.jsx#PasaporteEquiposPage"]'::jsonb,'94e691e9d6')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('pasaporte_equipos',1,'pasaporte_equipos',NULL,NULL,'Selecciona un equipo para desplazarte a su ficha y usa Agregar documento para registrar un documento suyo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('pasaporte_equipos',2,'pasaporte_equipos',NULL,NULL,'Editar cambia los datos del documento. Para cambiar el archivo hay que eliminar el documento y volver a registrarlo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('pasaporte_equipos',3,'pasaporte_equipos',NULL,NULL,'Eliminar abre una confirmación con el nombre del documento; usa Eliminar documento para borrarlo o Cancelar para conservarlo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('pasaporte_equipos',4,'pasaporte_equipos',NULL,NULL,'Para qué sirve: guardar en un solo lugar los documentos de cada equipo (manuales, fichas técnicas, tarjetas de propiedad, informes) para tenerlos a mano en una auditoría o al entregar el equipo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('pasaporte_equipos',5,'pasaporte_equipos',NULL,NULL,'Guardar documento registra el archivo en la ficha del equipo elegido.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('pasaporte_equipos',6,'pasaporte_equipos',NULL,NULL,'No deja guardar un documento sin seleccionar el equipo. Si no aparece un equipo, primero debe registrarse en el Panel de Flota. Los documentos con vencimiento (SOAT, pólizas) van en Certificaciones del Activo, no aquí.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('rrhh_admin','pantalla','rrhh_admin','Personal Administrativo','Ficha del personal administrativo: datos, contratos, jornada, documentos y amonestaciones.','["src/pages_admin.jsx#RRHHAdmin"]'::jsonb,'2883372074')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',1,'rrhh_admin',NULL,NULL,'Registra a un trabajador con Nuevo colaborador; Importar Excel carga varios a la vez con la plantilla. Al crearlo, la pantalla recuerda subir el contrato firmado para activar las alertas de vencimiento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',2,'rrhh_admin',NULL,NULL,'Nuevo contrato registra su contrato y Renovar lo renueva. El contrato se puede enviar con Enviar a firma del trabajador y firmar con Firmar como empresa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',3,'rrhh_admin',NULL,NULL,'Asignar jornada define su horario y Asignar cargo su puesto. Agregar cuenta registra sus datos bancarios.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',4,'rrhh_admin',NULL,NULL,'Sube sus documentos en la ficha; Archivar documento lo conserva pero deja de estar vigente. Configurar requisitos define qué documentos se exigen.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',5,'rrhh_admin',NULL,NULL,'Registrar amonestación deja constancia de una sanción; si el trabajador no tiene usuario de sistema, se le notifica por medios físicos y se adjunta el cargo firmado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',6,'rrhh_admin',NULL,NULL,'Renovar con firma digital (en el contrato del trabajador) renueva sin papel: eliges la plantilla publicada, la modalidad, las fechas de inicio y fin, la causa objetiva, la remuneración base y el firmante de la empresa. Si la fecha de inicio es anterior a hoy, la pantalla avisa pero no bloquea.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',7,'rrhh_admin',NULL,NULL,'Orden de la firma digital: primero firma la empresa (el firmante recibe un código en el correo personal de su ficha), luego el sistema envía solo el enlace al trabajador, que firma con su propio código. Al completarse las dos firmas el contrato queda aprobado automáticamente y el PDF lleva las dos constancias.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',8,'rrhh_admin',NULL,NULL,'Un contrato firmado por ambas partes queda protegido: no se puede modificar ni eliminar. Renovar con firma digital no aparece en contratos históricos, en adendas ni cuando el contrato ya tiene una renovación aprobada.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',9,'rrhh_admin',NULL,NULL,'Antes de la primera renovación digital, el firmante de la empresa debe estar registrado en Firmantes de contratos y tener correo personal en su ficha; el trabajador también necesita correo personal. Hoy el enlace y el código llegan por correo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',10,'rrhh_admin',NULL,NULL,'Se puede renovar por adelantado: el contrato actual sigue vigente hasta su fin y la ficha muestra el siguiente como «Próximo · desde». Un trabajador con renovación aprobada que empalma con su contrato ya no aparece en «Contratos por vencer».');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',11,'rrhh_admin',NULL,NULL,'Sin contrato o adenda vigente en la fecha, el sistema no deja registrar asistencia de ese trabajador. Si alguien no puede marcar, revisa primero la vigencia de su contrato.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',12,'rrhh_admin',NULL,NULL,'Para qué sirve: es el legajo de cada trabajador administrativo: sus datos, su cargo, su sueldo, su contrato, sus documentos, su jornada y sus cuentas. De aquí toman sus datos la planilla, la asistencia, el costeo de la mano de obra y los avisos de vencimiento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',13,'rrhh_admin',NULL,NULL,'Ficha: Editar colaborador abre los datos del trabajador y Guardar cambios los conserva; Más acciones reúne lo menos frecuente y Reportes los reportes del personal. Eliminar colaborador borra al trabajador y pide confirmación; si ya tiene historial, lo correcto es darlo de baja. Crear guarda un registro nuevo y Gestionar abre un catálogo relacionado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',14,'rrhh_admin',NULL,NULL,'Carga masiva: Descargar plantilla baja el Excel con el formato y Descargar plantilla vacía uno sin datos de ejemplo; Importar Excel lo carga e Importar registros válidos crea los que pasaron la revisión.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',15,'rrhh_admin',NULL,NULL,'Documentos: Subir documento carga un archivo del trabajador y Documento adicional uno que no está en sus requisitos; Ver archivo lo abre. Ver documentos pendientes muestra los que esperan revisión; RRHH los aprueba o usa Rechazar, que se confirma con Confirmar rechazo. Para borrar, Eliminar definitivamente lo quita; si el documento tiene dependencias, firma iniciada o ya se usó en nómina, el sistema rechaza el borrado y ofrece Archivar en su lugar. «Forzar eliminación (requiere autorización)» exige escribir la justificación.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',16,'rrhh_admin',NULL,NULL,'Contrato y firma: Subir contrato carga el contrato firmado en papel y Ver contrato lo abre. Mientras se espera la firma del trabajador, Reenviar enlace y Reenviar aviso le vuelven a mandar el correo y Cancelar envío detiene el proceso. Anular solicitud deja sin efecto el pedido de firma y Anular firma de la empresa retira la firma ya puesta; ambas piden Confirmar anulación. Ver PDF firmado abre el contrato con las dos firmas. Anular deja sin efecto un registro y pide su motivo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',17,'rrhh_admin',NULL,NULL,'Jornada y costo: Nueva asignación le asigna un turno y Guardar asignación lo conserva; Usar turno toma las horas base del mes del turno elegido. Si el cambio choca con una regla, «Forzar cambio (requiere autorización)» lo aplica con autorización. En el costo extra, Usar sugerido vuelve al valor calculado automáticamente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',18,'rrhh_admin',NULL,NULL,'Tipos de documento: desde aquí se llega al catálogo con Tipos de Documento, y a los documentos que exige cada cargo con Requisitos por Cargo; los marcados «req.» son obligatorios e Ir a Tipos de Documento vuelve al catálogo. Nuevo tipo de documento y Guardar Tipo crean un tipo, e Importar Plantilla Base o Importar tipos traen una lista.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_admin',19,'rrhh_admin',NULL,NULL,'Si no puedes registrar o editar, tu rol no tiene ese permiso en esta pantalla. Si no aparece un trabajador, revisa el filtro de estado: los dados de baja no salen en la lista de activos. No deja renovar con firma digital si el trabajador o el firmante de la empresa no tienen correo personal en su ficha. Si un documento no aparece para subirlo, falta definir su tipo o marcarlo como requisito del cargo.');
INSERT INTO public.asistente_manual_fichas (clave,tipo,pantalla_key,titulo,resumen,fuentes,revision) VALUES ('rrhh_operativo','pantalla','rrhh_operativo','Personal Operativo','Ficha del personal operativo: datos, contratos, jornada, documentos y amonestaciones.','["src/pages_ops.jsx#RRHH_Operativo"]'::jsonb,'8339f61f9c')
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',1,'rrhh_operativo',NULL,NULL,'Registra a un trabajador con Nuevo Colaborador; Carga masiva registra a varios desde un archivo y Descargar Excel exporta la lista.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',2,'rrhh_operativo',NULL,NULL,'Nuevo contrato registra su contrato y Renovar lo renueva. El contrato se puede enviar con Enviar a firma del trabajador y firmar con Firmar como empresa.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',3,'rrhh_operativo',NULL,NULL,'Asignar jornada define su horario y Agregar cuenta registra sus datos bancarios.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',4,'rrhh_operativo',NULL,NULL,'Un documento subido queda pendiente de aprobación por RRHH. Archivar documento lo conserva pero deja de estar vigente.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',5,'rrhh_operativo',NULL,NULL,'Registrar amonestación deja constancia de una sanción; el motivo es obligatorio.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',6,'rrhh_operativo',NULL,NULL,'Renovar con firma digital (en el contrato del trabajador) renueva sin papel: eliges la plantilla publicada, la modalidad, las fechas de inicio y fin, la causa objetiva, la remuneración base y el firmante de la empresa. Si la fecha de inicio es anterior a hoy, la pantalla avisa pero no bloquea.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',7,'rrhh_operativo',NULL,NULL,'Orden de la firma digital: primero firma la empresa (el firmante recibe un código en el correo personal de su ficha), luego el sistema envía solo el enlace al trabajador, que firma con su propio código. Al completarse las dos firmas el contrato queda aprobado automáticamente y el PDF lleva las dos constancias.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',8,'rrhh_operativo',NULL,NULL,'Un contrato firmado por ambas partes queda protegido: no se puede modificar ni eliminar. Renovar con firma digital no aparece en contratos históricos, en adendas ni cuando el contrato ya tiene una renovación aprobada.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',9,'rrhh_operativo',NULL,NULL,'Antes de la primera renovación digital, el firmante de la empresa debe estar registrado en Firmantes de contratos y tener correo personal en su ficha; el trabajador también necesita correo personal. Hoy el enlace y el código llegan por correo.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',10,'rrhh_operativo',NULL,NULL,'Se puede renovar por adelantado: el contrato actual sigue vigente hasta su fin y la ficha muestra el siguiente como «Próximo · desde». Un trabajador con renovación aprobada que empalma con su contrato ya no aparece en «Contratos por vencer».');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',11,'rrhh_operativo',NULL,NULL,'Sin contrato o adenda vigente en la fecha, el sistema no deja registrar asistencia de ese trabajador. Si alguien no puede marcar, revisa primero la vigencia de su contrato.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',12,'rrhh_operativo',NULL,NULL,'Para qué sirve: es el legajo de cada trabajador operativo (técnicos y personal de campo): sus datos, su cargo, su sueldo, su contrato, sus documentos, su jornada y sus cuentas. De aquí toman sus datos la planilla, la asistencia, el costeo de la mano de obra y los avisos de vencimiento.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',13,'rrhh_operativo',NULL,NULL,'Ficha: Editar ficha abre los datos del trabajador y Actualizar tecnico los conserva; Más acciones reúne lo menos frecuente y Reportes los reportes del personal. Eliminar técnico borra al trabajador y pide confirmación; si ya tiene historial, lo correcto es darlo de baja. Crear guarda un registro nuevo y Gestionar abre un catálogo relacionado.');
INSERT INTO public.asistente_manual_pasos (ficha_clave,orden,pantalla_key,permiso_pantalla,permiso_accion,texto) VALUES ('rrhh_operativo',14,'rrhh_operativo',NULL,NULL,'Carga masiva: Descargar plantilla baja el Excel con el formato y Descargar plantilla vacía uno sin datos de ejemplo; Importar Excel lo carga e Importar registros válidos crea los que pasaron la revisión.');
